-- Local database seed: source-backed vocabulary/Kanji plus sample learning content.
-- No real/demo frontend passwords are reused. Hash is a non-login placeholder;
-- replace through the future backend's password-hashing service before login.
SET NAMES utf8mb4;
USE nihongo_learning;

INSERT INTO roles (id, name) VALUES
  (1, 'user'),
  (2, 'admin')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO users (id, role_id, full_name, username, email, password_hash) VALUES
  (1, 1, 'Sample Learner', 'sample_learner', 'learner@example.invalid', '$2b$12$REPLACE_WITH_BACKEND_GENERATED_BCRYPT_HASH'),
  (2, 2, 'Sample Admin', 'sample_admin', 'admin@example.invalid', '$2b$12$REPLACE_WITH_BACKEND_GENERATED_BCRYPT_HASH')
ON DUPLICATE KEY UPDATE full_name = VALUES(full_name), role_id = VALUES(role_id);

INSERT INTO vocabulary (id, source_key, word, reading, romaji, level, jmdict_id) VALUES
  (1, 'sample-n5-001', '日本', 'にほん', 'nihon', 'N5', NULL)
ON DUPLICATE KEY UPDATE word = VALUES(word), reading = VALUES(reading);

INSERT INTO vocabulary_meanings (vocabulary_id, language_code, meaning, sort_order) VALUES
  (1, 'en', 'Japan', 1),
  (1, 'vi', 'Nhật Bản (nghĩa mẫu)', 1)
ON DUPLICATE KEY UPDATE meaning = VALUES(meaning);

INSERT INTO vocabulary_examples (id, vocabulary_id, japanese_text, furigana, meaning_vi, meaning_en) VALUES
  (1, 1, '日本へ行きます。', '日本{にほん}へ行{い}きます。', 'Tôi đi Nhật Bản.', 'I am going to Japan.')
ON DUPLICATE KEY UPDATE japanese_text=VALUES(japanese_text), furigana=VALUES(furigana),
  meaning_vi=VALUES(meaning_vi), meaning_en=VALUES(meaning_en);

INSERT INTO kanji (id, source_id, `character`, han_viet, meaning, jlpt_level, stroke_count) VALUES
  (1, 1, '日', 'Nhật', 'Mặt trời; ngày', 'N5', 4)
ON DUPLICATE KEY UPDATE meaning = VALUES(meaning), stroke_count = VALUES(stroke_count);

INSERT INTO kanji_readings (kanji_id, reading_type, reading, sort_order) VALUES
  (1, 'kun', 'ひ', 1),
  (1, 'on', 'ニチ', 1)
ON DUPLICATE KEY UPDATE reading = VALUES(reading);

INSERT INTO radicals (`character`) VALUES ('日')
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id);
SET @sample_radical_id = LAST_INSERT_ID();

INSERT INTO kanji_radicals (kanji_id, radical_id) VALUES (1, @sample_radical_id)
ON DUPLICATE KEY UPDATE radical_id = VALUES(radical_id);

INSERT INTO kanji_vocabulary (kanji_id, vocabulary_id) VALUES (1, 1)
ON DUPLICATE KEY UPDATE vocabulary_id = VALUES(vocabulary_id);

INSERT INTO lessons (id, title, level, duration, summary, objectives) VALUES
  (1, 'Làm quen với lời chào', 'N5', '15 phút', 'Bài học mẫu để kiểm tra liên kết tiến độ.', 'Nhận biết một số lời chào cơ bản.')
ON DUPLICATE KEY UPDATE title=VALUES(title), level=VALUES(level), duration=VALUES(duration),
  summary=VALUES(summary), objectives=VALUES(objectives);

INSERT INTO grammar_points (id, title, level, form, meaning, structure) VALUES
  (1, 'Câu danh từ đơn giản', 'N5', 'N は N です', 'Diễn đạt “A là B”.', 'Danh từ + は + danh từ + です')
ON DUPLICATE KEY UPDATE title=VALUES(title), level=VALUES(level), form=VALUES(form),
  meaning=VALUES(meaning), structure=VALUES(structure);

INSERT INTO grammar_examples (id, grammar_point_id, japanese_text, reading, meaning_vi, meaning_en, sort_order) VALUES
  (1, 1, '私は学生です。', 'わたしはがくせいです。', 'Tôi là học sinh/sinh viên.', 'I am a student.', 1)
ON DUPLICATE KEY UPDATE japanese_text=VALUES(japanese_text), reading=VALUES(reading),
  meaning_vi=VALUES(meaning_vi), meaning_en=VALUES(meaning_en), sort_order=VALUES(sort_order);

INSERT INTO exercises (id, title, level, topic, question_count, description) VALUES
  (1, 'Kiểm tra từ vựng N5 mẫu', 'N5', 'Từ vựng', 1, 'Bài kiểm tra mẫu dùng để xác nhận lưu nhiều lần làm bài.')
ON DUPLICATE KEY UPDATE title=VALUES(title), level=VALUES(level), topic=VALUES(topic),
  question_count=VALUES(question_count), description=VALUES(description);

INSERT INTO exercise_questions (id, exercise_id, question_text, question_type, sort_order) VALUES
  (1, 1, '日本 có nghĩa là gì?', 'multiple_choice', 1)
ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), question_type=VALUES(question_type);

INSERT INTO exercise_choices (id, question_id, choice_text, is_correct, sort_order) VALUES
  (1, 1, 'Nhật Bản', TRUE, 1),
  (2, 1, 'Việt Nam', FALSE, 2)
ON DUPLICATE KEY UPDATE choice_text=VALUES(choice_text), is_correct=VALUES(is_correct);

INSERT INTO lesson_progress (user_id, lesson_id, status, started_at, completed_at) VALUES
  (1, 1, 'completed', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE status = VALUES(status), completed_at = VALUES(completed_at);

INSERT INTO exercise_attempts (id, user_id, exercise_id, attempt_number, score, correct_count, total_questions, started_at, completed_at) VALUES
  (1, 1, 1, 1, 100.00, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  (2, 1, 1, 2, 0.00, 0, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE score = VALUES(score), correct_count = VALUES(correct_count);

INSERT INTO exercise_attempt_answers (attempt_id, question_id, selected_choice_id, answer_text, is_correct) VALUES
  (1, 1, 1, NULL, TRUE),
  (2, 1, 2, NULL, FALSE)
ON DUPLICATE KEY UPDATE selected_choice_id = VALUES(selected_choice_id), is_correct = VALUES(is_correct);

INSERT INTO user_learning_stats (user_id, level, completed_lessons, accuracy, streak_days, last_active_at) VALUES
  (1, 'N5', 1, 50.00, 2, CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE completed_lessons = VALUES(completed_lessons), accuracy = VALUES(accuracy);

INSERT INTO data_sources (id, name, source_url, source_file, source_version, license, notes) VALUES
  (1, 'OpenJLPT', 'https://github.com/evanclan/OpenJLPT', 'data/vocabulary.json', '0.3.0', 'CC BY-SA 4.0', 'Nguồn từ vựng N5; meaning_vi trống nếu chưa được xác minh.')
ON DUPLICATE KEY UPDATE source_url = VALUES(source_url), license = VALUES(license);

-- Full OpenJLPT vocabulary and project Kanji datasets; source data is in data/*.json.
-- Child rows are rebuilt for these source keys so this section can be rerun safely.
DROP TEMPORARY TABLE IF EXISTS seed_vocab, seed_vocab_meanings, seed_vocab_pos, seed_vocab_forms, seed_vocab_examples, seed_kanji, seed_kanji_readings, seed_kanji_radicals, seed_kanji_vocab;
CREATE TEMPORARY TABLE seed_vocab (source_key VARCHAR(64) PRIMARY KEY, word VARCHAR(255) NOT NULL, reading VARCHAR(255) NOT NULL, romaji VARCHAR(255) NULL, level ENUM('N5','N4','N3','N2','N1') NOT NULL, jmdict_id BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_vocab_meanings (source_key VARCHAR(64) NOT NULL, language_code CHAR(2) NOT NULL, meaning VARCHAR(1000) NOT NULL, sort_order SMALLINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_vocab_pos (source_key VARCHAR(64) NOT NULL, code VARCHAR(32) NULL, label VARCHAR(160) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_vocab_forms (source_key VARCHAR(64) NOT NULL, form_type ENUM('other_form','other_reading') NOT NULL, value VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_vocab_examples (source_key VARCHAR(64) NOT NULL, japanese_text TEXT NOT NULL, furigana TEXT NULL, meaning_vi TEXT NULL, meaning_en TEXT NULL, tatoeba_id BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_kanji (source_id BIGINT UNSIGNED PRIMARY KEY, `character` VARCHAR(8) NOT NULL, han_viet VARCHAR(120) NULL, meaning VARCHAR(1000) NOT NULL, jlpt_level ENUM('N5','N4','N3','N2','N1') NOT NULL, stroke_count SMALLINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_kanji_readings (source_id BIGINT UNSIGNED NOT NULL, reading_type ENUM('kun','on') NOT NULL, reading VARCHAR(255) NOT NULL, sort_order SMALLINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_kanji_radicals (source_id BIGINT UNSIGNED NOT NULL, radical_character VARCHAR(16) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE seed_kanji_vocab (source_id BIGINT UNSIGNED NOT NULL, source_key VARCHAR(64) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
