INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-ada066edfd', 'もうスミスさんに会われましたね。', 'もうスミスさんに{会|あ}われましたね。', NULL, 'You''ve met Mr. Smith already, haven''t you?', 194412),
  ('n5-ada066edfd', 'じゃあパーティーで会いましょう。', 'じゃあパーティーで{会|あ}いましょう。', NULL, 'See you at the party.', 215904),
  ('n5-ebec658463', '信号が青に変わったわよ。', '{信号|しんごう}が{青|あお}に{変|か}わったわよ。', NULL, 'The traffic light turned green.', 145720),
  ('n5-ebec658463', '夏の通学服は白と青のチェックです。', NULL, NULL, 'My summer school dress is blue and white checkered.', 187219),
  ('n5-51a671ec17', 'お前はまだ「青い」な。', 'お{前|まえ}はまだ「{青|あお}い」な。', NULL, 'You''re still green.', 226939),
  ('n5-51a671ec17', 'なぜ空が青いか知っているか。', 'なぜ{空|そら}が{青|あお}いか{知|し}っているか。', NULL, 'Do you know why the sky is blue?', 199202),
  ('n5-2dacb910b2', '赤インクで書いてはいけない。', '{赤|あか}インクで{書|か}いてはいけない。', NULL, 'Don''t write in red ink.', 142280),
  ('n5-2dacb910b2', 'その家は赤レンガづくりです。', 'その{家|いえ}は{赤|あか}レンガづくりです。', NULL, 'The house is built of red bricks.', 212071),
  ('n5-44ba38cf8b', '彼女は赤いスカートをはいていた。', '{彼女|かのじょ}は{赤|あか}いスカートをはいていた。', NULL, 'She was wearing a red skirt.', 88306),
  ('n5-44ba38cf8b', '赤いものもあれば白いのもある。', '{赤|あか}いものもあれば{白|しろ}いのもある。', NULL, 'Some are red and others are white.', 142281),
  ('n5-91987ae840', '外はだんだん明るくなっていく。', '{外|そと}はだんだん{明|あか}るくなっていく。', NULL, 'It is getting lighter outside.', 184877),
  ('n5-91987ae840', 'ダイヤは明るく光った。', 'ダイヤは{明|あか}るく{光|ひか}った。', NULL, 'The diamond shone brightly.', 203874),
  ('n5-8dc7006bda', '秋はもうすぐそこまで来ている。', '{秋|あき}はもうすぐそこまで{来|き}ている。', NULL, 'Autumn is just around the corner.', 148194),
  ('n5-8dc7006bda', 'さわやかな秋となりました。', 'さわやかな{秋|あき}となりました。', NULL, 'Cool fall is here.', 216632),
  ('n5-fc3bc1e6f1', 'ぐいと押すとドアは開いた。', 'ぐいと{押|お}すとドアは{開|あ}いた。', NULL, 'The door yielded to a strong push.', 225720),
  ('n5-fc3bc1e6f1', 'ドアはどうしても開かなかった。', 'ドアはどうしても{開|あ}かなかった。', NULL, 'The door would not open.', 201844),
  ('n5-321963ed35', 'ドアはジムによって開けられます。', 'ドアはジムによって{開|あ}けられます。', NULL, 'The door is opened by Jim.', 201846),
  ('n5-321963ed35', 'だれかこのドアを開けてください。', 'だれかこのドアを{開|あ}けてください。', NULL, 'Somebody, open this door, please.', 203221),
  ('n5-9661cbac61', '左手を上げなさい。', '{左手|ひだりて}を{上|あ}げなさい。', NULL, 'Raise your left hand.', 170915),
  ('n5-9661cbac61', '彼はスピードを上げた。', '{彼|かれ}はスピードを{上|あ}げた。', NULL, 'He accelerated.', 113352),
  ('n5-d46ae79a26', '朝のラッシュは今がピークだ。', '{朝|あさ}のラッシュは{今|いま}がピークだ。', NULL, 'The morning rush is at its peak now.', 126237),
  ('n5-d46ae79a26', 'ジョージは朝にたくさんのチーズを食べた。', 'ジョージは{朝|あさ}にたくさんのチーズを{食|た}べた。', NULL, 'George had a lot of cheese for breakfast.', 215640),
  ('n5-98bc6f72ae', '朝ごはんにはなにがよろしいですか。', NULL, NULL, 'What would you like for breakfast?', 126248),
  ('n5-98bc6f72ae', '朝ご飯に何を食べますか。', '{朝|あさ}ご{飯|はん}に{何|なに}を{食|た}べますか。', NULL, 'What do you usually have for breakfast?', 126246),
  ('n5-b3b4041c52', 'あさって彼にここへ来てもらうつもりです。', 'あさって{彼|かれ}にここへ{来|き}てもらうつもりです。', NULL, 'I will have him come here the day after tomorrow.', 234491),
  ('n5-b3b4041c52', 'あさって、時間がありませんか。', 'あさって、{時間|じかん}がありませんか。', NULL, 'Do you have time the day after tomorrow?', 234494),
  ('n5-27df3d5802', 'また足がしびれた。', 'また{足|あし}がしびれた。', NULL, 'My foot''s asleep again!', 195414),
  ('n5-27df3d5802', 'ヘビを見て足がすくんでしまった。', 'ヘビを{見|み}て{足|あし}がすくんでしまった。', NULL, 'I froze at the sight of the snake.', 196726),
  ('n5-115ec83476', 'あしたは一日中ひまです。', 'あしたは{一日中|いちにちじゅう}ひまです。', NULL, 'I''ll be free all day tomorrow.', 234469),
  ('n5-115ec83476', '明日はピクニックに行くつもりだ。', NULL, NULL, 'I am going on a picnic tomorrow.', 80466),
  ('n5-bee501faf0', '先生、アソコがかゆいんです。', '{先生|せんせい}、アソコがかゆいんです。', NULL, 'Doctor, I''ve got an itch in my crotch.', 2733322),
  ('n5-bee501faf0', 'あそこのスポーツカーを見なさい。', 'あそこのスポーツカーを{見|み}なさい。', NULL, 'Look at the sports car over there.', 234395),
  ('n5-2d55571300', 'ビルはよく一人でおもちゃで遊ぶ。', 'ビルはよく{一人|ひとり}でおもちゃで{遊|あそ}ぶ。', NULL, 'Bill often plays with toys by himself.', 197343),
  ('n5-2d55571300', 'けっしてここで遊んではいけない。', 'けっしてここで{遊|あそ}んではいけない。', NULL, 'Never play here.', 225249),
  ('n5-f665c2128a', 'だんだん暖かくなります。', 'だんだん{暖|あたた}かくなります。', NULL, 'It will get warmer and warmer.', 203062),
  ('n5-f665c2128a', '日毎にだんだん暖かくなっている。', '{日毎|ひごと}にだんだん{暖|あたた}かくなっている。', NULL, 'It is getting warmer and warmer day by day.', 122194),
  ('n5-b62cb9ce4c', 'アリスは頭に花をさしています。', 'アリスは{頭|あたま}に{花|はな}をさしています。', NULL, 'Alice has a flower in her hair.', 229971),
  ('n5-b62cb9ce4c', 'ジルはかわいいだけでなく頭もよい。', 'ジルはかわいいだけでなく{頭|あたま}もよい。', NULL, 'Jill is smart as well as pretty.', 215196),
  ('n5-8ae27e3b51', '先生は新しい車が気に入っている。', '{先生|せんせい}は{新|あたら}しい{車|くるま}が{気|き}に{入|い}っている。', NULL, 'Our teacher likes his new car.', 141560),
  ('n5-8ae27e3b51', '新しいレストランが出来たそうだ。', '{新|あたら}しいレストランが{出来|でき}たそうだ。', NULL, 'It is said that a new restaurant was constructed.', 145459),
  ('n5-34e6f7d220', 'こっちの本はあっちの本よりやさしい。', 'こっちの{本|ほん}はあっちの{本|ほん}よりやさしい。', NULL, 'These books are easier than those books.', 217779),
  ('n5-34e6f7d220', 'あちらに着いたら手紙をください。', 'あちらに{着|つ}いたら{手紙|てがみ}をください。', NULL, 'Please write to me when you get there.', 234350),
  ('n5-9949d87445', 'それは４ｃｍの厚さです。', 'それは４ｃｍの{厚|あつ}さです。', NULL, 'It is four centimeters thick.', 205578),
  ('n5-9949d87445', '氷は２インチの厚さだ。', '{氷|こおり}は２インチの{厚|あつ}さだ。', NULL, 'The ice is two inches thick.', 85389),
  ('n5-7b4aecdf7b', 'どうして、こんなに暑いのですか。', 'どうして、こんなに{暑|あつ}いのですか。', NULL, 'Why is it so hot?', 201579),
  ('n5-7b4aecdf7b', '暑くならないうちに出かけよう。', '{暑|あつ}くならないうちに{出|で}かけよう。', NULL, 'Let''s go out before it gets hot.', 147452),
  ('n5-a379d413fd', '熱いコーヒーを入れてあげましょう。', '{熱|あつ}いコーヒーを{入|い}れてあげましょう。', NULL, 'Let me make you a cup of hot coffee.', 147486),
  ('n5-a379d413fd', '熱いダックスフント・ソーセージはいかが。', '{熱|あつ}いダックスフント・ソーセージはいかが。', NULL, 'Get your hot dachshund sausages!', 236207),
  ('n5-60dd63379e', 'こっちの本はあっちの本よりやさしい。', 'こっちの{本|ほん}はあっちの{本|ほん}よりやさしい。', NULL, 'These books are easier than those books.', 217779),
  ('n5-60dd63379e', 'あっちにエレベーターがあるみたいだよ。', NULL, NULL, 'It looks like there''s an elevator over there.', 4892691);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-4f134c9b38', '雨天の後には晴天が来る。', '{雨天|うてん}の{後|あと}には{晴天|せいてん}が{来|く}る。', NULL, 'After rain comes fair weather.', 189518),
  ('n5-4f134c9b38', 'アルファベットでＢはＡの後にくる。', 'アルファベットでＢはＡの{後|あと}にくる。', NULL, 'In the alphabet, B comes after A.', 229928),
  ('n5-afdf384f68', 'ねえあなたたち行かないで。', NULL, NULL, 'Don''t go, dears.', 198640),
  ('n5-afdf384f68', 'どちらの本があなたのものですか。', 'どちらの{本|ほん}があなたのものですか。', NULL, 'Which book is yours?', 200726),
  ('n5-4aab699864', 'これは兄です。かっこいいですね。', 'これは{兄|あに}です。かっこいいですね。', NULL, 'This is my brother. Handsome, isn''t he?', 74148),
  ('n5-4aab699864', '兄はアパートをさがしています。', '{兄|あに}はアパートをさがしています。', NULL, 'My brother is looking for an apartment.', 176617),
  ('n5-8bfeb208b4', '先月、姉は６ポンドの男の子を生んだ。', '{先月|せんげつ}、{姉|あね}は６ポンドの{男|おとこ}の{子|こ}を{生|う}んだ。', NULL, 'Last month my sister gave birth to a six-pound baby.', 141894),
  ('n5-8bfeb208b4', '姉は私のズボンにアイロンをかけてくれる。', NULL, NULL, 'My sister presses my trousers.', 168901),
  ('n5-ac4706068b', 'あのおいしいワインをなぜ飲まないんだい。', 'あのおいしいワインをなぜ{飲|の}まないんだい。', NULL, 'Why not try that delicious wine?', 231361),
  ('n5-ac4706068b', 'この本はあの本ほどやさしくない。', 'この{本|ほん}はあの{本|ほん}ほどやさしくない。', NULL, 'This book is not as easy as that one.', 219724),
  ('n5-0cf05b3a0d', '兄はアパートをさがしています。', '{兄|あに}はアパートをさがしています。', NULL, 'My brother is looking for an apartment.', 176617),
  ('n5-0cf05b3a0d', 'いいアパートね。', NULL, NULL, 'This is a great apartment.', 229463),
  ('n5-a5aceb6426', 'その時はシャワーを浴びていた。', 'その{時|とき}はシャワーを{浴|あ}びていた。', NULL, 'I was taking a shower then.', 209749),
  ('n5-a5aceb6426', 'シャワーを浴びてもよいでしょうか。', 'シャワーを{浴|あ}びてもよいでしょうか。', NULL, 'May I take a shower?', 215743),
  ('n5-0509cb3b27', '間一髪！危ないところでした。', '{間一髪|かんいっぱつ}！{危|あぶ}ないところでした。', NULL, 'That was a close call.', 183713),
  ('n5-0509cb3b27', '危ない！トラックが来るぞ！', '{危|あぶ}ない！トラックが{来|く}るぞ！', NULL, 'Look out! There''s a truck coming!', 183596),
  ('n5-4afffe5811', 'メアリーにはつい甘くなってしまう。', 'メアリーにはつい{甘|あま}くなってしまう。', NULL, 'I have always had a soft spot in my heart for Mary.', 194851),
  ('n5-4afffe5811', 'このチョコレートはとっても甘くておいしい。', 'このチョコレートはとっても{甘|あま}くておいしい。', NULL, 'This chocolate is very sweet and tasty.', 223560),
  ('n5-eac90e8e98', 'この手の本はあまり読まない。', 'この{手|て}の{本|ほん}はあまり{読|よ}まない。', NULL, 'I don''t read this kind of book much.', 221356),
  ('n5-eac90e8e98', 'フランス語ではあまり話しません。', 'フランス{語|ご}ではあまり{話|はな}しません。', NULL, 'I don''t speak French very much.', 196985),
  ('n5-5d72771a3c', 'いい子にしていたら、あめをあげよう。', NULL, NULL, 'If you are a good girl, you shall have candy.', 229358),
  ('n5-5d72771a3c', '息子は箱から飴を一つ取った。', '{息子|むすこ}は{箱|はこ}から{飴|あめ}を{一|ひと}つ{取|と}った。', NULL, 'My son took a candy from the box.', 139909),
  ('n5-277a58c9df', '木のおかげで雨にぬれずにすんだ。', '{木|き}のおかげで{雨|あめ}にぬれずにすんだ。', NULL, 'The trees kept me out of the rain.', 80133),
  ('n5-277a58c9df', '今すぐにも雨がふるかもしれない。', '{今|いま}すぐにも{雨|あめ}がふるかもしれない。', NULL, 'It may rain any minute.', 172827),
  ('n5-f8fa96946f', 'いつこの車は洗われましたか。', 'いつこの{車|くるま}は{洗|あら}われましたか。', NULL, 'When was this car washed?', 228970),
  ('n5-f8fa96946f', '車を洗っているのはジョーンズさんです。', '{車|くるま}を{洗|あら}っているのはジョーンズさんです。', NULL, 'The man washing the car is Mr Jones.', 148947),
  ('n5-93461820fe', 'はるばる来てくれてありがとう。', 'はるばる{来|き}てくれてありがとう。', NULL, 'It was nice of you to come all the way.', 197814),
  ('n5-93461820fe', 'そうおっしゃって下さってありがとう。', 'そうおっしゃって{下|くだ}さってありがとう。', NULL, 'It''s very kind of you to say so.', 213900),
  ('n5-ac08788418', '話があったら電話をかけて下さい。', '{話|はなし}があったら{電話|でんわ}をかけて{下|くだ}さい。', NULL, 'If you want to speak to me, please call me up.', 77204),
  ('n5-ac08788418', '木はたとえあってもほとんどない。', '{木|き}はたとえあってもほとんどない。', NULL, 'There were few, if any, trees.', 80097),
  ('n5-55f3080ce4', '歩いて行きますか？それともバスで行きますか？', NULL, NULL, 'Will you go on foot or by bus?', 231584),
  ('n5-55f3080ce4', '歩きながら本を読んではいけない。', '{歩|ある}きながら{本|ほん}を{読|よ}んではいけない。', NULL, 'Do not read while walking.', 83212),
  ('n5-e37a087c0f', 'もう２、３ページ読みさえすればいい。', 'もう２、３ページ{読|よ}みさえすればいい。', NULL, 'You have only to read a few more pages.', 194533),
  ('n5-e37a087c0f', 'ダンスはスタイルをよくするのにいい。', NULL, NULL, 'Dancing is good for the figure.', 203075),
  ('n5-ae0cc00f94', '「みんなひと休みしようぜ」とジョンは言った。', NULL, NULL, 'John said, "Hey guys, let''s take a break."', 236431),
  ('n5-ae0cc00f94', 'さんざん小言をいってやる。', 'さんざん{小言|こごと}をいってやる。', NULL, 'I give a good scolding.', 216629),
  ('n5-9f074820b1', '木立の間に家が見える。', '{木立|こだち}の{間|あいだ}に{家|いえ}が{見|み}える。', NULL, 'I see a house among the trees.', 80048),
  ('n5-9f074820b1', '母はいつも家にいるわけではない。', '{母|はは}はいつも{家|いえ}にいるわけではない。', NULL, 'My mother is not always at home.', 83093),
  ('n5-a3f296ad9a', 'コンタクトを入れるというのはいかがでしょう？', 'コンタクトを{入|い}れるというのはいかがでしょう？', NULL, 'How about wearing contact lenses?', 74894),
  ('n5-a3f296ad9a', 'ベーコンかソーセージはいかがか。', NULL, NULL, 'Would you like bacon or sausage?', 196854),
  ('n5-66e4692df7', 'お母さん、泳ぎに行ってもいい？', NULL, NULL, 'Can I go swimming, Mother?', 226648),
  ('n5-66e4692df7', '父は、アメリカへ行ってしまった。', NULL, NULL, 'My father has gone to America.', 84793),
  ('n5-026ae57b50', 'あなたのお父さんはおいくつですか。', 'あなたのお{父|とう}さんはおいくつですか。', NULL, 'How old is your father?', 233594),
  ('n5-026ae57b50', 'ウエストのサイズはいくつですか。', NULL, NULL, 'What is your waist size?', 228303),
  ('n5-4fc98c6938', 'このハンカチはいくらですか。', NULL, NULL, 'How much is this handkerchief?', 223306),
  ('n5-4fc98c6938', 'ヒルトンホテルまでいくらですか。', NULL, NULL, 'How much is the fare to the Hilton Hotel?', 197388),
  ('n5-43c874a6c8', 'その池にはほとんど水がない。', 'その{池|いけ}にはほとんど{水|みず}がない。', NULL, 'There is little water in the pond.', 207858),
  ('n5-43c874a6c8', 'この前の夏にこの池は水がなくなりました。', NULL, NULL, 'The pond dried up last summer.', 220757),
  ('n5-ca76162587', '医者になるつもりだったのですが。', '{医者|いしゃ}になるつもりだったのですが。', NULL, 'I intended to become a doctor.', 190904),
  ('n5-ca76162587', '日本語の話せる医者はいますか。', '{日本語|にほんご}の{話|はな}せる{医者|いしゃ}はいますか。', NULL, 'Do you know any doctors who speak Japanese?', 122341);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-d305fa14a8', 'ちょっと椅子をずらしてくれない？', 'ちょっと{椅子|いす}をずらしてくれない？', NULL, 'Could you move the chair a bit?', 202860),
  ('n5-d305fa14a8', 'イスはそのままにしておきなさい。', NULL, NULL, 'Leave the chairs as they are.', 229123),
  ('n5-cd1bcc2b1b', '忙しくてそれどころじゃないよ。', '{忙|いそが}しくてそれどころじゃないよ。', NULL, 'I''ve got no time for that now.', 82529),
  ('n5-cd1bcc2b1b', 'このところ、とても忙しくてね。', 'このところ、とても{忙|いそが}しくてね。', NULL, 'I''m very busy these days.', 223466),
  ('n5-4dae367794', 'ほかに痛いところはありますか。', 'ほかに{痛|いた}いところはありますか。', NULL, 'Do you feel pain in any other part of your body?', 196436),
  ('n5-4dae367794', '痛くないようにしてください。', '{痛|いた}くないようにしてください。', NULL, 'Please be gentle.', 125689),
  ('n5-eac7a22620', '８ドル５０セントいただきます。', NULL, NULL, '$8.50, please.', 234953),
  ('n5-eac7a22620', 'ワインをいただきます。', NULL, NULL, 'We''d like to have some wine.', 192061),
  ('n5-9d8f862791', 'これは東京一のインドレストランです。', 'これは{東京|とうきょう}{一|いち}のインドレストランです。', NULL, 'This is the best Indian restaurant anywhere in Tokyo.', 218179),
  ('n5-9d8f862791', 'このとおりを一マイル行きなさい。', NULL, NULL, 'Go along this street for a mile.', 223472),
  ('n5-1cfccd0cdd', '一日で５００ドルつかってしまった。', '{一日|いちにち}で５００ドルつかってしまった。', NULL, 'I''ve spent $500 a day.', 190280),
  ('n5-1cfccd0cdd', '一日いい天気になりそうですよ。', '{一日|いちにち}いい{天気|てんき}になりそうですよ。', NULL, 'I think it''s going to be a nice day.', 190284),
  ('n5-cb96f363df', 'このリンゴがいちばんおいしい。', NULL, NULL, 'This is the most delicious apple.', 223023),
  ('n5-cb96f363df', 'あいつはクラスでいちばんのまぬけだ。', NULL, NULL, 'He is the dumbest kid in the class.', 234637),
  ('n5-fac6fc0838', 'いつ旅行においでになりますか。', 'いつ{旅行|りょこう}においでになりますか。', NULL, 'When will you go on a journey?', 228596),
  ('n5-fac6fc0838', 'パーティーはいつにしましょうか。', NULL, NULL, 'When shall we have the party?', 198453),
  ('n5-2a7c4baf86', '１月５日から１月１５日までおねがいします。', NULL, NULL, 'From the 5th to the 15th of January, please.', 235804),
  ('n5-2a7c4baf86', '五日待ってくれ。', '{五日|いつか}{待|ま}ってくれ。', NULL, 'Give me five days.', 235115),
  ('n5-2dc7289c82', '「ご一緒してもいいですか」「もちろんです」', '「ご{一緒|いっしょ}してもいいですか」「もちろんです」', NULL, '"May I go with you?" "Of course."', 217215),
  ('n5-2dc7289c82', 'もっと一緒にいられたらいいのに。', 'もっと{一緒|いっしょ}にいられたらいいのに。', NULL, 'I wish that we could spend more time together.', 2304921),
  ('n5-9ac35c3990', 'この箱にはリンゴが五つ入っている。', 'この{箱|はこ}にはリンゴが{五|いつ}つ{入|はい}っている。', NULL, 'This box contains five apples.', 220200),
  ('n5-9ac35c3990', 'レストランやパブは五つ木通りにたくさんあります。', 'レストランやパブは{五|いつ}つ{木|き}{通|どお}りにたくさんあります。', NULL, 'Many restaurants and pubs are on Itsutsugi Street.', 192345),
  ('n5-dea2a1df8b', 'あの子はいつもニコニコしている。', 'あの{子|こ}はいつもニコニコしている。', NULL, 'She is always smiling.', 230970),
  ('n5-dea2a1df8b', 'あの子はいつもだだをこねている。', 'あの{子|こ}はいつもだだをこねている。', NULL, 'That child is always throwing tantrums.', 230973),
  ('n5-0df89f5010', 'その犬はかみついたりしませんよ。', 'その{犬|いぬ}はかみついたりしませんよ。', NULL, 'The dog will not harm you.', 211003),
  ('n5-0df89f5010', 'この犬は何でもほとんど食べます。', 'この{犬|いぬ}は{何|なん}でもほとんど{食|た}べます。', NULL, 'This dog eats almost anything.', 222102),
  ('n5-ce75c75644', '今のアナウンスは何だったのですか。', '{今|いま}のアナウンスは{何|なに}だったのですか。', NULL, 'What did the announcement just say?', 172752),
  ('n5-ce75c75644', 'トムもビルも今テニスをしている。', 'トムもビルも{今|いま}テニスをしている。', NULL, 'Both Tom and Bill are playing tennis now.', 199786),
  ('n5-cb29ccdd2a', 'その語にはいくつかの意味がある。', 'その{語|ご}にはいくつかの{意味|いみ}がある。', NULL, 'The word has several meanings.', 210824),
  ('n5-cb29ccdd2a', 'おっしゃる意味がわかりませんが。', 'おっしゃる{意味|いみ}がわかりませんが。', NULL, 'What you said does not make sense.', 227633),
  ('n5-12047d019b', '男の子は妹を見下ろしがちである。', '{男|おとこ}の{子|こ}は{妹|いもうと}を{見下|みお}ろしがちである。', NULL, 'Boys tend to look down on their younger sisters.', 127233),
  ('n5-12047d019b', 'あいつの妹、とてもかわいいね。', 'あいつの{妹|いもうと}、とてもかわいいね。', NULL, 'His little sister is very cute, isn''t she?', 234651),
  ('n5-eda751e069', '毎日うっとうしくていやですね。', '{毎日|まいにち}うっとうしくていやですね。', NULL, 'Don''t you just hate this weather?', 81316),
  ('n5-eda751e069', 'どんなものでも、スポーツはいやです。', NULL, NULL, 'I just do not like any kind of sports.', 199479),
  ('n5-1ff0529d03', '１台の車が入り口に止まった。', NULL, NULL, 'A car stopped at the entrance.', 235719),
  ('n5-1ff0529d03', '数人の人が入り口でぶらついていた。', '{数人|すうにん}の{人|ひと}が{入|い}り{口|ぐち}でぶらついていた。', NULL, 'Some people were hanging around at the entrance.', 143523),
  ('n5-9438889173', 'すっかり食べ終わってはいない。', 'すっかり{食|た}べ{終|お}わってはいない。', NULL, 'I haven''t quite finished eating.', 214668),
  ('n5-9438889173', 'あんないい男そうそういないぞ！！', 'あんないい{男|おとこ}そうそういないぞ！！', NULL, 'There aren''t many blokes that nice!', 75577),
  ('n5-7a84208708', '今のところお金はいらない。', '{今|いま}のところお{金|かね}はいらない。', NULL, 'I don''t need money at present.', 172740),
  ('n5-7a84208708', 'バターが要るんだけど、いくらかありますか。', 'バターが{要|い}るんだけど、いくらかありますか。', NULL, 'I need some butter. Do you have any?', 198027),
  ('n5-6d824d5110', 'それは引き出しに入れておきました。', 'それは{引|ひ}き{出|だ}しに{入|い}れておきました。', NULL, 'I put it in the drawer.', 205330),
  ('n5-6d824d5110', '本をさかさまに入れないで下さい。', '{本|ほん}をさかさまに{入|い}れないで{下|くだ}さい。', NULL, 'Don''t put the books in the shelf upside down.', 81634),
  ('n5-523266ea6f', 'カメレオンはどんな色にでもなれる。', 'カメレオンはどんな{色|いろ}にでもなれる。', NULL, 'The chameleon can take on any color.', 226206),
  ('n5-523266ea6f', 'この色、気に入りましたか。', 'この{色|いろ}、{気|き}に{入|い}りましたか。', NULL, 'Do you like this color?', 221060),
  ('n5-f74dd1ee9a', '先生といってもいろいろある。', '{先生|せんせい}といってもいろいろある。', NULL, 'There are teachers and then there are teachers.', 141760),
  ('n5-f74dd1ee9a', 'コーヒーにもいろいろある。', NULL, NULL, 'There are various kinds of coffee.', 224928),
  ('n5-08a3ed212d', 'テーブルの上にリンゴがあります。', 'テーブルの{上|うえ}にリンゴがあります。', NULL, 'There is an apple on the table.', 202398),
  ('n5-08a3ed212d', 'テーブルの上にオレンジがある。', 'テーブルの{上|うえ}にオレンジがある。', NULL, 'There is an orange on the table.', 202408),
  ('n5-93bdc81dd9', '校長が先生の後ろから入ってきた。', '{校長|こうちょう}が{先生|せんせい}の{後|うし}ろから{入|はい}ってきた。', NULL, 'The principal came in after the teacher.', 173570),
  ('n5-93bdc81dd9', 'あなたの後ろのドアをしめて下さい。', 'あなたの{後|うし}ろのドアをしめて{下|くだ}さい。', NULL, 'Please close the door behind you.', 233318);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-d2b2316e45', 'コーヒーは薄いのが好きです。', 'コーヒーは{薄|うす}いのが{好|す}きです。', NULL, 'I''d like my coffee weak.', 224899),
  ('n5-d2b2316e45', '肉を薄く切りなさい。', '{肉|にく}を{薄|うす}く{切|き}りなさい。', NULL, 'Cut the meat into thin slices.', 122981),
  ('n5-036f4180a2', '歌がうまければいいのになあ。', '{歌|うた}がうまければいいのになあ。', NULL, 'I wish I were a good singer.', 186791),
  ('n5-036f4180a2', 'この歌の名前は『オンリー・ユー』です。', 'この{歌|うた}の{名前|なまえ}は『オンリー・ユー』です。', NULL, 'This song''s name is "Only You".', 222789),
  ('n5-3464318c23', 'ジョンはステージで何を歌いましたか。', 'ジョンはステージで{何|なに}を{歌|うた}いましたか。', NULL, 'What did John sing on the stage?', 215403),
  ('n5-3464318c23', 'ベティはうまく歌うことができた。', 'ベティはうまく{歌|うた}うことができた。', NULL, 'Betty managed to sing well.', 196771),
  ('n5-63bc7722fa', 'どんぐりからオークが生まれる。', 'どんぐりからオークが{生|う}まれる。', NULL, 'From acorns come oaks.', 199613),
  ('n5-63bc7722fa', 'ここが父の生まれたところです。', 'ここが{父|ちち}の{生|う}まれたところです。', NULL, 'This is the place where my father was born.', 224704),
  ('n5-06ac21dc7d', '何としても海をひと目みたいものだ。', NULL, NULL, 'I ache for a sight of the sea.', 187770),
  ('n5-06ac21dc7d', '海までは、たった１マイルです。', '{海|うみ}までは、たった１マイルです。', NULL, 'It is no more than a mile to the sea.', 185086),
  ('n5-f7e1da43df', 'トムはメアリーにバイクを売った。', 'トムはメアリーにバイクを{売|う}った。', NULL, 'Tom sold his motorcycle to Mary.', 2312116),
  ('n5-f7e1da43df', 'バターは１ポンドいくらで売られる。', 'バターは１ポンドいくらで{売|う}られる。', NULL, 'Butter is sold by the pound.', 198017),
  ('n5-7ecfe0d248', 'あの子はなんてうるさい子だろう。', 'あの{子|こ}はなんてうるさい{子|こ}だろう。', NULL, 'What a nuisance that child is!', 230966),
  ('n5-7ecfe0d248', 'つべこべうるさいよ。やるのかやらないのか！？', NULL, NULL, 'Quit your bellyaching. You goin'' to do it, or not!?', 75438),
  ('n5-1ef8a05bf3', 'ドアのそばのかぎに上着をかけなさい。', 'ドアのそばのかぎに{上着|うわぎ}をかけなさい。', NULL, 'Hang your jacket on the hook by the door.', 201867),
  ('n5-1ef8a05bf3', 'その上着はよくもったね。', 'その{上着|うわぎ}はよくもったね。', NULL, 'The coat has worn well.', 208973),
  ('n5-5bb390da0b', '絵がテーブルの上にかかっている。', '{絵|え}がテーブルの{上|うえ}にかかっている。', NULL, 'The picture hangs over the table.', 184950),
  ('n5-5bb390da0b', 'なぜその絵を見なかったのですか。', 'なぜその{絵|え}を{見|み}なかったのですか。', NULL, 'Why didn''t you look at the picture?', 199249),
  ('n5-92b1621231', 'その映画をもう一度見たいな。', 'その{映画|えいが}をもう{一度|いちど}{見|み}たいな。', NULL, 'I want to see the movie again.', 212237),
  ('n5-92b1621231', '映画を見に行こうではないですか。', '{映画|えいが}を{見|み}に{行|い}こうではないですか。', NULL, 'What do you say to going to the movies?', 189293),
  ('n5-8a88cfbcb8', 'その映画館は人々でいっぱいだった。', 'その{映画館|えいがかん}は{人々|ひとびと}でいっぱいだった。', NULL, 'The cinema was filled with people.', 212218),
  ('n5-8a88cfbcb8', 'この近くに映画館はありますか。', 'この{近|ちか}くに{映画館|えいがかん}はありますか。', NULL, 'Are there any movie theaters near here?', 179880),
  ('n5-16adc7bd03', 'アメリカでは英語を話します。', 'アメリカでは{英語|えいご}を{話|はな}します。', NULL, 'They speak English in America.', 230259),
  ('n5-16adc7bd03', '先生のように英語が話せたらなぁ。', '{先生|せんせい}のように{英語|えいご}が{話|はな}せたらなぁ。', NULL, 'I wish I could speak English the way my teacher does.', 141734),
  ('n5-8ac60a4060', '「テニスをしましょうか」「ええ」', NULL, NULL, '"Let''s play tennis." "Yes let''s."', 202181),
  ('n5-8ac60a4060', 'ええ、アンソニーです。', NULL, NULL, 'Yes, this is Anthony.', 228019),
  ('n5-d5f359c20b', 'グランド・セントラル駅までやってください。', 'グランド・セントラル{駅|えき}までやってください。', NULL, 'Grand Central Station, please.', 225536),
  ('n5-d5f359c20b', 'ここから駅まで２マイルあります。', 'ここから{駅|えき}まで２マイルあります。', NULL, 'It''s two miles from here to the station.', 224772),
  ('n5-eb1695baf6', 'エレベーターはどこですか。', NULL, NULL, 'Where is the elevator?', 227886),
  ('n5-eb1695baf6', '私はエレベーターで下におりた。', '{私|わたし}はエレベーターで{下|した}におりた。', NULL, 'I went down by elevator.', 161307),
  ('n5-381da4d060', 'えんぴつであなたの名前を書きなさい。', 'えんぴつであなたの{名前|なまえ}を{書|か}きなさい。', NULL, 'Write your name with the pencil.', 227853),
  ('n5-381da4d060', 'ペンか鉛筆を持っていますか。', 'ペンか{鉛筆|えんぴつ}を{持|も}っていますか。', NULL, 'Do you have a pen or a pencil?', 196645),
  ('n5-7f02ae8fa1', 'おいしい食事をありがとう。', 'おいしい{食事|しょくじ}をありがとう。', NULL, 'Thanks for the delicious meal.', 227834),
  ('n5-7f02ae8fa1', 'なんておいしいスープなんだろう。', NULL, NULL, 'This soup is exquisite.', 198944),
  ('n5-60813fffd1', 'この学校は男子よりも女子が多い。', 'この{学校|がっこう}は{男子|だんし}よりも{女子|じょし}が{多|おお}い。', NULL, 'There are more girls than boys in this school.', 222596),
  ('n5-60813fffd1', 'そこには、水が多かったからである。', 'そこには、{水|みず}が{多|おお}かったからである。', NULL, 'Because there was plenty of water...', 213686),
  ('n5-8fa5a63fc7', 'もっと大きいサイズはありますか。', 'もっと{大|おお}きいサイズはありますか。', NULL, 'Do you have a larger size?', 193236),
  ('n5-8fa5a63fc7', 'きみは何と大きい家を持っているんだろう。', 'きみは{何|なん}と{大|おお}きい{家|いえ}を{持|も}っているんだろう。', NULL, 'What a big house you have!', 225891),
  ('n5-3a2de0afca', 'それらはとても大きなりんごです。', 'それらはとても{大|おお}きなりんごです。', NULL, 'They are very big apples.', 204722),
  ('n5-3a2de0afca', 'あの大きなハンマーを見てごらん。', 'あの{大|おお}きなハンマーを{見|み}てごらん。', NULL, 'Look at that big hammer.', 230634),
  ('n5-57ed89b240', '大ぜいの人たちがいた。', NULL, NULL, 'There were lots of people.', 137691),
  ('n5-57ed89b240', 'そこには大勢の人がいた。', NULL, NULL, 'There was a large crowd there.', 213674),
  ('n5-2007947770', 'お母さんに口答えしてはいけませんよ。', 'お{母|かあ}さんに{口答|くちごた}えしてはいけませんよ。', NULL, 'Don''t answer your mother back.', 226625),
  ('n5-2007947770', 'ダンはよくお母さんにしかられる。', 'ダンはよくお{母|かあ}さんにしかられる。', NULL, 'Dan is often scolded by his mother.', 203056),
  ('n5-669019c625', 'もうすこしお菓子を食べませんか。', 'もうすこしお{菓子|かし}を{食|た}べませんか。', NULL, 'Will you have some more cake?', 194419),
  ('n5-669019c625', 'このお菓子を食べてもいいですか。', 'このお{菓子|かし}を{食|た}べてもいいですか。', NULL, 'May I eat this cake?', 223955),
  ('n5-3e015d0a8b', 'どうやってそのお金を手に入れたんですか。', 'どうやってそのお{金|かね}を{手|て}に{入|い}れたんですか。', NULL, 'How did you come by the money?', 232498),
  ('n5-3e015d0a8b', 'ぼくにいくらかお金をくれないか。', 'ぼくにいくらかお{金|かね}をくれないか。', NULL, 'Can you give me some money?', 196392),
  ('n5-248a353e09', 'お子さんはまだ起きているのですか。', 'お{子|こ}さんはまだ{起|お}きているのですか。', NULL, 'Is the kid still up?', 227112),
  ('n5-248a353e09', '６時ごろ起きた。', '６{時|じ}ごろ{起|お}きた。', NULL, 'I got up at about six.', 235061);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-96845304fd', 'それをテーブルの上に置きなさい。', 'それをテーブルの{上|うえ}に{置|お}きなさい。', NULL, 'Lay it on the table.', 204648),
  ('n5-96845304fd', 'バッグはどこに置けばいいですか。', 'バッグはどこに{置|お}けばいいですか。', NULL, 'Where can I put my bag?', 197972),
  ('n5-6c4661d672', '奥さんがどこかに出かけているらしいから。', '{奥|おく}さんがどこかに{出|で}かけているらしいから。', NULL, 'I think his wife is going out of town.', 188559),
  ('n5-6c4661d672', '奥さんがカンカンだぞ。', '{奥|おく}さんがカンカンだぞ。', NULL, 'Your wife is mad at you.', 188560),
  ('n5-f843b00173', 'マイクはお酒をやめたの？', 'マイクはお{酒|さけ}をやめたの？', NULL, 'Is Mike off the bottle?', 195774),
  ('n5-f843b00173', 'お酒を飲んでもいいですか。', 'お{酒|さけ}を{飲|の}んでもいいですか。', NULL, 'Can I drink alcohol?', 227033),
  ('n5-101d46a061', 'スープを入れるくぼんだお皿がありますか。', 'スープを{入|い}れるくぼんだお{皿|さら}がありますか。', NULL, 'Do you have a bowl for soup?', 215024),
  ('n5-101d46a061', '私はお皿を洗ってからテレビを見た。', '{私|わたし}はお{皿|さら}を{洗|あら}ってからテレビを{見|み}た。', NULL, 'I watched TV after I washed the dishes.', 161235),
  ('n5-1b89f0f993', 'おじいさんはとてもゆっくりと話す。', 'おじいさんはとてもゆっくりと{話|はな}す。', NULL, 'Grandfather speaks very slowly.', 227740),
  ('n5-1b89f0f993', 'おじいさんの世話をする。', 'おじいさんの{世話|せわ}をする。', NULL, 'I take care of my grandfather.', 227744),
  ('n5-f2fa049fdd', '生年月日を教えてくださいますか？', '{生年月日|せいねんがっぴ}を{教|おし}えてくださいますか？', NULL, 'May I have your birth date?', 142700),
  ('n5-f2fa049fdd', 'あの学校では中国語を教えている。', 'あの{学校|がっこう}では{中国語|ちゅうごくご}を{教|おし}えている。', NULL, 'They teach Chinese at that school.', 231121),
  ('n5-ce8facdf69', 'シャッターを押してくれますか。', 'シャッターを{押|お}してくれますか。', NULL, 'Could you press this button?', 215785),
  ('n5-ce8facdf69', 'このボタンを押せばいいのですよ。', 'このボタンを{押|お}せばいいのですよ。', NULL, 'Push the button here.', 223170),
  ('n5-a082687f7a', '遅くなっても何もないよりはまし。', '{遅|おそ}くなっても{何|なに}もないよりはまし。', NULL, 'Better late than never.', 126737),
  ('n5-a082687f7a', 'そういうわけで遅くなったのです。', 'そういうわけで{遅|おそ}くなったのです。', NULL, 'That''s why I was late.', 213942),
  ('n5-edca336b1f', '３時はお茶にしよう。', '３{時|じ}はお{茶|ちゃ}にしよう。', NULL, 'Let''s have tea at 3:00.', 235316),
  ('n5-edca336b1f', 'お茶かコーヒーでもいかがですか。', 'お{茶|ちゃ}かコーヒーでもいかがですか。', NULL, 'Would you like tea or coffee?', 226878),
  ('n5-75a36b034c', 'お手洗いはどこですか。', 'お{手洗|てあら}いはどこですか。', NULL, 'Where''s the restroom?', 227063),
  ('n5-75a36b034c', 'お手洗いはどこか教えて下さいませんか。', NULL, NULL, 'Could you show me where the bathroom is?', 227064),
  ('n5-89807c7c22', 'お父さんからことづけがあります。', 'お{父|とう}さんからことづけがあります。', NULL, 'I have a message for you from your father.', 226757),
  ('n5-89807c7c22', 'お父さんとキャッチボールをしたよ。', 'お{父|とう}さんとキャッチボールをしたよ。', NULL, 'I played catch with my father.', 161219),
  ('n5-db32745bbc', '弟のことなんかほっときなさい。', '{弟|おとうと}のことなんかほっときなさい。', NULL, 'Leave him alone.', 125460),
  ('n5-db32745bbc', 'マイクは弟にひどいいたずらをした。', 'マイクは{弟|おとうと}にひどいいたずらをした。', NULL, 'Mike played a bad trick on his brother.', 195735),
  ('n5-2fd7d45c8d', 'その男とつきあってはいけないよ。', 'その{男|おとこ}とつきあってはいけないよ。', NULL, 'You must have nothing to do with the man.', 208173),
  ('n5-2fd7d45c8d', 'おまえを一人前の男にしてやろう。', 'おまえを{一人前|いちにんまえ}の{男|おとこ}にしてやろう。', NULL, 'I will make a man of you.', 227512),
  ('n5-6f664d3ded', 'あのハンサムな男の子を見て。', 'あのハンサムな{男|おとこ}の{子|こ}を{見|み}て。', NULL, 'Look at that good-looking boy.', 231277),
  ('n5-6f664d3ded', '男の子のいたずらはしょうがない。', '{男|おとこ}の{子|こ}のいたずらはしょうがない。', NULL, 'Boys will be boys.', 127249),
  ('n5-f0f3826045', '一昨日、彼は学校を休んだかもしれない。', '{一昨日|おととい}、{彼|かれ}は{学校|がっこう}を{休|やす}んだかもしれない。', NULL, 'He may have absented himself from school the day before yesterday.', 190607),
  ('n5-f0f3826045', '一昨日から、雨が降ったりやんだりしている。', '{一昨日|おととい}から、{雨|あめ}が{降|ふ}ったりやんだりしている。', NULL, 'It has been raining on and off since the day before yesterday.', 190604),
  ('n5-b75778f0ce', '彼女は、一昨年よりもはるかに暮らし向きがよい。', NULL, NULL, 'She''s far better off than she was the year before last.', 93768),
  ('n5-6f5049e2d4', '大人だけこの映画が見える。', '{大人|おとな}だけこの{映画|えいが}が{見|み}える。', NULL, 'Only adults can see this film.', 137483),
  ('n5-6f5049e2d4', 'この本は大人によく読まれている。', 'この{本|ほん}は{大人|おとな}によく{読|よ}まれている。', NULL, 'This is a book often read by adults.', 219579),
  ('n5-3707072a6b', '何かおなかに入れてから出かけなさい。', NULL, NULL, 'You should put something in your stomach before you go.', 188135),
  ('n5-3707072a6b', 'ううん、もういいよ。お腹いっぱい。', 'ううん、もういいよ。お{腹|なか}いっぱい。', NULL, 'No, thank you. I''m full.', 228315),
  ('n5-7c134ec812', 'この木はあの木とほぼ同じ高さだ。', 'この{木|き}はあの{木|き}とほぼ{同|おな}じ{高|たか}さだ。', NULL, 'This tree is about as high as that one.', 219452),
  ('n5-7c134ec812', 'マイクとトムは同じクラスです。', 'マイクとトムは{同|おな}じクラスです。', NULL, 'Mike and Tom are in the same class.', 195787),
  ('n5-c6f43a8cc3', '私はあなたのお兄さんより年上です。', '{私|わたし}はあなたのお{兄|にい}さんより{年上|としうえ}です。', NULL, 'I''m older than your brother.', 161718),
  ('n5-c6f43a8cc3', 'あなたを見るとお兄さんを思い出します。', 'あなたを{見|み}るとお{兄|にい}さんを{思|おも}い{出|だ}します。', NULL, 'You remind me of your brother.', 231433),
  ('n5-af378a4c86', 'あなたのお姉さんは今何をしているの？', 'あなたのお{姉|ねえ}さんは{今|いま}{何|なに}をしているの？', NULL, 'What''s your older sister doing now?', 233258),
  ('n5-af378a4c86', 'お姉さんによろしくね。', 'お{姉|ねえ}さんによろしくね。', NULL, 'Say hello to your sister for me.', 168930),
  ('n5-4df6eda2a2', 'ファーストクラスでお願いします。', 'ファーストクラスでお{願|ねが}いします。', NULL, 'I''d like to travel first-class.', 197242),
  ('n5-4df6eda2a2', 'できれば、６時半でお願いします。', 'できれば、６{時半|じはん}でお{願|ねが}いします。', NULL, 'Six-thirty, it''s possible.', 202278),
  ('n5-12d9487797', 'トムのおばあさんは元気そうですよ。', 'トムのおばあさんは{元気|げんき}そうですよ。', NULL, 'Tom''s grandmother looks healthy.', 200160),
  ('n5-12d9487797', '私は一人のおばあさんに会った。', '{私|わたし}は{一人|ひとり}のおばあさんに{会|あ}った。', NULL, 'I met an old woman.', 158459),
  ('n5-03d7b15720', '叔母さんを訪ねた時はすごいごちそうだったね。', '{叔母|おば}さんを{訪|たず}ねた{時|とき}はすごいごちそうだったね。', NULL, 'What a feast we had when we visited my aunt!', 227572),
  ('n5-03d7b15720', 'これクララ叔母さんのと同じネックレスじゃない？', 'これクララ{叔母|おば}さんのと{同|おな}じネックレスじゃない？', NULL, 'Isn''t this the same necklace that Aunt Clara wears?', 218824),
  ('n5-36bff8d879', 'おはよう。ご飯をよそっても良いかしら？', 'おはよう。ご{飯|はん}をよそっても{良|よ}いかしら？', NULL, 'Morning. Shall I dish up?', 76824),
  ('n5-36bff8d879', 'やぁ、トム。おはよう。', NULL, NULL, 'Hello, Tom. Good morning.', 193149),
  ('n5-f347485004', '私はほとんど毎日お風呂に入ります。', '{私|わたし}はほとんど{毎日|まいにち}お{風呂|ふろ}に{入|はい}ります。', NULL, 'I take a bath almost every day.', 158918);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-f347485004', 'お風呂はありませんでした。', 'お{風呂|ふろ}はありませんでした。', NULL, 'There was no bathroom.', 226696),
  ('n5-7a073616e5', '彼は今日、お弁当を持って来た。', NULL, NULL, 'He brought his lunch today.', 107100),
  ('n5-7a073616e5', 'お弁当食べたんでしょう。', NULL, NULL, 'You have eaten lunch, haven''t you?', 226652),
  ('n5-dad2d16220', '日本語は外人にとって覚えにくい。', '{日本語|にほんご}は{外人|がいじん}にとって{覚|おぼ}えにくい。', NULL, 'It is hard for foreigners to learn Japanese.', 122337),
  ('n5-dad2d16220', 'どこでそんなこと覚えてきたんだ。', 'どこでそんなこと{覚|おぼ}えてきたんだ。', NULL, 'Where did you get the idea?', 200989),
  ('n5-ae5d1778d1', 'すみません、おまわりさん。ここはどこですか。', NULL, NULL, 'Excuse me, officer, where are we now?', 214211),
  ('n5-ae5d1778d1', 'おまわりさんに道を尋ねなさい。', 'おまわりさんに{道|みち}を{尋|たず}ねなさい。', NULL, 'Ask the policeman the way.', 227504),
  ('n5-cdfb776826', 'トムはジャックよりも１０ポンド重い。', 'トムはジャックよりも１０ポンド{重|おも}い。', NULL, 'Tom is heavier than Jack by ten pounds.', 200082),
  ('n5-cdfb776826', 'この本はあの本ほど重くない。', 'この{本|ほん}はあの{本|ほん}ほど{重|おも}くない。', NULL, 'This book isn''t as heavy as that book.', 219723),
  ('n5-2568873ebd', 'スケートはとてもおもしろかった。', NULL, NULL, 'We had a lot of fun skating.', 214743),
  ('n5-2568873ebd', 'これはとってもおもしろい本です。', 'これはとってもおもしろい{本|ほん}です。', NULL, 'This is a very interesting book.', 218571),
  ('n5-3c5bb8f223', 'トムはすぐに泳げるようになるよ。', 'トムはすぐに{泳|およ}げるようになるよ。', NULL, 'Tom will be able to swim soon.', 200074),
  ('n5-3c5bb8f223', 'ハリーはなんとかその川を泳ぎきった。', 'ハリーはなんとかその{川|かわ}を{泳|およ}ぎきった。', NULL, 'Harry managed to swim across the river.', 197870),
  ('n5-ae00442122', 'ここで降りましょう。', 'ここで{降|お}りましょう。', NULL, 'Let''s get off here.', 224559),
  ('n5-ae00442122', 'スリッパでロビーに降りたらだめだよ。', 'スリッパでロビーに{降|お}りたらだめだよ。', NULL, 'You''re not supposed to wear your slippers down to the lobby.', 214120),
  ('n5-d7960dc78d', 'そのコンサートは十時に終わった。', NULL, NULL, 'The concert came to an end at ten o''clock.', 213081),
  ('n5-d7960dc78d', '今日は終わりにしましょう。', NULL, NULL, 'Let''s call it a day.', 171599),
  ('n5-cdea017272', 'この音楽を聞いてくつろぎなさい。', 'この{音楽|おんがく}を{聞|き}いてくつろぎなさい。', NULL, 'Listen to this music and relax.', 222881),
  ('n5-cdea017272', 'ダンス音楽のレコードをかけてくれないか。', 'ダンス{音楽|おんがく}のレコードをかけてくれないか。', NULL, 'Will you play some dance records?', 203070),
  ('n5-980a922ad3', '人は男か女のどちらかである。', '{人|ひと}は{男|おとこ}か{女|おんな}のどちらかである。', NULL, 'A person is either male or female.', 144456),
  ('n5-980a922ad3', 'あの女のおしゃべりはまったくきりがない。', 'あの{女|おんな}のおしゃべりはまったくきりがない。', NULL, 'How that woman runs on!', 230895),
  ('n5-e6afab391a', '女の子はほとんどみんなやさしい。', '{女|おんな}の{子|こ}はほとんどみんなやさしい。', NULL, 'Almost all girls are kind.', 147335),
  ('n5-e6afab391a', 'ほかの女の子たちはどこにいるの。', 'ほかの{女|おんな}の{子|こ}たちはどこにいるの。', NULL, 'Where are the other girls?', 196427),
  ('n5-31a803c7f5', 'あなたは外国の本を持っていますか。', 'あなたは{外国|がいこく}の{本|ほん}を{持|も}っていますか。', NULL, 'Do you have any foreign books?', 232163),
  ('n5-31a803c7f5', 'ひとりで外国へ出かけてみなさい。', 'ひとりで{外国|がいこく}へ{出|で}かけてみなさい。', NULL, 'You must go to a foreign country for yourself.', 197481),
  ('n5-70f1678111', 'その外国人はかなりうまく日本語を話す。', 'その{外国人|がいこくじん}はかなりうまく{日本語|にほんご}を{話|はな}す。', NULL, 'The foreigner speaks Japanese fairly well.', 211699),
  ('n5-70f1678111', 'その外国人はまるで母語のように日本語を話した。', 'その{外国人|がいこくじん}はまるで{母語|ぼご}のように{日本語|にほんご}を{話|はな}した。', NULL, 'The foreigner spoke Japanese as if it were her mother tongue.', 211696),
  ('n5-2120ff505c', 'ビルは三年前にこの会社に入った。', 'ビルは{三年|さんねん}{前|#1392580}にこの{会社|かいしゃ}に{入|はい}った。', NULL, 'Bill joined our company three years ago.', 197326),
  ('n5-2120ff505c', '会社をクビにならなきゃいいけどね。', '{会社|かいしゃ}をクビにならなきゃいいけどね。', NULL, 'I hope I can hold on to my job.', 185231),
  ('n5-7cb27c411e', 'その階段を上ってはいけません。', NULL, NULL, 'You must not go up the stairs.', 211701),
  ('n5-7cb27c411e', '先生は階段をかけ上がった。', NULL, NULL, 'The teacher ran up the stairs.', 141655),
  ('n5-a771d4f949', '１日おきに買い物に行く。', NULL, NULL, 'I go shopping every other day.', 235706),
  ('n5-a771d4f949', 'ジェーンは買い物に出かけている。', 'ジェーンは{買|か}い{物|もの}に{出|で}かけている。', NULL, 'Jane is out shopping.', 216415),
  ('n5-bdb125e5c6', '買うかどうかはあなたしだいです。', '{買|か}うかどうかはあなたしだいです。', NULL, 'It is up to you whether to buy it or not.', 121489),
  ('n5-bdb125e5c6', '外国から買わなくてはなりません。', '{外国|がいこく}から{買|か}わなくてはなりません。', NULL, 'We have to buy them from abroad.', 184826),
  ('n5-8ea4b03d7f', '車はいつ返したらいいでしょうか。', '{車|くるま}はいつ{返|かえ}したらいいでしょうか。', NULL, 'When should I return the car?', 149018),
  ('n5-8ea4b03d7f', 'いつこれを返していただけますか。', 'いつこれを{返|かえ}していただけますか。', NULL, 'When will this be returned to me?', 228971),
  ('n5-1d22f1d023', '「帰ろ」「マックよってかない？」', '「{帰|かえ}ろ」「マックよってかない？」', NULL, '"Let''s head back." "Shall we drop by McDonald''s?"', 75070),
  ('n5-1d22f1d023', '父はちょうど帰ってきたところだ。', '{父|ちち}はちょうど{帰|かえ}ってきたところだ。', NULL, 'My father has just come home.', 84696),
  ('n5-687082e55c', 'どうしたらエンジンがかかりますか。', NULL, NULL, 'How can I start the engine?', 201593),
  ('n5-687082e55c', 'それはほとんど終わりかかっています。', 'それはほとんど{終|お}わりかかっています。', NULL, 'It''s almost over.', 205401),
  ('n5-e2d6576c76', '車のカギをなくしちゃった。', '{車|くるま}のカギをなくしちゃった。', NULL, 'I''ve lost my car key.', 149069),
  ('n5-e2d6576c76', 'ドアのカギをなくしたので家に入れない。', 'ドアのカギをなくしたので{家|いえ}に{入|い}れない。', NULL, 'I lost the door key, so I can''t enter the house.', 201870),
  ('n5-f7c7f35d9e', 'すぐに書かなければなりませんか。', 'すぐに{書|か}かなければなりませんか。', NULL, 'Should I fill it in now?', 214855),
  ('n5-f7c7f35d9e', 'これらの語をノートに書きなさい。', 'これらの{語|ご}をノートに{書|か}きなさい。', NULL, 'Write these words in your notebook.', 217911),
  ('n5-452102ad0a', '学生の半数が休んでいた。', '{学生|がくせい}の{半数|はんすう}が{休|やす}んでいた。', NULL, 'Half the students were absent.', 184267),
  ('n5-452102ad0a', 'ルシーはアメリカからきた学生だ。', 'ルシーはアメリカからきた{学生|がくせい}だ。', NULL, 'Lucy is a student from America.', 192389),
  ('n5-0ce2b98d3b', '１０円で電話がかけられますか。', '１０{円|えん}で{電話|でんわ}がかけられますか。', NULL, 'Can I make a phone call for ten yen?', 236074),
  ('n5-0ce2b98d3b', 'コックさんは少しもかけていない。', 'コックさんは{少|すこ}しもかけていない。', NULL, 'The cook hasn''t put any on it.', 224138),
  ('n5-6f54881e59', 'タクシーに傘を忘れてしまった。', 'タクシーに{傘|かさ}を{忘|わす}れてしまった。', NULL, 'I left my umbrella in the cab.', 203724);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-6f54881e59', '傘をもっていかなくてはならない。', '{傘|かさ}をもっていかなくてはならない。', NULL, 'I''ve got to take an umbrella with me.', 169468),
  ('n5-1122cac409', 'ホッチキスを貸してくれませんか。', 'ホッチキスを{貸|か}してくれませんか。', NULL, 'Will you please lend me a stapler?', 196239),
  ('n5-1122cac409', 'ヘアドライヤーを貸してください。', 'ヘアドライヤーを{貸|か}してください。', NULL, 'Can I borrow your hair drier?', 196870),
  ('n5-c1a28465a2', 'カーテンが風になびいた。', 'カーテンが{風|かぜ}になびいた。', NULL, 'The curtains blew in the wind.', 226491),
  ('n5-c1a28465a2', 'ただの風のいたずらだよ。', 'ただの{風|かぜ}のいたずらだよ。', NULL, 'It''s just a trick of the wind.', 203636),
  ('n5-c9b5da4d10', 'ただの風邪でしょう。', 'ただの{風邪|かぜ}でしょう。', NULL, 'You probably just have a cold.', 203635),
  ('n5-c9b5da4d10', 'かぜがなおるのに３週間かかった。', 'かぜがなおるのに３{週間|しゅうかん}かかった。', NULL, 'It took three weeks for me to get over my cold.', 226396),
  ('n5-1c9db63bdc', 'あなたの家族はきっと親切でしょう。', 'あなたの{家族|かぞく}はきっと{親切|しんせつ}でしょう。', NULL, 'Your family must be very nice.', 233420),
  ('n5-1c9db63bdc', '家族について聞いてもいいですか。', '{家族|かぞく}について{聞|き}いてもいいですか。', NULL, 'May I ask about your family?', 186951),
  ('n5-e34295f3e1', 'こちらはあなたがお話しになるお方です。', 'こちらはあなたがお{話|はな}しになるお{方|かた}です。', NULL, 'This is the man for you to speak to.', 224157),
  ('n5-e34295f3e1', 'お話になる方のお名前は。', 'お{話|はなし}になる{方|かた}のお{名前|なまえ}は。', NULL, 'Who do you want to speak to?', 226508),
  ('n5-dd8ac16bd2', 'この学校はたくさんの生徒がいます。', 'この{学校|がっこう}はたくさんの{生徒|せいと}がいます。', NULL, 'This school has many students.', 222600),
  ('n5-dd8ac16bd2', '学校を出たあと、どうするつもり？', '{学校|がっこう}を{出|で}たあと、どうするつもり？', NULL, 'What are you going to do after you leave school?', 184354),
  ('n5-613c41bd1d', 'テーブルの上にカップがある。', 'テーブルの{上|うえ}にカップがある。', NULL, 'There is a cup on the table.', 202407),
  ('n5-613c41bd1d', 'このカップは金でできている。', 'このカップは{金|きん}でできている。', NULL, 'The cup is made of gold.', 223900),
  ('n5-66eeeb818b', '食事は家庭で食べますか、外食ですか。', '{食事|しょくじ}は{家庭|かてい}で{食|た}べますか、{外食|がいしょく}ですか。', NULL, 'Do you eat at home or eat out?', 145834),
  ('n5-66eeeb818b', 'あなたの家庭のことを書いて下さい。', 'あなたの{家庭|かてい}のことを{書|か}いて{下|くだ}さい。', NULL, 'Please write about your home.', 233419),
  ('n5-4092bfd9bb', '角のテーブルがいいのですが。', '{角|かど}のテーブルがいいのですが。', NULL, 'Could we have a table in the corner?', 184544),
  ('n5-4092bfd9bb', 'あの角には、かつて本屋があった。', 'あの{角|かど}には、かつて{本屋|ほんや}があった。', NULL, 'There used to be a bookstore on that corner.', 231123),
  ('n5-6e6a06687d', 'これはジェーンさんのかばんです。', NULL, NULL, 'This is Jane''s bag.', 218609),
  ('n5-6e6a06687d', 'このかばんは６ポンドしました。', NULL, NULL, 'This bag cost me 6 pounds.', 223898),
  ('n5-749f78c9d1', '花びんに水を入れなさい。', NULL, NULL, 'Put some water into the vase.', 186606),
  ('n5-749f78c9d1', 'テーブルの上に花瓶がある。', 'テーブルの{上|うえ}に{花瓶|かびん}がある。', NULL, 'There is a vase on the table.', 202394),
  ('n5-cd08f9cdc2', '紙は木から作られる。', '{紙|かみ}は{木|き}から{作|つく}られる。', NULL, 'Paper is made from wood.', 151205),
  ('n5-cd08f9cdc2', '紙にはインクのしみがついていた。', '{紙|かみ}にはインクのしみがついていた。', NULL, 'The paper was blotted with ink.', 151214),
  ('n5-9d648d38ad', 'おじさんがぼくにカメラをくれました。', NULL, NULL, 'My uncle gave me a camera.', 227734),
  ('n5-9d648d38ad', 'このカメラはドイツでつくられた。', NULL, NULL, 'This camera was made in Germany.', 223885),
  ('n5-0dbf9ef8ca', '火曜日に国会が開かれる。', '{火曜日|かようび}に{国会|こっかい}が{開|ひら}かれる。', NULL, 'The Diet will meet on Tuesday.', 186646),
  ('n5-0dbf9ef8ca', '火曜日まで待ってもよいのではありませんか。', '{火曜日|かようび}まで{待|ま}ってもよいのではありませんか。', NULL, 'You might as well wait until Tuesday.', 186639),
  ('n5-d2546ac97b', 'このカレーは辛すぎて食べられない。', 'このカレーは{辛|から}すぎて{食|た}べられない。', NULL, 'This curry is too hot to eat.', 223874),
  ('n5-d2546ac97b', 'できるだけ辛くしてください。', 'できるだけ{辛|から}くしてください。', NULL, 'Make it as spicy as you can.', 202330),
  ('n5-a556e5edce', 'とりわけ体に気をつけなさい。', 'とりわけ{体|からだ}に{気|き}をつけなさい。', NULL, 'Above all, take care of yourself.', 199696),
  ('n5-a556e5edce', 'このスカートは体にちょうどよくあう。', 'このスカートは{体|からだ}にちょうどよくあう。', NULL, 'This skirt hangs nicely.', 223641),
  ('n5-8cd440a181', 'この本をお借りしてもよろしいですか。', 'この{本|ほん}をお{借|か}りしてもよろしいですか。', NULL, 'May I borrow this book?', 219525),
  ('n5-8cd440a181', '借りた本をなくしてしまいました。', '{借|か}りた{本|ほん}をなくしてしまいました。', NULL, 'I lost the book you lent me.', 148892),
  ('n5-a8b9eb425d', '軽く食べましょう。', '{軽|かる}く{食|た}べましょう。', NULL, 'Let''s catch a bite.', 176051),
  ('n5-a8b9eb425d', '朝食はたいてい軽くとります。', '{朝食|ちょうしょく}はたいてい{軽|かる}くとります。', NULL, 'I usually have a light breakfast.', 153039),
  ('n5-9decc44f4e', 'このレストランのカレーはうまいよ。', NULL, NULL, 'The curry at this restaurant is good.', 223009),
  ('n5-9decc44f4e', 'カレーはまあまあでした。', NULL, NULL, 'The curry was nothing special.', 76792),
  ('n5-6382448bd3', 'このカレンダーはどこにかけましょうか。', NULL, NULL, 'Where shall I hang this calendar?', 223871),
  ('n5-6382448bd3', '彼はカレンダーをめくった。', '{彼|かれ}はカレンダーをめくった。', NULL, 'He turned over a calendar.', 114085),
  ('n5-bcf12e002d', 'その川はあまりきれいではなかった。', 'その{川|かわ}はあまりきれいではなかった。', NULL, 'The river was not so clean.', 208510),
  ('n5-bcf12e002d', 'この川は長さ５００マイルです。', 'この{川|かわ}は{長|なが}さ５００マイルです。', NULL, 'This river is 500 miles in length.', 220796),
  ('n5-bad3423a93', 'ルーシーはかわいい女の子だ。', 'ルーシーはかわいい{女|おんな}の{子|こ}だ。', NULL, 'Lucy is a pretty little girl.', 192411),
  ('n5-bad3423a93', 'ナンシーさんはとてもかわいいそうです。', NULL, NULL, 'I hear that Nancy is very pretty.', 199013),
  ('n5-fdc787af58', 'この漢字はどういう意味ですか。', 'この{漢字|かんじ}はどういう{意味|いみ}ですか。', NULL, 'What does this kanji mean?', 222576),
  ('n5-fdc787af58', '君はこの漢字が読めますか。', '{君|きみ}はこの{漢字|かんじ}が{読|よ}めますか。', NULL, 'Can you read this kanji?', 177847),
  ('n5-22836046e2', 'その木には実がたわわになっていた。', 'その{木|き}には{実|み}がたわわになっていた。', NULL, 'The tree was heavy with fruit.', 206562),
  ('n5-22836046e2', '木はたとえあってもほとんどない。', '{木|き}はたとえあってもほとんどない。', NULL, 'There were few, if any, trees.', 80097),
  ('n5-5d679a1af2', '木の葉は秋には黄色になる。', '{木|こ}の{葉|は}は{秋|あき}には{黄色|きいろ}になる。', NULL, 'The leaves of the trees turn yellow in fall.', 80105);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-5d679a1af2', 'この花は黄色だが、ほかの花はみな青い。', 'この{花|はな}は{黄色|きいろ}だが、ほかの{花|はな}はみな{青|あお}い。', NULL, 'This flower is yellow, but all the others are blue.', 222733),
  ('n5-0b36c8d6c6', 'その黄色いのをいただきましょう。', 'その{黄色|きいろ}いのをいただきましょう。', NULL, 'I''ll take the yellow one.', 212174),
  ('n5-0b36c8d6c6', 'あれは黄色いチョークではありません。', 'あれは{黄色|きいろ}いチョークではありません。', NULL, 'That is not a yellow piece of chalk.', 229724),
  ('n5-6030b50276', '火が消えないようにしてください。', '{火|ひ}が{消|き}えないようにしてください。', NULL, 'Please keep the fire from going out.', 186758),
  ('n5-6030b50276', 'ろうそくはひとりでに消えた。', 'ろうそくはひとりでに{消|き}えた。', NULL, 'The candle went out of itself.', 192296),
  ('n5-dc19a213cd', 'ニューススタンドで聞いて下さい。', 'ニューススタンドで{聞|き}いて{下|くだ}さい。', NULL, 'You''ll have to ask at the newsstand.', 76494),
  ('n5-dc19a213cd', 'どこかで聞いたような気もするね。', 'どこかで{聞|き}いたような{気|き}もするね。', NULL, 'That rings a bell.', 201031),
  ('n5-fa320a51ea', 'その町はロンドンのすぐ北にある。', 'その{町|まち}はロンドンのすぐ{北|きた}にある。', NULL, 'The town lies just above London.', 207801),
  ('n5-fa320a51ea', '船はまっすぐ北に向かっている。', '{船|ふね}はまっすぐ{北|きた}に{向|む}かっている。', NULL, 'The ship is bearing due north.', 141143),
  ('n5-4fb1c0d758', 'どちらがあなたのギターですか。', NULL, NULL, 'Which is your guitar?', 200823),
  ('n5-4fb1c0d758', 'ギターをひくのはおもしろい。', NULL, NULL, 'Playing the guitar is fun.', 226059),
  ('n5-7d1cf1538b', 'ジャックは私に汚いいたずらをした。', 'ジャックは{私|わたし}に{汚|きたな}いいたずらをした。', NULL, 'Jack played a dirty trick on me.', 215815),
  ('n5-7d1cf1538b', 'まあ、なんて汚い客なんでしょう。', 'まあ、なんて{汚|きたな}い{客|きゃく}なんでしょう。', NULL, 'Gosh, what a dirty customer!', 195841),
  ('n5-5620a00afc', '私たちは喫茶店で昼食をとった。', '{私|わたし}たちは{喫茶店|きっさてん}で{昼食|ちゅうしょく}をとった。', NULL, 'We ate lunch in a coffee lounge.', 165940),
  ('n5-5620a00afc', 'この喫茶店でよくおしゃべりしたわね。', 'この{喫茶店|きっさてん}でよくおしゃべりしたわね。', NULL, 'We would often have a chat in this coffee shop.', 222392),
  ('n5-e101e41f54', '切手の上からサインをしてください。', '{切手|きって}の{上|うえ}からサインをしてください。', NULL, 'Sign across the stamp.', 142111),
  ('n5-e101e41f54', 'この切手のどちらでもあげよう。', 'この{切手|きって}のどちらでもあげよう。', NULL, 'I''ll give you either of these stamps.', 220864),
  ('n5-4fee5be397', 'この切符で二人入れるよ。', 'この{切符|きっぷ}で{二人|ふたり}{入|い}れるよ。', NULL, 'The ticket admits two persons.', 220860),
  ('n5-4fee5be397', 'このキップはこのバスでつかえますか。', NULL, NULL, 'Is this ticket good for this bus?', 223868),
  ('n5-a94a4be08f', 'きのう先生は今日テストをすると言った。', NULL, NULL, 'Yesterday the teacher told us that he would give us a test today.', 225950),
  ('n5-a94a4be08f', '昨日はなんともひどい天気だった。', NULL, NULL, 'The weather was miserable yesterday.', 169994),
  ('n5-8f81565ad7', '彼は「九時だ」と言った。', NULL, NULL, 'He said, "It''s nine o''clock."', 108121),
  ('n5-8f81565ad7', '九ページを開きなさい。', NULL, NULL, 'Open your book to page nine.', 179548),
  ('n5-b4faf372f3', '日本人はイギリス人より牛肉を食べる。', '{日本人|にほんじん}はイギリス{人|じん}より{牛肉|ぎゅうにく}を{食|た}べる。', NULL, 'The Japanese eat more beef than the British do.', 122271),
  ('n5-b4faf372f3', 'この牛肉は１ポンドにつき４ドルです。', 'この{牛肉|ぎゅうにく}は１ポンドにつき４ドルです。', NULL, 'This beef is four dollars per pound.', 222379),
  ('n5-797ae8d562', '牛乳はバターやチーズになります。', '{牛乳|ぎゅうにゅう}はバターやチーズになります。', NULL, 'Milk is made into butter and cheese.', 182280),
  ('n5-797ae8d562', '牛乳をチーズとバターにする。', '{牛乳|ぎゅうにゅう}をチーズとバターにする。', NULL, 'We make milk into cheese and butter.', 182266),
  ('n5-0400a204bd', '今日は何をしたいですか。', '{今日|きょう}は{何|なに}をしたいですか。', NULL, 'What would you like to do today?', 232046),
  ('n5-0400a204bd', '今日は父さんはそわそわしている。', NULL, NULL, 'Dad''s in an impatient mood today.', 171508),
  ('n5-85eb994887', 'ＬＬ教室を使ってもよいですか。', 'ＬＬ{教室|きょうしつ}を{使|つか}ってもよいですか。', NULL, 'May we use the language lab?', 234825),
  ('n5-85eb994887', 'エアロビクス教室に一日入学したいのですが。', NULL, NULL, 'I''d like to try out the aerobics class for a day.', 228037),
  ('n5-976c4f7174', 'あなたは何人兄弟がいますか。', NULL, NULL, 'How many siblings do you have?', 232196),
  ('n5-976c4f7174', 'あの人はトムの兄弟にちがいない。', 'あの{人|ひと}はトムの{兄弟|きょうだい}にちがいない。', NULL, 'He must be Tom''s brother.', 230736),
  ('n5-ec4e1dfc87', 'ビルは去年の秋に私に会いに来た。', 'ビルは{去年|きょねん}の{秋|あき}に{私|わたし}に{会|あ}いに{来|き}た。', NULL, 'Bill came to see me last autumn.', 197333),
  ('n5-ec4e1dfc87', 'わたしは去年一年生でした。', 'わたしは{去年|きょねん}{一年生|いちねんせい}でした。', NULL, 'I was a first year student last year.', 191813),
  ('n5-d106dac023', 'ジムくんは行き過ぎの嫌いがある。', 'ジムくんは{行|い}き{過|す}ぎの{嫌|きら}いがある。', NULL, 'Jim tends to go too far.', 76676),
  ('n5-d106dac023', 'いいや。あいつは水がキライなんだ。', 'いいや。あいつは{水|みず}がキライなんだ。', NULL, 'No. He doesn''t like water!', 229384),
  ('n5-cf23f5fba1', 'トランプをよく切ってください。', 'トランプをよく{切|き}ってください。', NULL, 'Please shuffle the cards carefully.', 199708),
  ('n5-cf23f5fba1', 'エアコンを切ってもかまいませんか。', 'エアコンを{切|き}ってもかまいませんか。', NULL, 'Do you mind if I turn off the AC?', 228042),
  ('n5-45fbcb8670', 'このセーターを着てごらんなさい。', 'このセーターを{着|き}てごらんなさい。', NULL, 'Try on this sweater.', 223601),
  ('n5-45fbcb8670', 'パーティーには何を着ていきますか。', 'パーティーには{何|なに}を{着|き}ていきますか。', NULL, 'What are you going to wear to the party?', 198497),
  ('n5-43cd9825f0', 'それからすっきりきれいにしてくれ。', NULL, NULL, 'Then clean it really well.', 205929),
  ('n5-43cd9825f0', 'その川はあまりきれいではなかった。', 'その{川|かわ}はあまりきれいではなかった。', NULL, 'The river was not so clean.', 208510),
  ('n5-36016e0c51', 'ヘレンはせいぜい４０キロだ。', NULL, NULL, 'Helen weighs not more than 40 kilograms.', 196669),
  ('n5-36016e0c51', 'この車は時速６０キロで走っている。', 'この{車|くるま}は{時速|じそく}６０キロで{走|はし}っている。', NULL, 'This car is going 60km an hour.', 221393),
  ('n5-a59efa3057', '銀行にどれだけお金がありますか。', '{銀行|ぎんこう}にどれだけお{金|かね}がありますか。', NULL, 'How much money do you have in the bank?', 179588),
  ('n5-a59efa3057', '銀行でお金をおろさなくちゃ。', '{銀行|ぎんこう}でお{金|かね}をおろさなくちゃ。', NULL, 'I have to withdraw some cash from the bank.', 179595),
  ('n5-b00c4af0a2', 'あなたは金曜日に何をするつもりですか。', 'あなたは{金曜日|きんようび}に{何|なに}をするつもりですか。', NULL, 'What will you do on Friday?', 232112),
  ('n5-b00c4af0a2', '金曜日の銀行は遅じまいだ。', '{金曜日|きんようび}の{銀行|ぎんこう}は{遅|おそ}じまいだ。', NULL, 'The bank shuts late on Fridays.', 179621),
  ('n5-95ccaa32f5', '４時間おきにこの薬をのみなさい。', '４{時間|じかん}おきにこの{薬|くすり}をのみなさい。', NULL, 'Take this medicine every four hours.', 235200);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-95ccaa32f5', '薬がなくなったら来てください。', '{薬|くすり}がなくなったら{来|き}てください。', NULL, 'Come back again when you finish your medicine.', 79501),
  ('n5-a36841ba49', 'ニューススタンドで聞いて下さい。', 'ニューススタンドで{聞|き}いて{下|くだ}さい。', NULL, 'You''ll have to ask at the newsstand.', 76494),
  ('n5-a36841ba49', '話があったら電話をかけて下さい。', '{話|はなし}があったら{電話|でんわ}をかけて{下|くだ}さい。', NULL, 'If you want to speak to me, please call me up.', 77204),
  ('n5-6b454b895e', '父はそんなに果物を食べないんです。', '{父|ちち}はそんなに{果物|くだもの}を{食|た}べないんです。', NULL, 'My father doesn''t eat all that much fruit.', 84708),
  ('n5-6b454b895e', '父はあんまり果物を食べません。', '{父|ちち}はあんまり{果物|くだもの}を{食|た}べません。', NULL, 'My father does not eat much fruit.', 84755),
  ('n5-a123a147d7', '口にものをほおばってしゃべるな。', '{口|くち}にものをほおばってしゃべるな。', NULL, 'Don''t speak with your mouth full.', 173943),
  ('n5-a123a147d7', 'なぜ、あなたの口はそんなに大きいの？', 'なぜ、あなたの{口|くち}はそんなに{大|おお}きいの？', NULL, 'Why is your mouth so big?', 199296),
  ('n5-9dd0572f05', '靴のほこりをはけではらいなさい。', '{靴|くつ}のほこりをはけではらいなさい。', NULL, 'Brush off the dust from your shoes.', 179254),
  ('n5-9dd0572f05', '靴のサイズはどれくらいですか。', '{靴|くつ}のサイズはどれくらいですか。', NULL, 'What size shoes do you wear?', 179255),
  ('n5-20a1278928', 'この靴下はちぐはぐだ。', 'この{靴下|くつした}はちぐはぐだ。', NULL, 'These socks do not match.', 237401),
  ('n5-20a1278928', 'この靴下の片方はどこだ。', 'この{靴下|くつした}の{片方|かたほう}はどこだ。', NULL, 'Where is the mate to this sock?', 222242),
  ('n5-b55dd305d1', 'あなたの国では何語を話しますか。', 'あなたの{国|くに}では{何語|なにご}を{話|はな}しますか。', NULL, 'What language do you speak in your country?', 233291),
  ('n5-b55dd305d1', 'この国はどのぐらいいるつもりですか。', 'この{国|くに}はどのぐらいいるつもりですか。', NULL, 'How long do you plan to stay in this country?', 221927),
  ('n5-eec0f93991', '曇りの日です。', '{曇|くも}りの{日|ひ}です。', NULL, 'It''s a cloudy day.', 123255),
  ('n5-eec0f93991', '今日は曇りのようですか。', NULL, NULL, 'Does it look cloudy today?', 171526),
  ('n5-c34fdb6092', '今日は曇っている。', NULL, NULL, 'It is cloudy today.', 171528),
  ('n5-c34fdb6092', '蒸気でメガネが曇ってしまった。', '{蒸気|じょうき}でメガネが{曇|くも}ってしまった。', NULL, 'The steam has fogged my glasses.', 146006),
  ('n5-01a0587b49', 'あたりがもう暗くなっていることに気がついた。', 'あたりがもう{暗|くら}くなっていることに{気|き}がついた。', NULL, 'I observed that it had already got dark.', 234367),
  ('n5-01a0587b49', '暗すぎてはっきりと見えない。', '{暗|くら}すぎてはっきりと{見|み}えない。', NULL, 'It is too dark to see clearly.', 191267),
  ('n5-72c04ce067', 'あいつはクラスでいちばんのまぬけだ。', NULL, NULL, 'He is the dumbest kid in the class.', 234637),
  ('n5-72c04ce067', 'このクラスには何人の男の子がいますか。', 'このクラスには{何人|なんにん}の{男|おとこ}の{子|こ}がいますか。', NULL, 'How many boys are there in this class?', 223857),
  ('n5-5538df2bce', 'プログラムをいただけますか。', NULL, NULL, 'May I have a program?', 196880),
  ('n5-5538df2bce', 'インスタグラムやってる？', NULL, NULL, 'Do you use Instagram?', 10704636),
  ('n5-2e2abd26ca', '１０時までに来ます。', '１０{時|じ}までに{来|き}ます。', NULL, 'I''ll come by 10.', 236043),
  ('n5-2e2abd26ca', '来てくださってどうもありがとう。', '{来|き}てくださってどうもありがとう。', NULL, 'Thank you for coming.', 78725),
  ('n5-d6b85573f3', '車のわきの男の子をごらんなさい。', '{車|くるま}のわきの{男|おとこ}の{子|こ}をごらんなさい。', NULL, 'Look at the boy beside the car.', 149061),
  ('n5-d6b85573f3', 'トレーラーがその車についている。', 'トレーラーがその{車|くるま}についている。', NULL, 'The trailer goes with the car.', 199672),
  ('n5-3c32cfb08a', '黒に黒をたしても白にはならぬ。', '{黒|くろ}に{黒|くろ}をたしても{白|しろ}にはならぬ。', NULL, 'Two blacks do not make a white.', 172985),
  ('n5-3c32cfb08a', '赤と黒のマジックかサインペン持ってない？', '{赤|あか}と{黒|くろ}のマジックかサインペン{持|も}ってない？', NULL, 'I need red and black markers or felt-tip pens. Do you have any?', 142223),
  ('n5-5e5300cf62', 'ナンシーはヘレンよりもほんのすこし色が黒い。', 'ナンシーはヘレンよりもほんのすこし{色|いろ}が{黒|くろ}い。', NULL, 'Nancy is a shade darker than Helen.', 198990),
  ('n5-5e5300cf62', 'あの黒いかばんはあなたのですか。', 'あの{黒|くろ}いかばんはあなたのですか。', NULL, 'Is that black bag yours?', 231019),
  ('n5-e1634cb3e9', '二人の警官もへとへとになった。', '{二人|ふたり}の{警官|けいかん}もへとへとになった。', NULL, 'The two policemen were exhausted, too.', 123109),
  ('n5-e1634cb3e9', '警官はその男をつけた。', '{警官|けいかん}はその{男|おとこ}をつけた。', NULL, 'The policeman followed him.', 176362),
  ('n5-9c1d724a61', '今朝はとても寒かった。', '{今朝|けさ}はとても{寒|さむ}かった。', NULL, 'It was very cold this morning.', 172291),
  ('n5-9c1d724a61', '今朝はするべきことがたくさんある。', '{今朝|けさ}はするべきことがたくさんある。', NULL, 'I have a lot of things to do this morning.', 172293),
  ('n5-19f270c68f', '寝る前に電気を消してください。', '{寝|ね}る{前|#1392580}に{電気|でんき}を{消|け}してください。', NULL, 'Turn off the light before you go to bed.', 145648),
  ('n5-19f270c68f', 'ローソクを消していただけますか。', 'ローソクを{消|け}していただけますか。', NULL, 'Would you put out the candles?', 192284),
  ('n5-dd34250740', 'いや結構です。たくさんいただきました。', 'いや{結構|けっこう}です。たくさんいただきました。', NULL, 'No more, thank you. I''m full.', 228472),
  ('n5-dd34250740', 'どちらの日でも結構です。', 'どちらの{日|ひ}でも{結構|けっこう}です。', NULL, 'Either day is OK.', 200732),
  ('n5-2eb252da72', 'ジョンはジェーンと結婚していた。', 'ジョンはジェーンと{結婚|けっこん}していた。', NULL, 'John was married to Jane.', 215406),
  ('n5-2eb252da72', 'いったん結婚したらおしまいだよ。', 'いったん{結婚|けっこん}したらおしまいだよ。', NULL, 'Once you are married, you are done for.', 228877),
  ('n5-04e80a2ba1', '月曜日までにここに来ています。', '{月曜日|げつようび}までにここに{来|き}ています。', NULL, 'I''ll be here by Monday.', 175591),
  ('n5-04e80a2ba1', '月曜日以外ならいつでもいいですよ。', '{月曜日|げつようび}{以外|いがい}ならいつでもいいですよ。', NULL, 'Any day will do except Monday.', 175588),
  ('n5-2e1642b248', '玄関のカギはどうなっていますか。', '{玄関|げんかん}のカギはどうなっていますか。', NULL, 'How does the front-door lock work?', 174948),
  ('n5-2e1642b248', 'コートは玄関のところにかけてください。', 'コートは{玄関|げんかん}のところにかけてください。', NULL, 'Hang your coat in the hall, please.', 224964),
  ('n5-442c4aa1ca', 'こんにちは、ロジャー。とっても元気よ。', 'こんにちは、ロジャー。とっても{元気|げんき}よ。', NULL, 'Hi, Roger. I''m pretty good!', 217292),
  ('n5-442c4aa1ca', '先生はまたすっかり元気になった。', '{先生|せんせい}はまたすっかり{元気|げんき}になった。', NULL, 'The teacher got quite well again.', 141667),
  ('n5-47c1fdbe2f', 'どこかは今五時だろう。', NULL, NULL, 'It''s five o''clock somewhere now.', 201024),
  ('n5-47c1fdbe2f', 'これは日本円で五千円です。', NULL, NULL, 'This is five thousand yen in the Japanese Yen.', 218159),
  ('n5-05cf590971', 'この公園はすべての人に公開されている。', 'この{公園|こうえん}はすべての{人|ひと}に{公開|こうかい}されている。', NULL, 'The park is open to everybody.', 222003);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-05cf590971', '二つの公園の間に川がありますか。', '{二|ふた}つの{公園|こうえん}の{間|あいだ}に{川|かわ}がありますか。', NULL, 'Is there a river between the two parks?', 123167),
  ('n5-8699b8bec2', 'あの交差点で何が起こったのか。', 'あの{交差点|こうさてん}で{何|なに}が{起|お}こったのか。', NULL, 'What happened at that crossing?', 231036),
  ('n5-8699b8bec2', 'この交差点は何と呼ばれていますか。', 'この{交差点|こうさてん}は{何|なに}と{呼|よ}ばれていますか。', NULL, 'What''s the name of this intersection?', 222010),
  ('n5-1288e600be', '紅茶かコーヒーはいかがですか。', '{紅茶|こうちゃ}かコーヒーはいかがですか。', NULL, 'Care for tea or coffee?', 173507),
  ('n5-1288e600be', 'これはなかなかおいしい紅茶だ。', 'これはなかなかおいしい{紅茶|こうちゃ}だ。', NULL, 'This is a very good tea.', 218548),
  ('n5-402eb0d21f', '向こうの交番で聞いてください。', '{向|む}こうの{交番|こうばん}で{聞|き}いてください。', NULL, 'Ask at the police station over there.', 173841),
  ('n5-402eb0d21f', '交番はどこにあるかわかりますか。', '{交番|こうばん}はどこにあるかわかりますか。', NULL, 'Do you know where the police station is?', 174098),
  ('n5-d890e45616', 'あなたの声が聞けてうれしいわ。', 'あなたの{声|こえ}が{聞|き}けてうれしいわ。', NULL, 'I am happy to hear your voice.', 1142225),
  ('n5-d890e45616', 'もっと大きな声で話してください。', 'もっと{大|おお}きな{声|こえ}で{話|はな}してください。', NULL, 'Speak louder, please.', 193232),
  ('n5-c552e79d34', 'このコートいいですね。試着してもいいですか。', 'このコートいいですね。{試着|しちゃく}してもいいですか。', NULL, 'I like this coat. May I try it on?', 1171687),
  ('n5-67126059f1', 'そのコーヒーはいいにおいがする。', NULL, NULL, 'That coffee smells good.', 213210),
  ('n5-67126059f1', 'コーヒーをもういっぱいください。', NULL, NULL, 'Give me another cup of coffee.', 224880),
  ('n5-9a7c962266', '午後何時ごろうかがいましょうか。', '{午後|ごご}{何時|なんじ}ごろうかがいましょうか。', NULL, 'When shall I call on you this afternoon?', 174382),
  ('n5-9a7c962266', '午後にはテニスをするつもりです。', '{午後|ごご}にはテニスをするつもりです。', NULL, 'I am going to play tennis in the afternoon.', 174404),
  ('n5-f114f6f499', 'スピーチコンテストは１１月９日に行われた。', NULL, NULL, 'The speech contest took place on the ninth of November.', 214544),
  ('n5-f114f6f499', '大会９日目、ベスト８が出揃った。', NULL, NULL, 'The top eight players survived the ninth day of the tournament.', 137653),
  ('n5-cff3c57405', '私たちの学校にはクラスが９つある。', '{私|わたし}たちの{学校|がっこう}にはクラスが９つある。', NULL, 'Our school has nine classes.', 167043),
  ('n5-cff3c57405', '彼の英作文には９行に９つの誤りがあります。', NULL, NULL, 'His English composition has nine mistakes in as many lines.', 118095),
  ('n5-c92dbe626a', 'その電車は午前９時にここを出発します。', 'その{電車|でんしゃ}は{午前|ごぜん}９{時|じ}にここを{出発|しゅっぱつ}します。', NULL, 'The train departs here at 9:00 a.m.', 207576),
  ('n5-c92dbe626a', '午前１０時に駅であいましょう。', '{午前|ごぜん}１０{時|じ}に{駅|えき}であいましょう。', NULL, 'I will meet you at the station at 10 a.m.', 174378),
  ('n5-d5d8c608aa', '「はい、ありません」とジョーダンさんは答えた。', '「はい、ありません」とジョーダンさんは{答|こた}えた。', NULL, '"No, I don''t," said Mr Jordan.', 236468),
  ('n5-d5d8c608aa', '何と答えていいかわかりません。', '{何|なん}と{答|こた}えていいかわかりません。', NULL, 'I don''t know how to reply to that question.', 187740),
  ('n5-a9191729e3', 'コーヒー、ごちそうさまでした。', NULL, NULL, 'Thank you for the coffee.', 10156656),
  ('n5-a9191729e3', 'もうごちそうさましなさい。', NULL, NULL, 'Now, say thank you for the meal.', 11264757),
  ('n5-e9e492c68a', '今のところこちらだけになります。', '{今|いま}のところこちらだけになります。', NULL, 'The only one we have is this one here.', 172739),
  ('n5-e9e492c68a', 'こちらにサインをいただけますか？', NULL, NULL, 'Could you sign here, please?', 3281203),
  ('n5-be9b8bcb5e', 'こっちへ来い、ぐずぐずしないで。', 'こっちへ{来|こ}い、ぐずぐずしないで。', NULL, 'Get over here and be quick about it!', 224125),
  ('n5-be9b8bcb5e', 'こっちへ来てこれを見てごらん。', 'こっちへ{来|き}てこれを{見|み}てごらん。', NULL, 'Come here and have a look at it.', 224124),
  ('n5-0020b9ee4e', '今年もよい年でありますように。', '{今年|ことし}もよい{年|とし}でありますように。', NULL, 'May the new year bring you happiness!', 171289),
  ('n5-0020b9ee4e', '今年の六月はあまり雨の日がなかった。', '{今年|ことし}の{六月|ろくがつ}はあまり{雨|あめ}の{日|ひ}がなかった。', NULL, 'There were not many rainy days in June this year.', 171353),
  ('n5-491cfa69be', '言葉が出てこなかった。', '{言葉|ことば}が{出|で}てこなかった。', NULL, 'Words failed me.', 174713),
  ('n5-491cfa69be', 'その言葉はラテン語から来ている。', 'その{言葉|ことば}はラテン{語|ご}から{来|き}ている。', NULL, 'The word is derived from Latin.', 210904),
  ('n5-1f4bb6e503', 'あなたには何人子供がいますか。', NULL, NULL, 'How many children do you have?', 233758),
  ('n5-1f4bb6e503', '子どもはじっとしていないものだ。', NULL, NULL, 'Children don''t keep still.', 168864),
  ('n5-bd3a2ad2ad', 'このコップをミルクで満たした。', 'このコップをミルクで{満|み}たした。', NULL, 'I filled this glass with milk.', 223794),
  ('n5-bd3a2ad2ad', 'この木にしっかりつかまりなさい。', 'この{木|き}にしっかりつかまりなさい。', NULL, 'Hold fast to this tree.', 219456),
  ('n5-a2694d259e', 'ご飯とパンどちらがいいですか。', 'ご{飯|はん}とパンどちらがいいですか。', NULL, 'Which do you prefer, rice or bread?', 217034),
  ('n5-a2694d259e', '友達にご飯をおごってもらった。', '{友達|ともだち}にご{飯|はん}をおごってもらった。', NULL, 'My friends treated me to a meal.', 79311),
  ('n5-f586d7d023', 'コピーするページに付箋をつけておいてください。', 'コピーするページに{付箋|ふせん}をつけておいてください。', NULL, 'Put a tag on the pages you want copied.', 219109),
  ('n5-f586d7d023', '著者の許可なしに本をコピーすることは違法です。', '{著者|ちょしゃ}の{許可|きょか}なしに{本|ほん}をコピーすることは{違法|いほう}です。', NULL, 'It is illegal to copy from books without the author''s permission.', 126291),
  ('n5-61994485cb', '時間がなくてたいへん困っている。', '{時間|じかん}がなくてたいへん{困|こま}っている。', NULL, 'I am pressed for time.', 150625),
  ('n5-61994485cb', '車のことで困ってるんだよね。', '{車|くるま}のことで{困|こま}ってるんだよね。', NULL, 'I have a problem with my car.', 149067),
  ('n5-4a11eb5fb4', 'お話し中、ごめんなさい。', 'お{話|はな}し{中|ちゅう}、ごめんなさい。', NULL, 'Excuse me for interrupting you.', 226510),
  ('n5-4a11eb5fb4', 'ごめんなさい、でもよく聞こえないんです。', 'ごめんなさい、でもよく{聞|き}こえないんです。', NULL, 'I''m sorry, but I can''t hear you well.', 219061),
  ('n5-6313cc9cb5', 'これは兄です。かっこいいですね。', 'これは{兄|あに}です。かっこいいですね。', NULL, 'This is my brother. Handsome, isn''t he?', 74148),
  ('n5-6313cc9cb5', 'これはいったいどういうことなの。', NULL, NULL, 'What does all this add up to?', 143331),
  ('n5-3793173687', '今月の売り上げはよくない。', '{今月|こんげつ}の{売|う}り{上|あ}げはよくない。', NULL, 'Sales have been off this month.', 172460),
  ('n5-3793173687', '今月いっぱいここにいます。', '{今月|こんげつ}いっぱいここにいます。', NULL, 'I will stay here all this month.', 172471),
  ('n5-7a27eadef1', '今週はどちらにいらしゃいましたか。', '{今週|こんしゅう}はどちらにいらしゃいましたか。', NULL, 'Where have you been this week?', 172375),
  ('n5-7a27eadef1', '今週あなたは何をしていましたか。', '{今週|こんしゅう}あなたは{何|なに}をしていましたか。', NULL, 'What have you been doing this week?', 172390);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-e1978f90df', 'こんな本を読んで何になるのか。', 'こんな{本|ほん}を{読|よ}んで{何|なに}になるのか。', NULL, 'What is the good of reading such books?', 217309),
  ('n5-e1978f90df', 'こんな日には外出したくない。', 'こんな{日|ひ}には{外出|がいしゅつ}したくない。', NULL, 'I don''t feel like going out on such a day.', 217322),
  ('n5-0a65b39cf7', 'こんにちはジョージ、どう？', NULL, NULL, 'Hi, George! How''s it going?', 217287),
  ('n5-0a65b39cf7', 'こんにちは、ジャッキー・スコットさんですか。', NULL, NULL, 'Hello. Are you Jackie Scott?', 217298),
  ('n5-eb1c9a5df9', '今晩はパーティーがあるのかなあ。', '{今晩|こんばん}はパーティーがあるのかなあ。', NULL, 'Is there going to be a party tonight?', 171245),
  ('n5-eb1c9a5df9', '今晩チェスをしてはどうですか。', '{今晩|こんばん}チェスをしてはどうですか。', NULL, 'How about playing chess tonight?', 171264),
  ('n5-6c0551dd8a', 'シカゴのみなさん、こんばんは。', NULL, NULL, 'Hello, Chicago!', 347753),
  ('n5-6c0551dd8a', 'こんばんは。', NULL, NULL, 'Good evening.', 426900),
  ('n5-7ba7ba2434', 'さあ、パーティーをおしまいにしよう。', NULL, NULL, 'Let''s break up the party.', 216960),
  ('n5-7ba7ba2434', 'みんな。さあ聞きなさい。', 'みんな。さあ{聞|き}きなさい。', NULL, 'Boys! Now listen.', 195024),
  ('n5-a96e3a2b33', 'サイフがないのにふと気がついた。', 'サイフがないのにふと{気|き}がついた。', NULL, 'He suddenly noticed his wallet was missing.', 216852),
  ('n5-a96e3a2b33', '財布とパスポートがなくなってます。', '{財布|さいふ}とパスポートがなくなってます。', NULL, 'My wallet and passport are missing.', 170210),
  ('n5-dbd7cd319c', '日本人は魚をたくさん食べますか。', '{日本人|にほんじん}は{魚|さかな}をたくさん{食|た}べますか。', NULL, 'Do Japanese eat a lot of fish?', 122254),
  ('n5-dbd7cd319c', '魚は水中でなければ生きられない。', '{魚|さかな}は{水中|すいちゅう}でなければ{生|い}きられない。', NULL, 'Fish cannot live out of water.', 182097),
  ('n5-20fcc4f54f', 'それから先の話を聞きたい。', NULL, NULL, 'I''d like to know the rest of the story.', 205916),
  ('n5-20fcc4f54f', 'もうちょっと先までいってください。', 'もうちょっと{先|さき}までいってください。', NULL, 'It''s just a little further.', 194388),
  ('n5-4c39babf5f', 'チューリップがみごとに咲いた。', 'チューリップがみごとに{咲|さ}いた。', NULL, 'The tulips have come out beautifully.', 202946),
  ('n5-4c39babf5f', 'これらの花は春に咲く。', 'これらの{花|はな}は{春|はる}に{咲|さ}く。', NULL, 'These flowers bloom in spring.', 217953),
  ('n5-c10cb3070d', '作文は書いてしまいましたか。', '{作文|さくぶん}は{書|か}いてしまいましたか。', NULL, 'Have you finished writing your composition?', 170165),
  ('n5-c10cb3070d', '「友情」という題で作文を書きなさい。', '「{友情|ゆうじょう}」という{題|だい}で{作文|さくぶん}を{書|か}きなさい。', NULL, 'Write an essay on "Friendship".', 236141),
  ('n5-4e2aefb855', '彼は雨の中を傘もささずに歩きつづけた。', '{彼|かれ}は{雨|あめ}の{中|なか}を{傘|かさ}もささずに{歩|ある}きつづけた。', NULL, 'He went on walking in the rain without an umbrella.', 109822),
  ('n5-4e2aefb855', '彼女はジリジリするような日差しの中で、傘をさした。', '{彼女|かのじょ}はジリジリするような{日差|ひざ}しの{中|なか}で、{傘|かさ}をさした。', NULL, 'She put up an umbrella against a scorching sun.', 92769),
  ('n5-a371cc6a54', 'その雑誌はどこで買えますか。', 'その{雑誌|ざっし}はどこで{買|か}えますか。', NULL, 'Where can I buy that magazine?', 210481),
  ('n5-a371cc6a54', 'そんな雑誌を読むのはばかげている。', 'そんな{雑誌|ざっし}を{読|よ}むのはばかげている。', NULL, 'It is foolish to read such a magazine.', 204129),
  ('n5-8af5030b7a', 'ポットにはあまり砂糖がなかった。', 'ポットにはあまり{砂糖|さとう}がなかった。', NULL, 'There wasn''t much sugar in the pot.', 196232),
  ('n5-8af5030b7a', '砂糖なしですまさなければならない。', '{砂糖|さとう}なしですまさなければならない。', NULL, 'We have to do without sugar.', 170890),
  ('n5-688bc67044', '寒いからコートを着るべきだ。', '{寒|さむ}いからコートを{着|き}るべきだ。', NULL, 'It''s cold so you should wear a coat.', 184049),
  ('n5-688bc67044', '天気は寒いだけでなく雨であった。', '{天気|てんき}は{寒|さむ}いだけでなく{雨|あめ}であった。', NULL, 'The weather was not only cold, but also wet.', 125110),
  ('n5-0a1f511640', 'では今晩またね、さようなら。', 'では{今晩|こんばん}またね、さようなら。', NULL, 'See you tonight, then. Cheers!', 202137),
  ('n5-0a1f511640', 'さようなら。また会いましょう。', 'さようなら。また{会|あ}いましょう。', NULL, 'I''ll be seeing you.', 216704),
  ('n5-45c705d5b2', '祖父は、再来年引退する予定です。', '{祖父|そふ}は、{再来年|さらいねん}{引退|いんたい}する{予定|よてい}です。', NULL, 'My grandfather is planning to retire the year after next.', 140720),
  ('n5-5cb07674a3', '二、三デメリットがありますね。', NULL, NULL, 'There are a few disadvantages to it.', 123182),
  ('n5-5cb07674a3', 'この本は三千円する。', NULL, NULL, 'This book costs 3,000 yen.', 219631),
  ('n5-e2695084c9', '散歩に出かけてもよろしいですか。', '{散歩|さんぽ}に{出|で}かけてもよろしいですか。', NULL, 'May I go out for a walk?', 169336),
  ('n5-e2695084c9', 'ちょっとそこまで散歩に出よう。', 'ちょっとそこまで{散歩|さんぽ}に{出|で}よう。', NULL, 'Let''s step out for a short walk.', 76557),
  ('n5-da4b805e0b', '列車でならここからたった四分だ。', NULL, NULL, 'It''s only four minutes from here by train.', 77561),
  ('n5-da4b805e0b', '月に三ないし四回映画を見に行く。', NULL, NULL, 'I go to the movies three or four times a month.', 175658),
  ('n5-b366a3d677', 'このスープは塩が少し足りない。', 'このスープは{塩|しお}が{少|すこ}し{足|た}りない。', NULL, 'This soup wants a bit of salt.', 223651),
  ('n5-b366a3d677', '塩をこっちへまわしてくれませんか。', '{塩|しお}をこっちへまわしてくれませんか。', NULL, 'Pass me the salt, would you?', 188597),
  ('n5-2c41aedcba', 'しかしこの本をしまっておきなさい。', 'しかしこの{本|ほん}をしまっておきなさい。', NULL, 'However, please put this book away first.', 216279),
  ('n5-2c41aedcba', 'しかし、人間はちがっている。', 'しかし、{人間|にんげん}はちがっている。', NULL, 'But human beings are different.', 216307),
  ('n5-d5c916ca85', 'いつだって読書の時間は見つけられる。', 'いつだって{読書|どくしょ}の{時間|じかん}は{見|み}つけられる。', NULL, 'We can always find time for reading.', 228889),
  ('n5-d5c916ca85', '時間がたつのに気がつかなかった。', '{時間|じかん}がたつのに{気|き}がつかなかった。', NULL, 'I took no note of the time.', 150629),
  ('n5-573bc15b1d', '仕事をサボったからクビになった。', '{仕事|しごと}をサボったからクビになった。', NULL, 'He got the sack for slacking off at work.', 76109),
  ('n5-573bc15b1d', 'どの仕事もやすやすとはできない。', 'どの{仕事|しごと}もやすやすとはできない。', NULL, 'No work can be done with ease.', 200317),
  ('n5-8ec35978bd', 'それはどの辞書にもでています。', 'それはどの{辞書|じしょ}にもでています。', NULL, 'You find it in any dictionary.', 205423),
  ('n5-8ec35978bd', 'これこそずっとほしかった辞書です。', 'これこそずっとほしかった{辞書|じしょ}です。', NULL, 'This is the very dictionary that I have wanted so long.', 218820),
  ('n5-178469ba7a', 'キャプテンは静かにするように命じた。', 'キャプテンは{静|しず}かにするように{命|めい}じた。', NULL, 'The captain commanded silence.', 225839),
  ('n5-178469ba7a', '静かにするように気をつけなさい。', '{静|しず}かにするように{気|き}をつけなさい。', NULL, 'See to it that you keep quiet.', 142511),
  ('n5-dd36cae3a9', 'クッキーはテーブルの下にいる。', 'クッキーはテーブルの{下|した}にいる。', NULL, 'Cookie is under the table.', 225669);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-dd36cae3a9', '木の下にベンチがあります。', '{木|き}の{下|した}にベンチがあります。', NULL, 'There is a bench under the tree.', 80128),
  ('n5-988db98632', 'どういっても七時までにいかないと。', NULL, NULL, 'However we go, we must get there by seven.', 201696),
  ('n5-988db98632', 'ちょうど七時半です。', NULL, NULL, 'It is just half past seven.', 202909),
  ('n5-2c5c99977c', 'あの先生に質問してもいいですよ。', 'あの{先生|せんせい}に{質問|しつもん}してもいいですよ。', NULL, 'You may ask a question of that teacher.', 230657),
  ('n5-2c5c99977c', '質問は書いていただけませんか。', '{質問|しつもん}は{書|か}いていただけませんか。', NULL, 'Will you put your questions in written form?', 149514),
  ('n5-ebf194a316', 'ぼくの自転車はパンクしている。', 'ぼくの{自転車|じてんしゃ}はパンクしている。', NULL, 'My bicycle has a flat tire.', 196377),
  ('n5-ebf194a316', 'マユコは自転車で学校にいく。', 'マユコは{自転車|じてんしゃ}で{学校|がっこう}にいく。', NULL, 'Mayuko goes to school by bicycle.', 195201),
  ('n5-78fd1a0e8a', '自動車にひかれたのではないですか。', '{自動車|じどうしゃ}にひかれたのではないですか。', NULL, 'Wasn''t he killed by a car?', 150044),
  ('n5-78fd1a0e8a', 'ぼくの自動車はずいぶんガソリンをくう。', 'ぼくの{自動車|じどうしゃ}はずいぶんガソリンをくう。', NULL, 'My car burns a lot of gas.', 196376),
  ('n5-ec6fd2f845', 'その少年は死んだものとしてあきらめられた。', 'その{少年|しょうねん}は{死|し}んだものとしてあきらめられた。', NULL, 'The boy was given up for dead.', 209091),
  ('n5-ec6fd2f845', '生きるものはすべていつかは死ぬ。', '{生|い}きるものはすべていつかは{死|し}ぬ。', NULL, 'All living things die some day.', 142836),
  ('n5-6156bfb418', 'ジョンソンさんはまるで生き字引です。', 'ジョンソンさんはまるで{生|い}き{字引|じびき}です。', NULL, 'Mr Johnson is, as it were, a walking dictionary.', 215504),
  ('n5-6156bfb418', '私たちの先生は、いわば、生き字引だ。', '{私|わたし}たちの{先生|せんせい}は、いわば、{生|い}き{字引|じびき}だ。', NULL, 'Our teacher is, as it were, a walking dictionary.', 166907),
  ('n5-995a632b12', '自分でそれをしなければならない。', '{自分|じぶん}でそれをしなければならない。', NULL, 'You must do it for yourself.', 149971),
  ('n5-995a632b12', '自分のペースでやってください。', '{自分|じぶん}のペースでやってください。', NULL, 'You can take your time.', 149918),
  ('n5-01420cdf0f', 'あいにく店は閉まっていた。', 'あいにく{店|みせ}は{閉|し}まっていた。', NULL, 'Unfortunately, the store was closed.', 234558),
  ('n5-01420cdf0f', 'ドアが閉まっていたので、入ることが出来なかった。', NULL, NULL, 'The door was locked, so I couldn''t get in.', 201896),
  ('n5-8e6c15bef9', 'いつもシートベルトを締めなさい。', 'いつもシートベルトを{締|し}めなさい。', NULL, 'Always fasten your seatbelt.', 228764),
  ('n5-8e6c15bef9', 'シートベルトをお締めください。', 'シートベルトをお{締|し}めください。', NULL, 'Please fasten your seat belt.', 216597),
  ('n5-95827b08e3', 'どうかドアを閉めてくれませんか。', 'どうかドアを{閉|し}めてくれませんか。', NULL, 'Will you please shut the door?', 201657),
  ('n5-95827b08e3', 'このデパートは７時に閉められる。', 'このデパートは７{時|じ}に{閉|し}められる。', NULL, 'This department store is closed at seven.', 223505),
  ('n5-091c8c0e07', 'じゃあ、キーをもらえますか。', NULL, NULL, 'Can I have the key now, please?', 215913),
  ('n5-091c8c0e07', 'じゃまた後から来ます。', 'じゃまた{後|あと}から{来|き}ます。', NULL, 'Then I''ll come again later.', 215754),
  ('n5-5101640e7e', 'なんてキレイな写真なんでしょう。', 'なんてキレイな{写真|しゃしん}なんでしょう。', NULL, 'What a beautiful picture!', 198939),
  ('n5-5101640e7e', 'ここにあなたに見せる写真がある。', 'ここにあなたに{見|み}せる{写真|しゃしん}がある。', NULL, 'Here is a picture to show you.', 224510),
  ('n5-f71424e3ff', 'シャツにアイロンをかけてください。', NULL, NULL, 'Please iron the shirt.', 215784),
  ('n5-f71424e3ff', 'このシャツはだれのですか。', NULL, NULL, 'Whose shirt is this?', 223699),
  ('n5-d9c88143a2', 'シャワーの水が出ません。', 'シャワーの{水|みず}が{出|で}ません。', NULL, 'There''s no water coming out of the shower.', 215745),
  ('n5-d9c88143a2', 'シャワーにするわ。', NULL, NULL, 'I''ll take a shower.', 215746),
  ('n5-db9f5d4422', 'その会は十時に終わった。', NULL, NULL, 'The party ended at ten o''clock.', 211902),
  ('n5-db9f5d4422', '日本に来てから十年になります。', NULL, NULL, 'It is ten years since he came to Japan.', 122693),
  ('n5-5bae559507', 'それは授業の終わりだった。', 'それは{授業|じゅぎょう}の{終|お}わりだった。', NULL, 'That was the end of the class.', 205089),
  ('n5-5bae559507', 'そんなに授業をさぼっちゃダメよ。', 'そんなに{授業|じゅぎょう}をさぼっちゃダメよ。', NULL, 'Don''t cut your classes so often.', 204268),
  ('n5-4daa103d7d', '宿題はもうやってしまいましたか。', '{宿題|しゅくだい}はもうやってしまいましたか。', NULL, 'Have you done your assignment yet?', 147882),
  ('n5-4daa103d7d', 'やるべき宿題がたくさんあります。', 'やるべき{宿題|しゅくだい}がたくさんあります。', NULL, 'I have a lot of homework to do.', 193016),
  ('n5-1763fc412a', 'あなたは上手にバスケットボールができますか。', NULL, NULL, 'Do you play basketball well?', 231837),
  ('n5-1763fc412a', 'マイクは日本語を話すのが上手だ。', 'マイクは{日本語|にほんご}を{話|はな}すのが{上手|じょうず}だ。', NULL, 'Mike speaks good Japanese.', 195731),
  ('n5-50525927ee', 'このロープはとてもじょうぶだ。', NULL, NULL, 'This rope is very tough.', 222994),
  ('n5-50525927ee', '彼は丈夫だったそうです。', '{彼|かれ}は{丈夫|じょうぶ}だったそうです。', NULL, 'He is said to have been strong.', 103983),
  ('n5-9476d7966d', '同社は醤油その他の食品を生産する。', '{同社|どうしゃ}は{醤油|しょうゆ}その{他|ほか}の{食品|しょくひん}を{生産|せいさん}する。', NULL, 'The company produces soy sauce and other food products.', 123656),
  ('n5-dcc87a37fb', '食堂はセルフサービスでした。', '{食堂|しょくどう}はセルフサービスでした。', NULL, 'The cafeteria was self-service.', 145792),
  ('n5-dcc87a37fb', '食堂は何時にあきますか。', '{食堂|しょくどう}は{何時|なんじ}にあきますか。', NULL, 'What time does the dining room open?', 145790),
  ('n5-1fcb2fece8', 'ぼくは知らないし、気にもしない。', 'ぼくは{知|し}らないし、{気|き}にもしない。', NULL, 'I don''t know, nor do I care.', 196304),
  ('n5-1fcb2fece8', 'ブラウンさんを知らないのですか。', 'ブラウンさんを{知|し}らないのですか。', NULL, 'Don''t you know Mr. Brown?', 197075),
  ('n5-98eace7008', '黒に黒をたしても白にはならぬ。', '{黒|くろ}に{黒|くろ}をたしても{白|しろ}にはならぬ。', NULL, 'Two blacks do not make a white.', 172985),
  ('n5-98eace7008', '赤白まだらのタオルを一本ください。', NULL, NULL, 'A red and spotted white towel, please.', 142119),
  ('n5-8997f64f52', '白いベルトがついてるのがいいな。', '{白|しろ}いベルトがついてるのがいいな。', NULL, 'I like the one with a white belt.', 121433),
  ('n5-8997f64f52', 'それはここからでは白く見える。', 'それはここからでは{白|しろ}く{見|み}える。', NULL, 'It shows white from here.', 205517),
  ('n5-b8317395af', 'ジョンのことが新聞に出ていた。', 'ジョンのことが{新聞|しんぶん}に{出|で}ていた。', NULL, 'John was mentioned in the paper.', 215457),
  ('n5-b8317395af', '新聞はもうおすみになりましたか。', '{新聞|しんぶん}はもうおすみになりましたか。', NULL, 'Are you through with the paper?', 145135);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-44d9d70862', '今度の水曜日ならいいですよ。', '{今度|こんど}の{水曜日|すいようび}ならいいですよ。', NULL, 'Next Wednesday will be fine.', 172151),
  ('n5-44d9d70862', '彼女は先週の水曜日から病気です。', '{彼女|かのじょ}は{先週|せんしゅう}の{水曜日|すいようび}から{病気|びょうき}です。', NULL, 'She has been sick since last Wednesday.', 88253),
  ('n5-e82727193e', 'この紙はインクを吸わない。', 'この{紙|かみ}はインクを{吸|す}わない。', NULL, 'This paper does not absorb ink.', 221731),
  ('n5-e82727193e', '大人になったらパイプを吸っていいよ。', '{大人|おとな}になったらパイプを{吸|す}っていいよ。', NULL, 'You can smoke a pipe when you grow up.', 137481),
  ('n5-f0f5f6b29b', 'スカートを見せていただけませんか。', 'スカートを{見|み}せていただけませんか。', NULL, 'Would you please show me that skirt?', 215022),
  ('n5-f0f5f6b29b', 'このスカートは少しきつすぎます。', 'このスカートは{少|すこ}しきつすぎます。', NULL, 'This skirt is a little too tight.', 223642),
  ('n5-20cbecd474', 'あなたのそんなところが好きです。', 'あなたのそんなところが{好|す}きです。', NULL, 'I like that about you.', 161709),
  ('n5-20cbecd474', 'あなたはマルチーズは好きですか。', 'あなたはマルチーズは{好|す}きですか。', NULL, 'Are you fond of Maltese dogs?', 232388),
  ('n5-ce75057c4c', 'すぐわかるところにあるよ。', NULL, NULL, 'It''s in plain sight.', 214924),
  ('n5-ce75057c4c', '「雨がすぐあがるでしょうか」「あがらないと思うよ」', '「{雨|あめ}がすぐあがるでしょうか」「あがらないと{思|おも}うよ」', NULL, '"Will it stop raining soon?" "I''m afraid not."', 236397),
  ('n5-0d38b01113', '読書の時間がますます少なくなっている。', '{読書|どくしょ}の{時間|じかん}がますます{少|すく}なくなっている。', NULL, 'I have less and less time for reading.', 123386),
  ('n5-0d38b01113', 'たとえそんな人はいるとしてもごく少ない。', 'たとえそんな{人|ひと}はいるとしてもごく{少|すく}ない。', NULL, 'There are few, if any, such men.', 203555),
  ('n5-a8722990f1', 'すぐに書かなければなりませんか。', 'すぐに{書|か}かなければなりませんか。', NULL, 'Should I fill it in now?', 214855),
  ('n5-a8722990f1', 'すぐに出かけるほうがよさそうだ。', 'すぐに{出|で}かけるほうがよさそうだ。', NULL, 'I may as well start at once.', 214879),
  ('n5-c373555102', '少しテレビを見てもいいですか。', '{少|すこ}しテレビを{見|み}てもいいですか。', NULL, 'Do you mind if I watch TV for a while?', 146856),
  ('n5-c373555102', 'このスカートは少しきつすぎます。', 'このスカートは{少|すこ}しきつすぎます。', NULL, 'This skirt is a little too tight.', 223642),
  ('n5-67f5908e10', '日増しに涼しくなっていく。', '{日増|ひま}しに{涼|すず}しくなっていく。', NULL, 'It''s getting cooler day by day.', 122850),
  ('n5-67f5908e10', 'だんだん涼しくなっていきます。', 'だんだん{涼|すず}しくなっていきます。', NULL, 'It is getting cooler and cooler.', 203059),
  ('n5-8149d77689', '私は古いストーブに１０ドルの値をつけた。', '{私|わたし}は{古|ふる}いストーブに１０ドルの{値|あたい}をつけた。', NULL, 'I bid ten dollars for the old stove.', 157236),
  ('n5-8149d77689', '彼はストーブで体を暖めた。', '{彼|かれ}はストーブで{体|からだ}を{暖|あたた}めた。', NULL, 'He warmed himself at the stove.', 113365),
  ('n5-938a169f6c', 'スプーンをいただけますか。', NULL, NULL, 'Could we have a spoon?', 214525),
  ('n5-938a169f6c', 'スプーンがありません。', NULL, NULL, 'There is a spoon missing.', 214526),
  ('n5-0a33903ccf', 'ビリーはスポーツがうまいです。', NULL, NULL, 'Billy is good at sports.', 197412),
  ('n5-0a33903ccf', 'どのようなスポーツをなさいますか。', NULL, NULL, 'What sports do you go in for?', 200376),
  ('n5-10fe0704ca', 'ちょっとこのズボンにつめて。', NULL, NULL, 'Please take the pants in a bit.', 202838),
  ('n5-10fe0704ca', 'このズボンはひざが出やすい。', 'このズボンはひざが{出|で}やすい。', NULL, 'These pants tend to go baggy at the knees.', 223621),
  ('n5-feae64eac4', 'すみません、この席あいていますか。', 'すみません、この{席|せき}あいていますか。', NULL, 'Excuse me, is this seat taken?', 214207),
  ('n5-feae64eac4', 'すみませんが電話に出てください。', 'すみませんが{電話|でんわ}に{出|で}てください。', NULL, 'Please answer the phone.', 214132),
  ('n5-d671097071', 'どうしてアメリカに住んでいたの？', 'どうしてアメリカに{住|す}んでいたの？', NULL, 'Why did he live in the United States?', 201568),
  ('n5-d671097071', 'ここにかつて住んでいたのですか。', 'ここにかつて{住|す}んでいたのですか。', NULL, 'Did you use to live here?', 224491),
  ('n5-508131fe89', 'スリッパをはいてください。', NULL, NULL, 'Please put on your slippers.', 214119),
  ('n5-508131fe89', 'スリッパでロビーに降りたらだめだよ。', 'スリッパでロビーに{降|お}りたらだめだよ。', NULL, 'You''re not supposed to wear your slippers down to the lobby.', 214120),
  ('n5-c4cdc162d7', 'ログアウトするんじゃなかったよ。', NULL, NULL, 'I shouldn''t have logged off.', 4858),
  ('n5-c4cdc162d7', '父がもっと長生きしていたらなあ。', '{父|ちち}がもっと{長生|ながい}きしていたらなあ。', NULL, 'I wish my father had lived longer.', 84880),
  ('n5-c9a15e8777', '父と母は木の下に座っていました。', '{父|ちち}と{母|はは}は{木|き}の{下|した}に{座|すわ}っていました。', NULL, 'My father and mother were sitting under a tree.', 84829),
  ('n5-c9a15e8777', 'あのベンチに座ってはいけません。', 'あのベンチに{座|すわ}ってはいけません。', NULL, 'Don''t sit on that bench.', 231252),
  ('n5-898b067287', 'トムはジャックと背が同じくらいだ。', 'トムはジャックと{背|せ}が{同|おな}じくらいだ。', NULL, 'Tom is as tall as Jack.', 200083),
  ('n5-898b067287', '彼はいすの背にもたれている。', '{彼|かれ}はいすの{背|せ}にもたれている。', NULL, 'He is leaning on the back of the chair.', 114666),
  ('n5-af7459ef1e', 'この学校はたくさんの生徒がいます。', 'この{学校|がっこう}はたくさんの{生徒|せいと}がいます。', NULL, 'This school has many students.', 222600),
  ('n5-af7459ef1e', 'あなたは生徒ではありません。', 'あなたは{生徒|せいと}ではありません。', NULL, 'You are not a student.', 231798),
  ('n5-4b0b49a42d', 'このセーターは気に入らない。', 'このセーターは{気|き}に{入|い}らない。', NULL, 'I don''t like this sweater.', 223610),
  ('n5-4b0b49a42d', '母にこのセーターをつくろってもらった。', '{母|はは}にこのセーターをつくろってもらった。', NULL, 'I had my mother mend this sweater.', 83138),
  ('n5-b48d0c99d4', 'せっけんだらけの手で私にさわらないで。', 'せっけんだらけの{手|て}で{私|わたし}にさわらないで。', NULL, 'Don''t touch me with your soapy hands.', 214032),
  ('n5-b48d0c99d4', 'せっけんで手を洗いました。', NULL, NULL, 'I washed my hands with soap.', 10899704),
  ('n5-9d432ac114', '私は新しい背広を買った。', '{私|わたし}は{新|あたら}しい{背広|せびろ}を{買|か}った。', NULL, 'I bought a new suit of clothes.', 155725),
  ('n5-9d432ac114', '彼はくたくたの背広を着ていた。', '{彼|かれ}はくたくたの{背広|せびろ}を{着|き}ていた。', NULL, 'He was wearing a threadbare suit.', 74070),
  ('n5-d12ee2e932', 'オランダは狭い国です。', 'オランダは{狭|せま}い{国|くに}です。', NULL, 'The Netherlands is a small country.', 227474),
  ('n5-d12ee2e932', 'その通りはとても狭いんだ。', 'その{通|とお}りはとても{狭|せま}いんだ。', NULL, 'The street is very narrow.', 207729),
  ('n5-434707d737', '私たちは商売をゼロから始めなければならなかった。', '{私|わたし}たちは{商売|しょうばい}をゼロから{始|はじ}めなければならなかった。', NULL, 'We had to start our business from zero.', 165629),
  ('n5-434707d737', 'ゼロという概念はヒンドゥー文化に由来している。', 'ゼロという{概念|がいねん}はヒンドゥー{文化|ぶんか}に{由来|ゆらい}している。', NULL, 'The concept of zero sprang from the Hindu culture.', 213989);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-1729d60f09', 'このホールには人が二千人入れる。', NULL, NULL, 'Two thousand people fit into this hall.', 223188),
  ('n5-1729d60f09', '千人もの人がそこにいた。', NULL, NULL, 'As many as a thousand people were there.', 141432),
  ('n5-0eaa93c144', '先月は、ほとんど雨が降らなかった。', '{先月|せんげつ}は、ほとんど{雨|あめ}が{降|ふ}らなかった。', NULL, 'We had little rain last month.', 141880),
  ('n5-0eaa93c144', '先月インフルエンザにかかった。', '{先月|せんげつ}インフルエンザにかかった。', NULL, 'I had the flu last month.', 141890),
  ('n5-b8c4cd80db', 'あの人は先週ここにいた人です。', 'あの{人|ひと}は{先週|せんしゅう}ここにいた{人|ひと}です。', NULL, 'He''s the man that was here last week.', 230710),
  ('n5-b8c4cd80db', 'あなたは先週ここにいましたか。', 'あなたは{先週|せんしゅう}ここにいましたか。', NULL, 'Were you here last week?', 231791),
  ('n5-814bdc2cec', '校長が先生の後ろから入ってきた。', '{校長|こうちょう}が{先生|せんせい}の{後|うし}ろから{入|はい}ってきた。', NULL, 'The principal came in after the teacher.', 173570),
  ('n5-814bdc2cec', 'あの先生の話にはうんざりするよ。', 'あの{先生|せんせい}の{話|はなし}にはうんざりするよ。', NULL, 'That Prof.''s talk is driving me up the wall.', 230655),
  ('n5-4d0ca7b320', '洗濯はいつやってもいいですか。', '{洗濯|せんたく}はいつやってもいいですか。', NULL, 'Can I use the laundry any time?', 141216),
  ('n5-4d0ca7b320', '洗濯のサービスはありますか。', '{洗濯|せんたく}のサービスはありますか。', NULL, 'Do you have a laundry service?', 141217),
  ('n5-acba6e07ba', 'トッピングは全部のせて下さい。', 'トッピングは{全部|ぜんぶ}のせて{下|くだ}さい。', NULL, 'I want everything on it.', 200680),
  ('n5-acba6e07ba', 'それは全部で１００ドルでした。', 'それは{全部|ぜんぶ}で１００ドルでした。', NULL, 'It has cost me $100 altogether.', 205017),
  ('n5-501df34d31', '父はガレージを掃除している。', '{父|ちち}はガレージを{掃除|そうじ}している。', NULL, 'My father is sweeping the garage.', 84738),
  ('n5-501df34d31', 'あなたの部屋を掃除しましたか。', 'あなたの{部屋|へや}を{掃除|そうじ}しましたか。', NULL, 'Did you clean your room?', 233037),
  ('n5-e75777d218', 'そうしてくださればとてもうれしい。', NULL, NULL, 'I can''t be sorry.', 213883),
  ('n5-e75777d218', 'そうしてくれて君は親切ですね。', 'そうしてくれて{君|きみ}は{親切|しんせつ}ですね。', NULL, 'It is kind of you to do so.', 213882),
  ('n5-5ef867ff81', 'バスでそこまで２時間かかります。', 'バスでそこまで２{時間|じかん}かかります。', NULL, 'It takes two hours to go there by bus.', 198206),
  ('n5-5ef867ff81', '気がつくと、そこにありました。', '{気|き}がつくと、そこにありました。', NULL, 'It was there when I noticed it.', 183289),
  ('n5-105df79571', 'これとそちらとの違いは何だい。', 'これとそちらとの{違|ちが}いは{何|なに}だい。', NULL, 'What is the difference between this and that?', 218744),
  ('n5-105df79571', 'そっちの生活はどうだい？', 'そっちの{生活|せいかつ}はどうだい？', NULL, 'How are things for you up there?', 213468),
  ('n5-80981fa136', 'そっちの天気は？', 'そっちの{天気|てんき}は？', NULL, 'How''s the weather there?', 213467),
  ('n5-80981fa136', 'そっちへ行く前に電話するね。', NULL, NULL, 'I''ll give you a call before I visit you.', 10499829),
  ('n5-68ad5f4363', '外に出してやってくれませんか。', '{外|そと}に{出|だ}してやってくれませんか。', NULL, 'Could you let him out?', 184892),
  ('n5-68ad5f4363', 'テントの中ではなくて外で食べよう。', 'テントの{中|なか}ではなくて{外|そと}で{食|た}べよう。', NULL, 'Let''s eat outside instead of in our tents.', 201917),
  ('n5-38c854e97f', 'ガレージは家のそばにあります。', 'ガレージは{家|いえ}のそばにあります。', NULL, 'The garage is at the side of the house.', 226153),
  ('n5-38c854e97f', 'われわれはドアのそばに立ってまった。', 'われわれはドアのそばに{立|た}ってまった。', NULL, 'We stood at the door and waited.', 191672),
  ('n5-6ff51bace3', '空はすっかりもやがかかっていた。', '{空|そら}はすっかりもやがかかっていた。', NULL, 'The sky misted over.', 179433),
  ('n5-6ff51bace3', 'ワシが空を飛んでいる。', 'ワシが{空|そら}を{飛|と}んでいる。', NULL, 'An eagle is flying in the sky.', 191980),
  ('n5-79d922e359', 'わたしはそれを見てぎょっとした。', 'わたしはそれを{見|み}てぎょっとした。', NULL, 'I was appalled at the sight.', 191835),
  ('n5-79d922e359', 'それをリストから外してください。', 'それをリストから{外|はず}してください。', NULL, 'Leave it off the list.', 204628),
  ('n5-799b7cabe0', 'それからすっきりきれいにしてくれ。', NULL, NULL, 'Then clean it really well.', 205929),
  ('n5-799b7cabe0', 'それから先の話を聞きたい。', NULL, NULL, 'I''d like to know the rest of the story.', 205916),
  ('n5-46c1721526', 'それでは、あなたは来ないということですか。', 'それでは、あなたは{来|こ}ないということですか。', NULL, 'Does that mean you won''t come?', 205771),
  ('n5-46c1721526', 'それでは学校へ急ぎましょう。', 'それでは{学校|がっこう}へ{急|いそ}ぎましょう。', NULL, 'Now let''s hurry to school.', 205760),
  ('n5-5b303264b9', '大学で何をするつもりですか。', '{大学|だいがく}で{何|なに}をするつもりですか。', NULL, 'What are you going to do in college?', 137646),
  ('n5-5b303264b9', '大学ではテニスクラブに入っています。', '{大学|だいがく}ではテニスクラブに{入|はい}っています。', NULL, 'I belong to a tennis club in my university.', 137648),
  ('n5-992fc07339', '日本大使館はどこにありますか。', NULL, NULL, 'Where is the Japanese Embassy?', 122209),
  ('n5-992fc07339', '彼はアメリカ大使館に出入りしている。', NULL, NULL, 'He has access to the American Embassy.', 114807),
  ('n5-2f62b9db5e', 'いや、大丈夫だ。', 'いや、{大丈夫|だいじょうぶ}だ。', NULL, 'No, no, that''s okay.', 228498),
  ('n5-2f62b9db5e', '彼女は今のところ大丈夫です。', '{彼女|かのじょ}は{今|いま}のところ{大丈夫|だいじょうぶ}です。', NULL, 'She is all right at the moment.', 90036),
  ('n5-9ee7cd3382', 'ロジャーはパーティーが大好きだ。', 'ロジャーはパーティーが{大好|だいす}きだ。', NULL, 'Roger is a party animal.', 192202),
  ('n5-9ee7cd3382', '人間はしゃべることが大好きだ。', '{人間|にんげん}はしゃべることが{大好|だいす}きだ。', NULL, 'People love to talk, talk, talk.', 144314),
  ('n5-b3a8593e53', '本を読むことは大切です。', '{本|ほん}を{読|よ}むことは{大切|たいせつ}です。', NULL, 'To read books is important.', 81616),
  ('n5-b3a8593e53', '水は人間にとって大切だ。', '{水|みず}は{人間|にんげん}にとって{大切|たいせつ}だ。', NULL, 'Water is important for humans.', 143754),
  ('n5-1c0b0f77b6', 'ルーシーは今台所にいるでしょう。', 'ルーシーは{今|いま}{台所|だいどころ}にいるでしょう。', NULL, 'Lucy should be in the kitchen now.', 192405),
  ('n5-1c0b0f77b6', 'そのドアから台所へ出入りできる。', 'そのドアから{台所|だいどころ}へ{出入|でい}りできる。', NULL, 'The door gives access to the kitchen.', 212931),
  ('n5-e04372c490', 'それはたいへんなショックでした。', NULL, NULL, 'It was such a shock.', 237333),
  ('n5-e04372c490', 'この本はたいへんおもしろい。', 'この{本|ほん}はたいへんおもしろい。', NULL, 'This book is very interesting.', 219705),
  ('n5-c74892f565', '二つのうちでどちらが高いですか。', '{二|ふた}つのうちでどちらが{高|たか}いですか。', NULL, 'Which is the more expensive of the two?', 123179),
  ('n5-c74892f565', 'これはなんと高い木なのでしょう。', 'これはなんと{高|たか}い{木|き}なのでしょう。', NULL, 'What a tall tree this is!', 218541);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-a7c72d9bb1', 'なすべきことがまだたくさんある。', NULL, NULL, 'There still remains much to be done.', 199298),
  ('n5-a7c72d9bb1', 'そんなにたくさんくださいました。', NULL, NULL, 'You have given me so many.', 204301),
  ('n5-2d5a93eb11', 'そのタクシーはいきなり左に曲がった。', 'そのタクシーはいきなり{左|ひだり}に{曲|ま}がった。', NULL, 'The taxi abruptly turned left.', 212991),
  ('n5-2d5a93eb11', 'ここでタクシーをつかまえられますか。', NULL, NULL, 'Can I catch a taxi here?', 224661),
  ('n5-6298cfc5d6', 'ここではおいしい食べ物が出されます。', 'ここではおいしい{食|た}べ{物|もの}が{出|だ}されます。', NULL, 'They serve excellent food here.', 224634),
  ('n5-6298cfc5d6', 'この件では名前を出したくない。', 'この{件|けん}では{名前|なまえ}を{出|だ}したくない。', NULL, 'I want to remain anonymous in this.', 222164),
  ('n5-932afda20b', '立っているのは、みんな男だった。', '{立|た}っているのは、みんな{男|おとこ}だった。', NULL, 'Those standing were all men.', 78277),
  ('n5-932afda20b', 'なぜぼくをここに立たせておくの？', 'なぜぼくをここに{立|た}たせておくの？', NULL, 'Why leave me standing here?', 199215),
  ('n5-e7ca1b2fd5', 'テーブルを縦一列に並べなさい。', 'テーブルを{縦|たて}{一列|いちれつ}に{並|なら}べなさい。', NULL, 'Put the tables end to end.', 202374),
  ('n5-e7ca1b2fd5', '蟹を縦に歩かせることはできない。', '{蟹|かに}を{縦|たて}に{歩|ある}かせることはできない。', NULL, 'You cannot make a crab walk straight.', 184932),
  ('n5-372b08211e', '建物がとっても小さく見えるよ。', '{建物|たてもの}がとっても{小|ちい}さく{見|み}えるよ。', NULL, 'The buildings look so tiny.', 175391),
  ('n5-372b08211e', 'リンダは建物の中に入って来ました。', 'リンダは{建物|たてもの}の{中|なか}に{入|はい}って{来|き}ました。', NULL, 'Linda came into the building.', 192428),
  ('n5-9b2d455dfe', 'あなたと一緒にいて楽しかった。', 'あなたと{一緒|いっしょ}にいて{楽|たの}しかった。', NULL, 'I really enjoyed your company.', 233856),
  ('n5-9b2d455dfe', 'ひとみはとても楽しそうにみえた。', 'ひとみはとても{楽|たの}しそうにみえた。', NULL, 'Hitomi looked very happy.', 197488),
  ('n5-7e9d38afeb', 'あなたに頼んでもよろしいですか。', 'あなたに{頼|たの}んでもよろしいですか。', NULL, 'May I request a favour of you?', 233649),
  ('n5-7e9d38afeb', 'このテーブルを頼んだのではない。', 'このテーブルを{頼|たの}んだのではない。', NULL, 'I didn''t ask for a table here.', 223523),
  ('n5-80beed00bf', '男はライターでたばこに火をつけた。', '{男|おとこ}はライターでたばこに{火|ひ}をつけた。', NULL, 'The man lit a cigarette with a lighter.', 127211),
  ('n5-80beed00bf', 'タバコはなかなかやめられない。', NULL, NULL, 'It''s hard to shake the smoking habit.', 203430),
  ('n5-d9eba03b7b', '君にはたぶんみんなわかっていることでしょう。', '{君|きみ}にはたぶんみんなわかっていることでしょう。', NULL, 'I expect you know all about it.', 178680),
  ('n5-d9eba03b7b', 'たぶんガールフレンドがたくさんいるのよ。', NULL, NULL, 'Maybe he has lots of girlfriends.', 203356),
  ('n5-5c89b3094a', '食べ物はすべてなくなってしまった。', '{食|た}べ{物|もの}はすべてなくなってしまった。', NULL, 'All the food was gone.', 145899),
  ('n5-5c89b3094a', '食べ物はよくかむほうがよい。', '{食|た}べ{物|もの}はよくかむほうがよい。', NULL, 'You might as well chew your food well.', 145896),
  ('n5-86f67e2dc3', 'ちょうど食べたかったものでした。', 'ちょうど{食|た}べたかったものでした。', NULL, 'That hit the spot.', 202896),
  ('n5-86f67e2dc3', '食べながら読んではいけません。', '{食|た}べながら{読|よ}んではいけません。', NULL, 'You must not read while eating.', 145934),
  ('n5-4d66739694', '卵を一ダースづつつめなさい。', NULL, NULL, 'Pack eggs in dozens.', 78480),
  ('n5-4d66739694', '卵を食べるとじんましんが出ます。', '{卵|たまご}を{食|た}べるとじんましんが{出|で}ます。', NULL, 'He gets hives when he eats eggs.', 78471),
  ('n5-3d2ca62c5f', '誰がこれをしたのかはわからない。', '{誰|だれ}がこれをしたのかはわからない。', NULL, 'There is no telling who did this.', 137017),
  ('n5-3d2ca62c5f', '誰がこのビルのかんりしゃですか。', '{誰|だれ}がこのビルのかんりしゃですか。', NULL, 'Who is in charge of this building?', 137043),
  ('n5-2e610178ae', '誕生日とは人が生まれた日のことだ。', '{誕生日|たんじょうび}とは{人|ひと}が{生|う}まれた{日|ひ}のことだ。', NULL, 'The birthday is the day on which a person was born.', 127349),
  ('n5-2e610178ae', 'これ誕生日のプレゼントなんだ。', 'これ{誕生日|たんじょうび}のプレゼントなんだ。', NULL, 'Here is a present for your birthday.', 217561),
  ('n5-55dbb815ba', '日がだんだん長くなってきています。', '{日|ひ}がだんだん{長|なが}くなってきています。', NULL, 'The days are getting longer and longer.', 122958),
  ('n5-55dbb815ba', 'それはだんだん大きくなった。', 'それはだんだん{大|おお}きくなった。', NULL, 'It grew larger and larger.', 205465),
  ('n5-d4779ac36c', 'もっと小さいサイズがありますか。', 'もっと{小|ちい}さいサイズがありますか。', NULL, 'Do you have a smaller size?', 193270),
  ('n5-d4779ac36c', 'これより小さいのはないんですか？', 'これより{小|ちい}さいのはないんですか？', NULL, 'Don''t you have anything smaller than this?', 218012),
  ('n5-38a8411ec3', '小さなことでくよくよするな。', '{小|ちい}さなことでくよくよするな。', NULL, 'Don''t trouble about small things.', 147022),
  ('n5-38a8411ec3', 'アンは小さな女の子です。', 'アンは{小|ちい}さな{女|おんな}の{子|こ}です。', NULL, 'Ann is a little girl.', 229481),
  ('n5-a21ba677f2', 'クリスマスが近くなってきた。', 'クリスマスが{近|ちか}くなってきた。', NULL, 'Christmas is fast approaching.', 225480),
  ('n5-a21ba677f2', 'トイレが近いのです。', 'トイレが{近|ちか}いのです。', NULL, 'Is there a toilet near here?', 201736),
  ('n5-35e9881c22', 'ライオンとヒョウの違いは何ですか。', 'ライオンとヒョウの{違|ちが}いは{何|なに}ですか。', NULL, 'What''s the difference between lions and leopards?', 192689),
  ('n5-35e9881c22', 'そうかもしれないけど、たぶん違う。', 'そうかもしれないけど、たぶん{違|ちが}う。', NULL, 'That could be true, but I don''t really think so.', 213899),
  ('n5-6d7293f7cf', '７時近くだ。学校へ行かなくては。', NULL, NULL, 'It is close to seven o''clock. We have to go to school.', 234967),
  ('n5-6d7293f7cf', 'スミスさんはすぐ近くにいます。', 'スミスさんはすぐ{近|ちか}くにいます。', NULL, 'Mr Smith is within shouting distance.', 214296),
  ('n5-3134199c25', '地下鉄で行きたいのです。', NULL, NULL, 'I want to get there by subway.', 127016),
  ('n5-3134199c25', '地下鉄から出るのに私はもがいた。', '{地下鉄|ちかてつ}から{出|で}るのに{私|わたし}はもがいた。', NULL, 'I struggled to get out of the subway.', 127017),
  ('n5-ffa3dda331', 'この大きなアメリカの地図を見て。', 'この{大|おお}きなアメリカの{地図|ちず}を{見|み}て。', NULL, 'Look at this large map of America.', 220672),
  ('n5-ffa3dda331', 'ちょっとこの地図を見なさい。', 'ちょっとこの{地図|ちず}を{見|み}なさい。', NULL, 'Take a look at this map.', 202836),
  ('n5-f9b377e253', 'その犬は茶色で小さくて、やせています。', 'その{犬|いぬ}は{茶色|ちゃいろ}で{小|ちい}さくて、やせています。', NULL, 'The dog is brown, small and thin.', 210959),
  ('n5-f9b377e253', 'この茶色のネクタイをいただきたいのですが。', 'この{茶色|ちゃいろ}のネクタイをいただきたいのですが。', NULL, 'I would take this brown tie.', 220566),
  ('n5-3d12036023', 'この茶わんはなんとすばらしいのでしょう。', NULL, NULL, 'How nice this cup is!', 220567),
  ('n5-3d12036023', 'テーブルの上に茶碗があります。', 'テーブルの{上|うえ}に{茶碗|ちゃわん}があります。', NULL, 'There is a cup on the table.', 202391);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-9b08365493', 'ちょうど食べたかったものでした。', 'ちょうど{食|た}べたかったものでした。', NULL, 'That hit the spot.', 202896),
  ('n5-9b08365493', 'ちょうどチェックインするところです。', NULL, NULL, 'I''m just about to check in.', 202931),
  ('n5-602fdffbf2', 'ちょっと、そこのきみ！', NULL, NULL, 'Hey, you there!', 74695),
  ('n5-602fdffbf2', 'もうほんのちょっと気をつけねば。', 'もうほんのちょっと{気|き}をつけねば。', NULL, 'You should be a thought more careful.', 194363),
  ('n5-c88e0ba104', 'フラッシュを使ってもいいですか。', 'フラッシュを{使|つか}ってもいいですか。', NULL, 'Is it all right to use a flash here?', 197026),
  ('n5-c88e0ba104', 'どうぞヘッドホンをお使い下さい。', 'どうぞヘッドホンをお{使|つか}い{下|くだ}さい。', NULL, 'Please use your headsets.', 201311),
  ('n5-156f17113e', 'とても疲れているように見えます。', 'とても{疲|つか}れているように{見|み}えます。', NULL, 'You look very tired.', 177623),
  ('n5-156f17113e', 'あなたは疲れているように見える。', 'あなたは{疲|つか}れているように{見|み}える。', NULL, 'You look tired.', 231609),
  ('n5-d00ef0a9d5', '次はいつ来ればいいのでしょうか。', '{次|つぎ}はいつ{来|く}ればいいのでしょうか。', NULL, 'When should I come again?', 150216),
  ('n5-d00ef0a9d5', '次は前もって電話して下さいね。', '{次|つぎ}は{前|まえ}もって{電話|でんわ}して{下|くだ}さいね。', NULL, 'Next time phone ahead.', 150204),
  ('n5-9d4a68ce12', 'シカゴに着いたらすぐ電話します。', 'シカゴに{着|つ}いたらすぐ{電話|でんわ}します。', NULL, 'I''ll call you as soon as I get to Chicago.', 216366),
  ('n5-9d4a68ce12', 'ロンドンにはいつ着きましたか。', 'ロンドンにはいつ{着|つ}きましたか。', NULL, 'When did you get to London?', 192138),
  ('n5-672321bac9', '机の上にペンが一本もありません。', '{机|つくえ}の{上|うえ}にペンが{一本|いっぽん}もありません。', NULL, 'There are no pens on the desk.', 183446),
  ('n5-672321bac9', '机の上にはほこりがたまっていた。', '{机|つくえ}の{上|うえ}にはほこりがたまっていた。', NULL, 'Dust had accumulated on the desk.', 183454),
  ('n5-6e922a750e', 'たまごを割らずにオムレツは作れない。', 'たまごを{割|わ}らずにオムレツは{作|つく}れない。', NULL, 'You can''t make an omelet without breaking eggs.', 203324),
  ('n5-6e922a750e', 'このテーブルは木で作られている。', 'このテーブルは{木|き}で{作|つく}られている。', NULL, 'This table is made of wood.', 223530),
  ('n5-edc22b8d98', 'テレビをつけて。', NULL, NULL, 'Please turn on the television.', 201970),
  ('n5-edc22b8d98', 'ラジオをつけてもかまいませんか。', NULL, NULL, 'Do you mind if I turn on the radio?', 192597),
  ('n5-ba6c46f68c', '父は銀行に勤めています。', '{父|ちち}は{銀行|ぎんこう}に{勤|つと}めています。', NULL, 'My father works for a bank.', 84602),
  ('n5-ba6c46f68c', '彼はもうここには勤めていない。', '{彼|かれ}はもうここには{勤|つと}めていない。', NULL, 'He no longer works here.', 110635),
  ('n5-3a94b5e981', 'このビデオはつまらないよ。', NULL, NULL, 'This video is boring.', 223276),
  ('n5-3a94b5e981', 'あの新しい映画は、つまらんかった。', 'あの{新|あたら}しい{映画|えいが}は、つまらんかった。', NULL, 'That new movie was a bummer.', 230825),
  ('n5-a23d308800', 'もう手が冷たくって。', 'もう{手|て}が{冷|つめ}たくって。', NULL, 'My hand''s getting too cold.', 194174),
  ('n5-a23d308800', '夏は冷たいポテトサラダがいいな。', '{夏|なつ}は{冷|つめ}たいポテトサラダがいいな。', NULL, 'I like cold potato salad in the summertime.', 187197),
  ('n5-d99745fbb6', 'トラとライオンとどちらが強いか。', 'トラとライオンとどちらが{強|つよ}いか。', NULL, 'Which is stronger, a tiger or a lion?', 199736),
  ('n5-d99745fbb6', 'あの小学校はサッカーが強い。', 'あの{小学校|しょうがっこう}はサッカーが{強|つよ}い。', NULL, 'That primary school has a strong soccer team.', 230859),
  ('n5-5b9670420a', 'ここに手のないナベがある。', 'ここに{手|て}のないナベがある。', NULL, 'Here is a pan without handles.', 224417),
  ('n5-5b9670420a', 'いい手を思いついた。', 'いい{手|て}を{思|おも}いついた。', NULL, 'I hit upon a good idea.', 229349),
  ('n5-0cf2b43e9c', '君はそのコンサートをテープにとったか。', '{君|きみ}はそのコンサートをテープにとったか。', NULL, 'Did you tape that concert?', 177769),
  ('n5-0cf2b43e9c', 'そのテープをかけてくれませんか。', NULL, NULL, 'Will you play the tape?', 212956),
  ('n5-ff161262dd', 'このテーブルを頼んだのではない。', 'このテーブルを{頼|たの}んだのではない。', NULL, 'I didn''t ask for a table here.', 223523),
  ('n5-ff161262dd', 'テーブルの上にリンゴがあります。', 'テーブルの{上|うえ}にリンゴがあります。', NULL, 'There is an apple on the table.', 202398),
  ('n5-dc0ae29019', 'このテープレコーダーは新しくない。', 'このテープレコーダーは{新|あたら}しくない。', NULL, 'This tape recorder is not new.', 223518),
  ('n5-dc0ae29019', 'このテープレコーダーは４万円しました。', NULL, NULL, 'I paid 40,000 yen for this tape recorder.', 223521),
  ('n5-375cfbefdd', '出かけるよりもじっとしていたい。', '{出|で}かけるよりもじっとしていたい。', NULL, 'I would sooner stay than go.', 147811),
  ('n5-375cfbefdd', '雨だったので出かけられなかった。', '{雨|あめ}だったので{出|で}かけられなかった。', NULL, 'It being rainy, I could not go out.', 189654),
  ('n5-218ea67735', '書かねばならない手紙があります。', '{書|か}かねばならない{手紙|てがみ}があります。', NULL, 'I have to write a letter.', 147430),
  ('n5-218ea67735', 'フレッドは母に長い手紙を書いた。', 'フレッドは{母|はは}に{長|なが}い{手紙|てがみ}を{書|か}いた。', NULL, 'Fred wrote his mother a long letter.', 196892),
  ('n5-69d0d632fa', 'あの二人はどうもできているらしい。', 'あの{二人|ふたり}はどうもできているらしい。', NULL, 'They seem to be in love with each other.', 230516),
  ('n5-69d0d632fa', 'トイレお借りできますか。', 'トイレお{借|か}りできますか。', NULL, 'May I use your toilet?', 201738),
  ('n5-151fd72164', 'B2出口から地上に出てください。', 'B2{出口|でぐち}から{地上|ちじょう}に{出|で}てください。', NULL, 'Go up to ground level at exit B2.', 234867),
  ('n5-151fd72164', '出口はどちらですか。', '{出口|でぐち}はどちらですか。', NULL, 'Where is the way out?', 147749),
  ('n5-90e9410bff', 'そのテストはむずかしかった。', NULL, NULL, 'I found the test difficult.', 212948),
  ('n5-90e9410bff', 'テストはなんとかなった。', NULL, NULL, 'I just got by on the test.', 202236),
  ('n5-d33540fe8e', 'では今晩またね、さようなら。', 'では{今晩|こんばん}またね、さようなら。', NULL, 'See you tonight, then. Cheers!', 202137),
  ('n5-d33540fe8e', 'アメリカでは何語が話されていますか。', 'アメリカでは{何語|なにご}が{話|はな}されていますか。', NULL, 'What language is spoken in America?', 187507),
  ('n5-0144505953', 'あのデパートで新しいコートを買いたい。', 'あのデパートで{新|あたら}しいコートを{買|か}いたい。', NULL, 'I would like to buy a new coat at that department store.', 155750),
  ('n5-0144505953', 'そのデパートの前に書店がある。', 'そのデパートの{前|#1392580}に{書店|しょてん}がある。', NULL, 'There is a bookstore in front of the department store.', 212947),
  ('n5-3f71089c32', 'どんな人でもいないよりはましだ。', 'どんな{人|ひと}でもいないよりはましだ。', NULL, 'Anybody would be better than nobody.', 199395),
  ('n5-3f71089c32', 'どんなベッドでもないよりはよい。', NULL, NULL, 'Any bed is better than no bed.', 199480);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-5ef4f7dde9', '電話には出なかったからメールしておきました。', '{電話|でんわ}には{出|で}なかったからメールしておきました。', NULL, 'He didn''t answer the phone, so I left him an email.', 449040),
  ('n5-5ef4f7dde9', '電気シェーバーから火が出ました。', '{電気|でんき}シェーバーから{火|ひ}が{出|で}ました。', NULL, 'My electric razor is on fire.', 124855),
  ('n5-c7e14d8454', 'あなたはどこでテレビを見ますか。', 'あなたはどこでテレビを{見|み}ますか。', NULL, 'Where do you watch television?', 232489),
  ('n5-c7e14d8454', 'テレビはここでは見られていない。', 'テレビはここでは{見|み}られていない。', NULL, 'TV is not watched here.', 201993),
  ('n5-679e34031e', '今日が天気ならいいのに。', NULL, NULL, 'I wish it were fine today.', 171537),
  ('n5-679e34031e', '一日いい天気になりそうですよ。', '{一日|いちにち}いい{天気|てんき}になりそうですよ。', NULL, 'I think it''s going to be a nice day.', 190284),
  ('n5-a7c36fdb70', '電気シェーバーから火が出ました。', '{電気|でんき}シェーバーから{火|ひ}が{出|で}ました。', NULL, 'My electric razor is on fire.', 124855),
  ('n5-a7c36fdb70', '電気をつけていただけませんか。', '{電気|でんき}をつけていただけませんか。', NULL, 'Would you be so kind as to turn the light on?', 124844),
  ('n5-62b5c13164', '電車の中ですりにやられちゃったんだ。', '{電車|でんしゃ}の{中|なか}ですりにやられちゃったんだ。', NULL, 'I had my pocket picked on the train.', 124800),
  ('n5-62b5c13164', '電車でポケットの中にあるものをすられた。', '{電車|でんしゃ}でポケットの{中|なか}にあるものをすられた。', NULL, 'I had my pocket picked in the train.', 124816),
  ('n5-3c039918ba', 'ブラウンさんから電話のようです。', 'ブラウンさんから{電話|でんわ}のようです。', NULL, 'It''s a phone call from a Mr Brown.', 197096),
  ('n5-3c039918ba', '電話では、ありがとうございました。', '{電話|でんわ}では、ありがとうございました。', NULL, 'Thank you very much for your time on the phone.', 124718),
  ('n5-6f4691297f', '誰かが戸をやかましくノックしている。', '{誰|だれ}かが{戸|と}をやかましくノックしている。', NULL, 'Someone is knocking loudly at the door.', 137092),
  ('n5-6f4691297f', '見ると戸にかぎがかけられていた。', '{見|み}ると{戸|と}にかぎがかけられていた。', NULL, 'He found the door locked.', 175163),
  ('n5-677d3c5fac', '入る前にドアをノックして下さい。', '{入|はい}る{前|#1392580}にドアをノックして{下|くだ}さい。', NULL, 'Please knock on the door before you enter.', 122091),
  ('n5-677d3c5fac', 'ドアをあけてくださいませんか。', NULL, NULL, 'Will you open the door?', 201824),
  ('n5-e1e7c2d290', 'トイレの水が止まりません。', 'トイレの{水|みず}が{止|と}まりません。', NULL, 'The toilet won''t stop running.', 201731),
  ('n5-e1e7c2d290', 'トイレはどこにあるのでしょうか。', NULL, NULL, 'Where''s the restroom?', 201725),
  ('n5-a891b73f8b', 'どうしてあなたは一人になったの？', 'どうしてあなたは{一人|ひとり}になったの？', NULL, 'How did you end up on your own?', 201572),
  ('n5-a891b73f8b', 'どうしてスペイン語を学ぶのですか。', 'どうしてスペイン{語|ご}を{学|まな}ぶのですか。', NULL, 'What do you learn Spanish for?', 201551),
  ('n5-a71cbc3ce4', '写真をどうぞ見せて下さい。', '{写真|しゃしん}をどうぞ{見|み}せて{下|くだ}さい。', NULL, 'Please show me your picture.', 149251),
  ('n5-a71cbc3ce4', 'どうぞごゆっくりなさって下さい。', 'どうぞごゆっくりなさって{下|くだ}さい。', NULL, 'Please make yourself at home.', 201333),
  ('n5-93b9cec3d4', 'どうぞよろしく。', NULL, NULL, 'Nice to meet you.', 201303),
  ('n5-93b9cec3d4', 'ご家族の皆さんにどうぞよろしく。', 'ご{家族|かぞく}の{皆|みな}さんにどうぞよろしく。', NULL, 'Give my best regards to all your family.', 217197),
  ('n5-03d03cf25d', '私はその動物の名前を知っている。', '{私|わたし}はその{動物|どうぶつ}の{名前|なまえ}を{知|し}っている。', NULL, 'I know the name of this animal.', 159921),
  ('n5-03d03cf25d', '人は何よりもまず話す動物である。', '{人|ひと}は{何|なに}よりもまず{話|はな}す{動物|どうぶつ}である。', NULL, 'Man is above all things the talking animal.', 144525),
  ('n5-d2cb14f88a', 'あの二人はどうもできているらしい。', 'あの{二人|ふたり}はどうもできているらしい。', NULL, 'They seem to be in love with each other.', 230516),
  ('n5-d2cb14f88a', '先生、どうもありがとうございました。', '{先生|せんせい}、どうもありがとうございました。', NULL, 'Thank you very much, doctor.', 141797),
  ('n5-f840779b9e', 'それはホテルから遠くありません。', 'それはホテルから{遠|とお}くありません。', NULL, 'It is not far away from the hotel.', 205405),
  ('n5-f840779b9e', 'ここからシドニーは遠いですね。', 'ここからシドニーは{遠|とお}いですね。', NULL, 'Sydney is far from here.', 224795),
  ('n5-e8579084ba', 'ジャックは８月１０日に生まれた。', NULL, NULL, 'Jack was born on August the tenth.', 215846),
  ('n5-e8579084ba', 'つまり、５月１０日のことだ。', NULL, NULL, 'That is to say, on May 10th.', 202538),
  ('n5-978a2cefa5', 'ジェーンはときどき学校まで走っていく。', 'ジェーンはときどき{学校|がっこう}まで{走|はし}っていく。', NULL, 'Jane sometimes runs to school.', 216490),
  ('n5-978a2cefa5', 'すごい！じゃこれから時々あえるわね。', 'すごい！じゃこれから{時々|ときどき}あえるわね。', NULL, 'Great! Let''s get together sometime.', 214732),
  ('n5-e3ad76810f', 'あなたの時計では何時ですか。', 'あなたの{時計|とけい}では{何時|なんじ}ですか。', NULL, 'What time is it by your watch?', 233246),
  ('n5-e3ad76810f', 'この時計はせいぜい１０ドルだ。', 'この{時計|とけい}はせいぜい１０ドルだ。', NULL, 'This watch costs ten dollars at the most.', 221611),
  ('n5-ad884a3b70', 'あなたはどこでテレビを見ますか。', 'あなたはどこでテレビを{見|み}ますか。', NULL, 'Where do you watch television?', 232489),
  ('n5-ad884a3b70', '休み中にどこへいくつもりですか。', '{休|やす}み{中|ちゅう}にどこへいくつもりですか。', NULL, 'Where are you going to go on your vacation?', 182700),
  ('n5-ca332ac7b4', 'どんな所でアルバイトできるの。', 'どんな{所|ところ}でアルバイトできるの。', NULL, 'Where can you get a part-time job?', 199406),
  ('n5-ca332ac7b4', 'どういう所を見学したいですか。', 'どういう{所|ところ}を{見学|けんがく}したいですか。', NULL, 'What kind of places would you like to see?', 201701),
  ('n5-358fc382cb', 'お年をお聞きしてよろしいでしょうか。', NULL, NULL, 'Might I ask your age?', 226785),
  ('n5-358fc382cb', '今年もよい年でありますように。', '{今年|ことし}もよい{年|とし}でありますように。', NULL, 'May the new year bring you happiness!', 171289),
  ('n5-de5a452667', '図書館の中で話をしてはいけない。', '{図書館|としょかん}の{中|なか}で{話|はなし}をしてはいけない。', NULL, 'We must not speak in the library.', 143872),
  ('n5-de5a452667', '図書館にはたくさんの本があります。', '{図書館|としょかん}にはたくさんの{本|ほん}があります。', NULL, 'There are a lot of books in the library.', 143878),
  ('n5-5480c153dc', '二つのうちでどちらが高いですか。', '{二|ふた}つのうちでどちらが{高|たか}いですか。', NULL, 'Which is the more expensive of the two?', 123179),
  ('n5-5480c153dc', 'どちらの本があなたのものですか。', 'どちらの{本|ほん}があなたのものですか。', NULL, 'Which book is yours?', 200726),
  ('n5-e8a4843059', 'この本とあの本とどっちがやさしい？', 'この{本|ほん}とあの{本|ほん}とどっちがやさしい？', NULL, 'Which is easier to read, this book or that one?', 219777),
  ('n5-e8a4843059', 'トムとメアリー、どっちもどっちよ。', NULL, NULL, 'Both Tom and Mary are to blame.', 10472406),
  ('n5-a3679ee665', 'この雨の中を外出することはとてもできないことです。', 'この{雨|あめ}の{中|なか}を{外出|がいしゅつ}することはとてもできないことです。', NULL, 'Going out in this rain is out of the question.', 222938),
  ('n5-a3679ee665', 'それらはとても大きなりんごです。', 'それらはとても{大|おお}きなりんごです。', NULL, 'They are very big apples.', 204722);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-10fb2e55c0', '「どなたですか」「お母さんよ」', '「どなたですか」「お{母|かあ}さんよ」', NULL, '"Who is it?" "It''s your mother."', 4914),
  ('n5-10fb2e55c0', 'あなたが話していた人はどなたですか。', 'あなたが{話|はな}していた{人|ひと}はどなたですか。', NULL, 'Who is the man that you were talking with?', 233903),
  ('n5-c597c353cb', 'あのビルのとなりです。', NULL, NULL, 'It''s next to that building.', 231268),
  ('n5-c597c353cb', 'いいですよ。プラザデパートの隣です。', 'いいですよ。プラザデパートの{隣|となり}です。', NULL, 'Sure. It''s next to the Plaza Department Store.', 229394),
  ('n5-cd4b8c6381', 'これはほかのどの木よりも高い。', 'これはほかのどの{木|き}よりも{高|たか}い。', NULL, 'This is taller than any other tree.', 218528),
  ('n5-cd4b8c6381', 'あなたはどのＣＤを聞きたいですか。', 'あなたはどのＣＤを{聞|き}きたいですか。', NULL, 'Which CD do you want to listen to?', 232473),
  ('n5-397b682fa7', 'ヒューズが飛んだ。', 'ヒューズが{飛|と}んだ。', NULL, 'A fuse has blown.', 197450),
  ('n5-397b682fa7', '彼の話はいろいろなところへ飛ぶ。', '{彼|かれ}の{話|はなし}はいろいろなところへ{飛|と}ぶ。', NULL, 'He frequently jumps from one topic to another while he is talking.', 115795),
  ('n5-9d1aa046d6', 'ちょうどその時バスが止まった。', 'ちょうどその{時|とき}バスが{止|と}まった。', NULL, 'Just then, the bus stopped.', 202936),
  ('n5-9d1aa046d6', 'ここでどのくらい止まりますか。', 'ここでどのくらい{止|と}まりますか。', NULL, 'How long do we stop here?', 224650),
  ('n5-72c525f37a', 'よい友達がたくさんいてうれしい。', 'よい{友達|ともだち}がたくさんいてうれしい。', NULL, 'I am happy to have so many good friends.', 192885),
  ('n5-72c525f37a', '友達がここにいないのでがっかりだ。', '{友達|ともだち}がここにいないのでがっかりだ。', NULL, 'I am disappointed that my friend is not here.', 79333),
  ('n5-86e7fb81c6', '私は土曜日からここにいます。', '{私|わたし}は{土曜日|どようび}からここにいます。', NULL, 'I''ve been here since Saturday.', 154894),
  ('n5-86e7fb81c6', 'その年のクリスマスは土曜日だった。', 'その{年|とし}のクリスマスは{土曜日|どようび}だった。', NULL, 'Christmas fell on Saturday that year.', 207297),
  ('n5-7e4fccba7f', 'なんてきれいな鳥なんだろう。', 'なんてきれいな{鳥|とり}なんだろう。', NULL, 'What a beautiful bird it is!', 198937),
  ('n5-7e4fccba7f', '木の中でさえずっている鳥を見てごらん。', '{木|き}の{中|なか}でさえずっている{鳥|とり}を{見|み}てごらん。', NULL, 'Look at the bird singing in the tree.', 80121),
  ('n5-3669c65744', '鶏肉を３ポンド分ください。', '{鶏肉|とりにく}を３ポンド{分|ぶん}ください。', NULL, 'I''d like three pounds of chicken.', 125767),
  ('n5-3669c65744', 'この鶏肉はよく揚げられている。', 'この{鶏肉|とりにく}はよく{揚|あ}げられている。', NULL, 'This chicken is fried well.', 222186),
  ('n5-4cc27797ba', '外からなら撮ってもかまいません。', '{外|そと}からなら{撮|と}ってもかまいません。', NULL, 'It doesn''t matter to us if you take a photo from the outside.', 184902),
  ('n5-4cc27797ba', '写真はあまり撮らなかったんだ。', '{写真|しゃしん}はあまり{撮|と}らなかったんだ。', NULL, 'I did not take many photos.', 156161),
  ('n5-1313ed47fb', 'そのお金はいざというときのために取っておくよ。', 'そのお{金|かね}はいざというときのために{取|と}っておくよ。', NULL, 'I''m going to lay aside that money for emergencies.', 213310),
  ('n5-1313ed47fb', '水分をたくさん取ってください。', '{水分|すいぶん}をたくさん{取|と}ってください。', NULL, 'You should drink a lot of liquid.', 143632),
  ('n5-3ae88c29c4', 'それはあなたのナイフではない。', NULL, NULL, 'That is not your knife.', 205569),
  ('n5-3ae88c29c4', 'すみません、ナイフを落としてしまいました。', 'すみません、ナイフを{落|お}としてしまいました。', NULL, 'I''m sorry, I dropped my knife.', 214129),
  ('n5-5d32281da9', 'テントの中ではなくて外で食べよう。', 'テントの{中|なか}ではなくて{外|そと}で{食|た}べよう。', NULL, 'Let''s eat outside instead of in our tents.', 201917),
  ('n5-5d32281da9', 'かごの中にはほとんどリンゴがない。', 'かごの{中|なか}にはほとんどリンゴがない。', NULL, 'There are few apples in the basket.', 226423),
  ('n5-fcea29f192', 'だんだん日が長くなっています。', 'だんだん{日|ひ}が{長|なが}くなっています。', NULL, 'The days are getting longer and longer.', 203060),
  ('n5-fcea29f192', '長くいらっしゃるつもりですか。', '{長|なが}くいらっしゃるつもりですか。', NULL, 'Are you going to stay long?', 125914),
  ('n5-07a4101167', 'カエルが鳴いたら帰ろう。', 'カエルが{鳴|な}いたら{帰|かえ}ろう。', NULL, 'Let''s return when the frog croaks.', 226439),
  ('n5-07a4101167', 'あのかわいい鳥は来る日も来る日も鳴いてばかりいた。', 'あのかわいい{鳥|とり}は{来|く}る{日|ひ}も{来|く}る{日|ひ}も{鳴|な}いてばかりいた。', NULL, 'That pretty bird did nothing but sing day after day.', 231343),
  ('n5-04015c3825', '私は前日無くした本を見つけた。', '{私|わたし}は{前日|ぜんじつ}{無|な}くした{本|ほん}を{見|み}つけた。', NULL, 'I found the book which I had lost the day before.', 155413),
  ('n5-04015c3825', '私はペンを無くしてしまった。', '{私|わたし}はペンを{無|な}くしてしまった。', NULL, 'I have lost my pen.', 158950),
  ('n5-ef9536b1ee', 'あなたはなぜ働いているの。', 'あなたはなぜ{働|はたら}いているの。', NULL, 'How come you''re still working?', 232436),
  ('n5-ef9536b1ee', 'なぜそんなにうれしがっているのか。', NULL, NULL, 'Why are you so happy?', 199245),
  ('n5-641ddbf693', 'アリは夏じゅうせっせとはたらく。', 'アリは{夏|なつ}じゅうせっせとはたらく。', NULL, 'Ants work away during summer.', 229963),
  ('n5-641ddbf693', 'とうとう夏がやってきたようだ。', 'とうとう{夏|なつ}がやってきたようだ。', NULL, 'Summer seems to have come at last.', 201234),
  ('n5-e09167a3d4', 'この夏休みはどこかへ行くのですか。', NULL, NULL, 'Are you going away this summer?', 222855),
  ('n5-e09167a3d4', '学校より夏休みのほうがいいです。', '{学校|がっこう}より{夏休|なつやす}みのほうがいいです。', NULL, 'I like summer holidays better than school.', 184362),
  ('n5-cf58476318', 'ぬくもりなどどこにも見つからない。', 'ぬくもりなどどこにも{見|み}つからない。', NULL, 'I can''t find anything like warmth anywhere.', 198659),
  ('n5-cf58476318', 'この雨の中を外出などできるものじゃない。', 'この{雨|あめ}の{中|なか}を{外出|がいしゅつ}などできるものじゃない。', NULL, 'Going out in this rain is out of the question.', 222937),
  ('n5-e65bf7ad23', '７つの海って何ですか。', '７つの{海|うみ}って{何|なに}ですか。', NULL, 'What are the seven seas?', 235014),
  ('n5-e65bf7ad23', '地球上には７つの大陸がある。', '{地球上|ちきゅうじょう}には７つの{大陸|たいりく}がある。', NULL, 'There are seven continents on the earth.', 126933),
  ('n5-75ed3c3b2b', '一週間は七日です。', '{一週間|いっしゅうかん}は{七日|なのか}です。', NULL, 'There are seven days in a week.', 190567),
  ('n5-75ed3c3b2b', '今、７日間の「ゴールデンウィーク」の休日です。', NULL, NULL, 'Now we have a seven-day Golden Week holiday.', 172942),
  ('n5-a812b1ac7f', 'あなたの名前はリストからはずされた。', 'あなたの{名前|なまえ}はリストからはずされた。', NULL, 'Your name was dropped from the list.', 232988),
  ('n5-a812b1ac7f', 'ここにあなたの名前を書きなさい。', 'ここにあなたの{名前|なまえ}を{書|か}きなさい。', NULL, 'Write down your name here.', 224507),
  ('n5-a95b0a87ad', '車の運転を習っています。', '{車|くるま}の{運転|うんてん}を{習|なら}っています。', NULL, 'I''ve been learning to drive.', 149053),
  ('n5-a95b0a87ad', '今ギターを習っています。', '{今|いま}ギターを{習|なら}っています。', NULL, 'I am learning to play the guitar now.', 172864),
  ('n5-1227b20370', 'あんた、なぜに並んでいるのだい。', 'あんた、なぜに{並|なら}んでいるのだい。', NULL, 'What are you lining up for?', 229608),
  ('n5-1227b20370', '女の子たちは並んで座っていました。', '{女|おんな}の{子|こ}たちは{並|なら}んで{座|すわ}っていました。', NULL, 'The girls were sitting side by side.', 147326);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-1635de1a94', 'メイドはテーブルにナイフとフォークを並べた。', 'メイドはテーブルにナイフとフォークを{並|なら}べた。', NULL, 'The maid arranged the knives and forks on the table.', 194690),
  ('n5-1635de1a94', '夕食がテーブルに並べられた。', '{夕食|ゆうしょく}がテーブルに{並|なら}べられた。', NULL, 'Supper was laid out on the table.', 79117),
  ('n5-e05de4981d', 'ちまたではインターネットなるものがはやっています。', NULL, NULL, 'People are talking about this Internet phenomenon.', 202981),
  ('n5-e05de4981d', '日がだんだん長くなってきています。', '{日|ひ}がだんだん{長|なが}くなってきています。', NULL, 'The days are getting longer and longer.', 122958),
  ('n5-558866ef86', '学校の前に何本か木が見えます。', NULL, NULL, 'You see some trees in front of the school.', 184431),
  ('n5-558866ef86', '「ユリ」を英語で何といいますか。', '「ユリ」を{英語|えいご}で{何|なん}といいますか。', NULL, 'What do you call "yuri" in English?', 236417),
  ('n5-34108268e1', 'このホールには人が二千人入れる。', NULL, NULL, 'Two thousand people fit into this hall.', 223188),
  ('n5-34108268e1', '二、三デメリットがありますね。', NULL, NULL, 'There are a few disadvantages to it.', 123182),
  ('n5-c17f97fafc', 'この通りは賑やかだ。', 'この{通|とお}りは{賑|にぎ}やかだ。', NULL, 'This street is lively.', 220474),
  ('n5-c17f97fafc', 'にぎやかなところが好きだ。', 'にぎやかなところが{好|す}きだ。', NULL, 'I like busy places.', 198795),
  ('n5-efac1fc502', '肉にはウジがわいていた。', '{肉|にく}にはウジがわいていた。', NULL, 'The meat was crawling with maggots.', 122996),
  ('n5-efac1fc502', 'お肉は食べられません。', 'お{肉|にく}は{食|た}べられません。', NULL, 'I can''t eat meat.', 226787),
  ('n5-436f1c3c65', '列車は西へ走っていた。', '{列車|れっしゃ}は{西|にし}へ{走|はし}っていた。', NULL, 'The train was hurrying west.', 77480),
  ('n5-436f1c3c65', '駅はホテルの西の方にある。', '{駅|えき}はホテルの{西|にし}の{方|ほう}にある。', NULL, 'The station is to the west of the hotel.', 188893),
  ('n5-d8c3a3f0d0', 'ちょうど日曜日にぶつかりますね。', 'ちょうど{日曜日|にちようび}にぶつかりますね。', NULL, 'It falls on Sunday.', 202889),
  ('n5-d8c3a3f0d0', '日曜日にはよくテニスをします。', '{日曜日|にちようび}にはよくテニスをします。', NULL, 'I often play tennis on Sunday.', 122163),
  ('n5-2e6c7d2d9d', 'これ荷物を上にあげてもよろしい。', 'これ{荷物|にもつ}を{上|うえ}にあげてもよろしい。', NULL, 'Can I put this up for you?', 217565),
  ('n5-2e6c7d2d9d', '荷物をはかりの上にのせてください。', '{荷物|にもつ}をはかりの{上|うえ}にのせてください。', NULL, 'Please put your baggage on this scale.', 186542),
  ('n5-b824bec2c5', 'そのニュースはラジオで聞いたよ。', 'そのニュースはラジオで{聞|き}いたよ。', NULL, 'I heard the news on the radio.', 212803),
  ('n5-b824bec2c5', 'あのテレビニュースはいかがです？', NULL, NULL, 'How do you like that TV news program?', 231300),
  ('n5-9ef6c9d703', 'その庭にはバラがまったくなかった。', 'その{庭|にわ}にはバラがまったくなかった。', NULL, 'There weren''t any roses in the garden.', 207712),
  ('n5-9ef6c9d703', 'ウサギが庭の中をかけています。', 'ウサギが{庭|にわ}の{中|なか}をかけています。', NULL, 'A rabbit is running in the garden.', 228283),
  ('n5-3af80b5b2a', 'ここで靴を脱がなければなりませんか。', 'ここで{靴|くつ}を{脱|ぬ}がなければなりませんか。', NULL, 'Do I have to take off my shoes here?', 224569),
  ('n5-3af80b5b2a', 'コートを脱いだらどうですか。', 'コートを{脱|ぬ}いだらどうですか。', NULL, 'Why not take your coat off?', 224957),
  ('n5-2f01adebd7', 'このコーヒーはぬるいです。', NULL, NULL, 'This coffee is not hot enough.', 223801),
  ('n5-2f01adebd7', '風呂がぬるくて入った気がしなかった。', NULL, NULL, 'The bath was not hot enough and I was unable to enjoy it.', 196881),
  ('n5-18046e46a1', 'このネクタイはいくらですか。', NULL, NULL, 'How much is this tie?', 223401),
  ('n5-18046e46a1', 'ネクタイがほどけてるよ。', NULL, NULL, 'Your tie has come undone.', 178510),
  ('n5-cbbfc8cad6', '猫はにゃーにゃーいいつづけた。', '{猫|ねこ}はにゃーにゃーいいつづけた。', NULL, 'The cat continued to mew.', 121967),
  ('n5-cbbfc8cad6', '猫がソファーでねむっている。', '{猫|ねこ}がソファーでねむっている。', NULL, 'The cat is sleeping on the sofa.', 122010),
  ('n5-0c6e923ef9', '本を読んでるうちに寝てしまった。', '{本|ほん}を{読|よ}んでるうちに{寝|ね}てしまった。', NULL, 'While I was reading, I fell asleep.', 81604),
  ('n5-0c6e923ef9', 'あなたはいつもは何時に寝ますか。', 'あなたはいつもは{何時|なんじ}に{寝|ね}ますか。', NULL, 'What time do you usually turn in?', 232828),
  ('n5-278c1e0e04', 'これらの語をノートに書きなさい。', 'これらの{語|ご}をノートに{書|か}きなさい。', NULL, 'Write these words in your notebook.', 217911),
  ('n5-278c1e0e04', 'あなたのノートを見せてください。', 'あなたのノートを{見|み}せてください。', NULL, 'Please show me your notebook.', 233500),
  ('n5-7817fc9d64', '木は高ければ高いほど登りにくい。', '{木|き}は{高|たか}ければ{高|たか}いほど{登|のぼ}りにくい。', NULL, 'The taller a tree is, the harder it is to climb.', 80091),
  ('n5-7817fc9d64', 'トムはその高い木に登ろうとした。', 'トムはその{高|たか}い{木|き}に{登|のぼ}ろうとした。', NULL, 'Tom tried to climb the tall tree.', 200059),
  ('n5-5e8fc8669c', '何か飲み物をいただけますか。', NULL, NULL, 'May I have something to drink?', 188051),
  ('n5-5e8fc8669c', 'なにかおいしい飲み物をください。', 'なにかおいしい{飲|の}み{物|もの}をください。', NULL, 'Give me something nice to drink.', 199117),
  ('n5-e0bcec9bd9', 'コーラはみんな飲んでしまったの。', 'コーラはみんな{飲|の}んでしまったの。', NULL, 'Has all the coke been drunk?', 224842),
  ('n5-e0bcec9bd9', '今すぐにコーラが飲みたいんだ。', '{今|いま}すぐにコーラが{飲|の}みたいんだ。', NULL, 'I am just dying for a Coke right now.', 172829),
  ('n5-822c5e11a6', 'ほら、あなたの乗る電車が来たわ。', 'ほら、あなたの{乗|の}る{電車|でんしゃ}が{来|き}たわ。', NULL, 'Look, here comes your train.', 195969),
  ('n5-822c5e11a6', '車に乗るかどうか聞いたのです。', '{車|くるま}に{乗|の}るかどうか{聞|き}いたのです。', NULL, 'I asked if you wanted a ride.', 149076),
  ('n5-390ac6443d', 'その赤ちゃんは歯が生えはじめている。', 'その{赤|あか}ちゃんは{歯|は}が{生|は}えはじめている。', NULL, 'The baby is cutting his teeth.', 208598),
  ('n5-390ac6443d', '歯をくいしばってください。', '{歯|は}をくいしばってください。', NULL, 'Bite together, please.', 150960),
  ('n5-28111455cd', 'パーティーはたのしかったですか。', NULL, NULL, 'Did you enjoy yourself at the party?', 198449),
  ('n5-28111455cd', 'パーティーはいつにしましょうか。', NULL, NULL, 'When shall we have the party?', 198453),
  ('n5-542f39c93d', '「もしもし、ブラウンさんですか」「はい、そうです」', NULL, NULL, '"Hello, is this Mrs. Brown?" "Yes, this is Mrs. Brown."', 236422),
  ('n5-542f39c93d', 'はい、外出しませんでした。', 'はい、{外出|がいしゅつ}しませんでした。', NULL, 'No, I didn''t go out.', 198381),
  ('n5-5cc1dad1e8', '灰皿を下さい。', '{灰皿|はいざら}を{下|くだ}さい。', NULL, 'I need an ashtray.', 185012),
  ('n5-5cc1dad1e8', 'その缶は灰皿の代わりになる。', 'その{缶|かん}は{灰皿|はいざら}の{代|か}わりになる。', NULL, 'The can will do for an ashtray.', 211587);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-c428d02d43', '入る前にドアをノックして下さい。', '{入|はい}る{前|#1392580}にドアをノックして{下|くだ}さい。', NULL, 'Please knock on the door before you enter.', 122091),
  ('n5-c428d02d43', '校長が先生の後ろから入ってきた。', '{校長|こうちょう}が{先生|せんせい}の{後|うし}ろから{入|はい}ってきた。', NULL, 'The principal came in after the teacher.', 173570),
  ('n5-645e1e3b4d', 'この店に葉書がたくさんある。', 'この{店|みせ}に{葉書|はがき}がたくさんある。', NULL, 'There are many postcards in this store.', 220432),
  ('n5-645e1e3b4d', '葉書をおくれ。', '{葉書|はがき}をおくれ。', NULL, 'Send me a postcard.', 78830),
  ('n5-4729cc56f4', 'この靴はきつすぎてはけない。', 'この{靴|くつ}はきつすぎてはけない。', NULL, 'These shoes are too tight to get into.', 222263),
  ('n5-4729cc56f4', 'どうしたの、ベルボトムなんかはいて。', NULL, NULL, 'Have you lost your marbles, wearing those bell-bottoms?', 201604),
  ('n5-658b912df8', 'その箱はほとんどいっぱいでした。', 'その{箱|はこ}はほとんどいっぱいでした。', NULL, 'The box was almost full.', 207213),
  ('n5-658b912df8', 'その箱には何もありませんでした。', 'その{箱|はこ}には{何|なに}もありませんでした。', NULL, 'There was nothing in the box.', 207226),
  ('n5-7ce7f7d305', 'パーカーさんは箸で食べてみました。', 'パーカーさんは{箸|はし}で{食|た}べてみました。', NULL, 'Mr Parker tried eating with chopsticks.', 198541),
  ('n5-7ce7f7d305', 'ルーシーは箸が使えないんだ。', 'ルーシーは{箸|はし}が{使|つか}えないんだ。', NULL, 'Lucy cannot use chopsticks.', 192400),
  ('n5-8f663254b0', 'その橋はどれくらいの長さですか。', 'その{橋|はし}はどれくらいの{長|なが}さですか。', NULL, 'How long is the bridge?', 211389),
  ('n5-8f663254b0', 'その橋は長さが１００メートルある。', 'その{橋|はし}は{長|なが}さが１００メートルある。', NULL, 'The bridge has a span of 100 meters.', 211383),
  ('n5-8fea1e3f3c', '今コンサートが始まろうとしている。', '{今|いま}コンサートが{始|はじ}まろうとしている。', NULL, 'The concert is beginning now.', 172848),
  ('n5-8fea1e3f3c', '学校は８時半に始まりますか。', '{学校|がっこう}は８{時半|じはん}に{始|はじ}まりますか。', NULL, 'Does school start at eight-thirty?', 184419),
  ('n5-e5b36d7b24', '旅行の初めの二日間は雨降りだった。', '{旅行|りょこう}の{初|はじ}めの{二日間|ふつかかん}は{雨降|あめふ}りだった。', NULL, 'The first two days of my trip were rainy.', 162444),
  ('n5-e5b36d7b24', '初めよければすべてよし。', '{初|はじ}めよければすべてよし。', NULL, 'Well begun, well finished.', 147521),
  ('n5-3f18999e09', '初めてドリアンを食べました。', '{初|はじ}めてドリアンを{食|た}べました。', NULL, 'I ate durian for the first time.', 147562),
  ('n5-3f18999e09', '初めてのものばかりです。', '{初|はじ}めてのものばかりです。', NULL, 'Everything is so new to me!', 147558),
  ('n5-a2c1e54c17', '初めましてケン。', '{初|はじ}めましてケン。', NULL, 'Nice to meet you, Ken.', 147522),
  ('n5-a2c1e54c17', 'はじめまして、ジョーンズ夫人。', NULL, NULL, 'How do you do, Mrs. Jones?', 198254),
  ('n5-244e138920', 'あの走ってる少年をごらんなさい。', 'あの{走|はし}ってる{少年|しょうねん}をごらんなさい。', NULL, 'Look at that boy running.', 230641),
  ('n5-244e138920', 'スクールバスが走れませんでした。', 'スクールバスが{走|はし}れませんでした。', NULL, 'The school bus could not run.', 214986),
  ('n5-bd7df6c7a2', 'バス通学と積極的差別是正措置などが論争の多い話題だった。', NULL, NULL, 'School busing and taking a proactive stance against discrimination were hotly debated topics.', 77225),
  ('n5-4385616659', 'バターはミルクから出来る。', 'バターはミルクから{出来|でき}る。', NULL, 'Butter is made from milk.', 198015),
  ('n5-4385616659', 'このバターつきパンをいただいてもいいですか。', NULL, NULL, 'May I have this bread and butter?', 223336),
  ('n5-c65a346458', 'ムーリエルは２０歳になりました。', NULL, NULL, 'Muiriel is 20 now.', 4707),
  ('n5-c65a346458', '私は２０歳になったところです。', NULL, NULL, 'I have turned 20.', 161998),
  ('n5-9ea671262d', 'スイッチは時間通りに働かなかった。', 'スイッチは{時間通|じかんどお}りに{働|はたら}かなかった。', NULL, 'The switch didn''t work on time.', 215137),
  ('n5-9ea671262d', '先生はここで働いているのだろう。', '{先生|せんせい}はここで{働|はたら}いているのだろう。', NULL, 'I wonder if the teacher works here.', 141700),
  ('n5-6eeff514e0', 'そのハイキングは八時間もかかるでしょう。', NULL, NULL, 'The hike will take no less than eight hours.', 212749),
  ('n5-6eeff514e0', 'それは八時から十時の間に起こった。', NULL, NULL, 'It happened between eight and ten.', 204945),
  ('n5-153de06669', '私は二十日までに帰るつもりです。', '{私|わたし}は{二十日|はつか}までに{帰|かえ}るつもりです。', NULL, 'I expect to be back by the 20th.', 154765),
  ('n5-153de06669', '卒業式は三月二十日に行われます。', NULL, NULL, 'The graduation ceremony will take place on March 20th.', 139663),
  ('n5-6485c3c2a7', 'テーブルの上に花が一本あります。', 'テーブルの{上|うえ}に{花|はな}が{一本|いっぽん}あります。', NULL, 'There is a flower on the table.', 202395),
  ('n5-6485c3c2a7', 'この花はなんてきれいなんだろう。', 'この{花|はな}はなんてきれいなんだろう。', NULL, 'How beautiful this flower is!', 222739),
  ('n5-8b5843f7fb', '鼻が出ているよ。かみなさい。', '{鼻|はな}が{出|で}ているよ。かみなさい。', NULL, 'Your nose is running. Blow it.', 85518),
  ('n5-8b5843f7fb', '鼻にポリープがあるようです。', '{鼻|はな}にポリープがあるようです。', NULL, 'I''m afraid I have a polyp in my nose.', 85515),
  ('n5-1ed0362cc3', '話を聞かせてくれ。', '{話|はなし}を{聞|き}かせてくれ。', NULL, 'I want a full report though.', 77142),
  ('n5-1ed0362cc3', '話があったら電話をかけて下さい。', '{話|はなし}があったら{電話|でんわ}をかけて{下|くだ}さい。', NULL, 'If you want to speak to me, please call me up.', 77204),
  ('n5-9d5bde24ec', '英語はカナダで話されている。', '{英語|えいご}はカナダで{話|はな}されている。', NULL, 'English is spoken in Canada.', 189149),
  ('n5-9d5bde24ec', 'ジョンはお客さんと電話で話した。', 'ジョンはお{客|きゃく}さんと{電話|でんわ}で{話|はな}した。', NULL, 'John talked with his customer on the phone.', 215417),
  ('n5-4db42e0181', '時のたつのは早いものだ。', '{時|とき}のたつのは{早|はや}いものだ。', NULL, 'Time flies.', 150671),
  ('n5-4db42e0181', '今年は春の訪れが早かった。', '{今年|ことし}は{春|はる}の{訪|おとず}れが{早|はや}かった。', NULL, 'Spring has come early this year.', 171315),
  ('n5-406d15f6e9', 'ショットはとても速いものもある。', 'ショットはとても{速|はや}いものもある。', NULL, 'Some people have very fast serves.', 215557),
  ('n5-406d15f6e9', '時のたつのってはやいものですね。', '{時|とき}のたつのってはやいものですね。', NULL, 'Time goes by very quickly, doesn''t it?', 150673),
  ('n5-f16244c585', 'カッコウは春にここにやってくる。', 'カッコウは{春|はる}にここにやってくる。', NULL, 'Cuckoos visit here in spring.', 226353),
  ('n5-f16244c585', '春になると川がここであふれる。', '{春|はる}になると{川|かわ}がここであふれる。', NULL, 'Every spring the river floods here.', 147635),
  ('n5-f47c4aee42', 'その写真はアルバムに貼ったほうがよい。', 'その{写真|しゃしん}はアルバムに{貼|は}ったほうがよい。', NULL, 'You should stick those pictures in your album.', 209617),
  ('n5-f47c4aee42', 'あなたの名前がテープでケースに貼ってあります。', NULL, NULL, 'Your name is taped on the case.', 233000),
  ('n5-9edf8548bb', 'ロンドンの天気は晴れです。', 'ロンドンの{天気|てんき}は{晴|は}れです。', NULL, 'The weather is fine in London.', 192149);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-9edf8548bb', '晴れにならないと思う。', '{晴|は}れにならないと{思|おも}う。', NULL, 'I don''t suppose it''s going to be sunny.', 143007),
  ('n5-3be88666ba', 'あした晴れてくれるといいなあ。', 'あした{晴|は}れてくれるといいなあ。', NULL, 'I hope the weather will clear up tomorrow.', 234462),
  ('n5-3be88666ba', '間もなく、晴れてきそうだ。', '{間|ま}もなく、{晴|は}れてきそうだ。', NULL, 'It''s going to clear up soon.', 183770),
  ('n5-9cd7c780c3', '半時間したら彼はここに来るでしょう。', '{半|はん}{時間|じかん}したら{彼|かれ}はここに{来|く}るでしょう。', NULL, 'He will be here in half an hour.', 121264),
  ('n5-9cd7c780c3', '海まではわずか半マイルだ。', '{海|うみ}まではわずか{半|はん}マイルだ。', NULL, 'It is no more than half a mile to the sea.', 185085),
  ('n5-532c73de5d', '晩までにはおそらく雨になるだろう。', '{晩|ばん}までにはおそらく{雨|あめ}になるだろう。', NULL, 'It may well rain before tonight.', 121181),
  ('n5-532c73de5d', 'その晩は月が出ていた。', 'その{晩|ばん}は{月|つき}が{出|で}ていた。', NULL, 'There was a moon that night.', 207157),
  ('n5-ee3206bb3f', 'このハンカチはいくらですか。', NULL, NULL, 'How much is this handkerchief?', 223306),
  ('n5-ee3206bb3f', '私はハンカチにアイロンをかけた。', '{私|わたし}はハンカチにアイロンをかけた。', NULL, 'I ironed my handkerchiefs.', 161866),
  ('n5-67775e3b25', '番号をまちがえじゃありませんか。', '{番号|ばんごう}をまちがえじゃありませんか。', NULL, 'I''m afraid you have got the wrong number.', 121170),
  ('n5-67775e3b25', 'お名前とフライト番号をどうぞ。', 'お{名前|なまえ}とフライト{番号|ばんごう}をどうぞ。', NULL, 'Your name and flight number, please?', 226580),
  ('n5-246b5ae84d', '晩ご飯ですよ、お父さん。', NULL, NULL, 'Dinner is ready, Father.', 121185),
  ('n5-246b5ae84d', 'おいしい晩御飯をありがとうございました。', 'おいしい{晩御飯|ばんごはん}をありがとうございました。', NULL, 'Thank you for the wonderful dinner.', 227833),
  ('n5-a1cda8cb11', 'ケーキのどちらの半分でもとりなさい。', 'ケーキのどちらの{半分|はんぶん}でもとりなさい。', NULL, 'You may take either half of the cake.', 225320),
  ('n5-a1cda8cb11', 'それを半分にきりなさい。', 'それを{半分|はんぶん}にきりなさい。', NULL, 'Cut it in half.', 204534),
  ('n5-0a38c65004', 'その市はロンドンの東にある。', 'その{市|し}はロンドンの{東|ひがし}にある。', NULL, 'The city lies east of London.', 210091),
  ('n5-0a38c65004', '東の空が白み始めていた。', '{東|ひがし}の{空|そら}が{白|しら}み{始|はじ}めていた。', NULL, 'The eastern sky was getting light.', 124292),
  ('n5-5b84039234', 'カーテンがゆっくり引かれた。', 'カーテンがゆっくり{引|ひ}かれた。', NULL, 'The curtains were drawn slowly.', 226492),
  ('n5-5b84039234', 'あんな本みたらフツーの女は引くもんな！', 'あんな{本|ほん}みたらフツーの{女|おんな}は{引|ひ}くもんな！', NULL, 'Obviously a normal woman would lose interest if she saw a book like that!', 76875),
  ('n5-23911a0718', 'ギターをひくのはおもしろい。', NULL, NULL, 'Playing the guitar is fun.', 226059),
  ('n5-23911a0718', 'アンがピアノをひいているはずがない。', NULL, NULL, 'Ann cannot be playing the piano.', 229616),
  ('n5-e25cf6ed2f', 'ラジオの音を低くして下さい。', 'ラジオの{音|おと}を{低|ひく}くして{下|くだ}さい。', NULL, 'Please turn down the radio.', 192612),
  ('n5-e25cf6ed2f', 'このイスは私には低すぎる。', 'このイスは{私|わたし}には{低|ひく}すぎる。', NULL, 'This chair is too low for me.', 223992),
  ('n5-a81612169c', 'あなたは飛行機で旅行したことがありますか。', 'あなたは{飛行機|ひこうき}で{旅行|りょこう}したことがありますか。', NULL, 'Have you ever traveled by air?', 231608),
  ('n5-a81612169c', '飛行機はまもなく見えなくなった。', '{飛行機|ひこうき}はまもなく{見|み}えなくなった。', NULL, 'The airplane soon went out of sight.', 85661),
  ('n5-ec5bd86b72', 'アラビア語は右から左へ書きます。', 'アラビア{語|ご}は{右|みぎ}から{左|ひだり}へ{書|か}きます。', NULL, 'Arabic is written from right to left.', 230059),
  ('n5-ec5bd86b72', '入るお金が右から左へと出てしまう。', '{入|はい}るお{金|かね}が{右|みぎ}から{左|ひだり}へと{出|で}てしまう。', NULL, 'I spend money as soon as I get it.', 122093),
  ('n5-d91ee7a9ed', 'どんな人でもいないよりはましだ。', 'どんな{人|ひと}でもいないよりはましだ。', NULL, 'Anybody would be better than nobody.', 199395),
  ('n5-d91ee7a9ed', 'お前はすぐ人のせいにするからな。', 'お{前|まえ}はすぐ{人|ひと}のせいにするからな。', NULL, 'You always try to blame somebody else.', 226941),
  ('n5-537f8af3d6', '車にはハンドルが一つある。', '{車|くるま}にはハンドルが{一|ひと}つある。', NULL, 'A car has one steering wheel.', 149093),
  ('n5-537f8af3d6', 'スーツケースが一つ見つからないんです。', 'スーツケースが{一|ひと}つ{見|み}つからないんです。', NULL, 'One of my suitcases is missing.', 215075),
  ('n5-3554fb81b8', '金がなくなる頃にはもうひと月ある。', '{金|かね}がなくなる{頃|ころ}にはもうひと{月|つき}ある。', NULL, 'When the money runs out, there''ll still be one month left.', 179773),
  ('n5-3554fb81b8', 'あなたは、ひと月にどのくらい洗車しますか。', 'あなたは、ひと{月|つき}にどのくらい{洗車|せんしゃ}しますか。', NULL, 'About how many times a month do you wash your car?', 232929),
  ('n5-3fb1b70809', 'どうしてあなたは一人になったの？', 'どうしてあなたは{一人|ひとり}になったの？', NULL, 'How did you end up on your own?', 201572),
  ('n5-3fb1b70809', '私は一人の弟がいます。', '{私|わたし}は{一人|ひとり}の{弟|おとうと}がいます。', NULL, 'I have one brother.', 158458),
  ('n5-7a9ce8e2df', 'ジョンはひどく急いでいたので話をする暇もなかった。', 'ジョンはひどく{急|いそ}いでいたので{話|はなし}をする{暇|ひま}もなかった。', NULL, 'John was in such a hurry that he had no time for talking.', 215363),
  ('n5-7a9ce8e2df', 'あしたは一日中ひまです。', 'あしたは{一日中|いちにちじゅう}ひまです。', NULL, 'I''ll be free all day tomorrow.', 234469),
  ('n5-13696bc9b5', '百年後にはみな同じになる。', NULL, NULL, 'It will be all the same a hundred years hence.', 85413),
  ('n5-13696bc9b5', '百歳まで生きる人はほとんどいません。', NULL, NULL, 'Few people live to be 100 years old.', 85416),
  ('n5-734d275fd9', 'この近くに病院はありますか。', 'この{近|ちか}くに{病院|びょういん}はありますか。', NULL, 'Is there a hospital near here?', 222301),
  ('n5-734d275fd9', '病院まで１０マイルもある。', '{病院|びょういん}まで１０マイルもある。', NULL, 'It is no less than ten miles to the hospital.', 85328),
  ('n5-c551bc3f7c', 'ボブはいったい病気なのだろうか。', 'ボブはいったい{病気|びょうき}なのだろうか。', NULL, 'Can Bob be sick?', 196062),
  ('n5-c551bc3f7c', 'ブラウンさんはその時病気でした。', 'ブラウンさんはその{時|とき}{病気|びょうき}でした。', NULL, 'Mr Brown was sick at the time.', 197091),
  ('n5-5d7a8d133b', '昼はホットドッグを食べたんだ。', '{昼|ひる}はホットドッグを{食|た}べたんだ。', NULL, 'I ate a hot dog for lunch.', 155091),
  ('n5-5d7a8d133b', 'ケンは昼まで家にいるでしょう。', 'ケンは{昼|ひる}まで{家|いえ}にいるでしょう。', NULL, 'Ken will be at home until noon.', 225117),
  ('n5-0b492c3209', '昼ご飯を食べに外に出ませんか。', '{昼|ひる}ご{飯|はん}を{食|た}べに{外|そと}に{出|で}ませんか。', NULL, 'How about going out for lunch?', 126420),
  ('n5-0b492c3209', '今は外出しないで。もうすぐ昼ご飯にするとこだから。', '{今|いま}は{外出|がいしゅつ}しないで。もうすぐ{昼|ひる}ご{飯|はん}にするとこだから。', NULL, 'Don''t go out now. We''re about to have lunch.', 172658),
  ('n5-230d5c7343', 'この通りは広いが、あまり長くない。', 'この{通|とお}りは{広|ひろ}いが、あまり{長|なが}くない。', NULL, 'This avenue is wide but not very long.', 220476),
  ('n5-230d5c7343', 'どのくらい広い？', 'どのくらい{広|ひろ}い？', NULL, 'How big?', 200414),
  ('n5-ef9babb012', 'カラーフィルムを一本ください。', 'カラーフィルムを{一本|いっぽん}ください。', NULL, 'I want a roll of color film for prints.', 226201);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-ef9babb012', 'フィルムがなくなった。', NULL, NULL, 'My film has run out.', 197224),
  ('n5-d156402900', 'だれがこの封筒を破って開けたのか。', 'だれがこの{封筒|ふうとう}を{破|やぶ}って{開|あ}けたのか。', NULL, 'Who has torn the envelope open?', 203217),
  ('n5-d156402900', '封筒をください。', '{封筒|ふうとう}をください。', NULL, 'I need an envelope.', 84069),
  ('n5-55c1439239', 'サウナとプールがあります。', NULL, NULL, 'There''s a sauna and a pool.', 2301777),
  ('n5-55c1439239', 'それはこころをひきつけるようなプールだ。', NULL, NULL, 'That pool really looks inviting.', 205516),
  ('n5-15f4136421', 'あの日は強い風が吹いていました。', 'あの{日|ひ}は{強|つよ}い{風|かぜ}が{吹|ふ}いていました。', NULL, 'There was a strong wind that day.', 230511),
  ('n5-15f4136421', 'テッドはトランペットを吹くのが好きです。', 'テッドはトランペットを{吹|ふ}くのが{好|す}きです。', NULL, 'Ted likes playing the trumpet.', 202226),
  ('n5-68571540e1', 'この服はわたしにはもったいない。', 'この{服|ふく}はわたしにはもったいない。', NULL, 'This suit is too good for me.', 219956),
  ('n5-68571540e1', 'スーザンはジルに服をつくってやった。', 'スーザンはジルに{服|ふく}をつくってやった。', NULL, 'Susan made a dress for Jill.', 215109),
  ('n5-0c1dbd4838', '二つのうちでどちらが高いですか。', '{二|ふた}つのうちでどちらが{高|たか}いですか。', NULL, 'Which is the more expensive of the two?', 123179),
  ('n5-0c1dbd4838', 'サリーはケンよりも二つ年上です。', 'サリーはケンよりも{二|ふた}つ{年上|としうえ}です。', NULL, 'Sally is two years senior to Ken.', 216654),
  ('n5-c518fb9116', 'この豚肉は１キロいくらですか。', 'この{豚肉|ぶたにく}は１キロいくらですか。', NULL, 'How much is this pork a kilo?', 220250),
  ('n5-c518fb9116', 'この豚肉は少しいたんでいる。', 'この{豚肉|ぶたにく}は{少|すこ}しいたんでいる。', NULL, 'This pork is a bit off.', 220249),
  ('n5-94c2076821', '二人は何をしているところですか。', '{二人|ふたり}は{何|なに}をしているところですか。', NULL, 'What are you two doing?', 123073),
  ('n5-94c2076821', '二人だけでお話ししたいのですが。', '{二人|ふたり}だけでお{話|はな}ししたいのですが。', NULL, 'May I talk with you in private about the matter?', 123125),
  ('n5-750786cc55', 'それは１週間前、すなわち４月２日に行われた。', NULL, NULL, 'It was due a week ago, namely on April second.', 205590),
  ('n5-750786cc55', 'このミルクは二日はもつ。', 'このミルクは{二日|ふつか}はもつ。', NULL, 'The milk will keep for two days.', 223124),
  ('n5-4162724f9a', '彼は太い首をしている。', '{彼|かれ}は{太|ふと}い{首|くび}をしている。', NULL, 'He has a thick neck.', 102554),
  ('n5-4162724f9a', '私の妹は足が太いのをひどく気にしている。', NULL, NULL, 'My sister is sensitive about her thick legs.', 162597),
  ('n5-eb9acca7ba', 'まもなく冬だ。', 'まもなく{冬|ふゆ}だ。', NULL, 'It will be winter before long.', 195261),
  ('n5-eb9acca7ba', '冬でもなおアスパラガスが食べられる。', '{冬|ふゆ}でもなおアスパラガスが{食|た}べられる。', NULL, 'You can still get asparagus in the winter.', 124383),
  ('n5-5791e248f1', 'シカゴのあたりでは雨が降っていました。', 'シカゴのあたりでは{雨|あめ}が{降|ふ}っていました。', NULL, 'It was raining around Chicago.', 216365),
  ('n5-5791e248f1', '六月は来る日も来る日も雨が降る。', '{六月|ろくがつ}は{来|く}る{日|ひ}も{来|く}る{日|ひ}も{雨|あめ}が{降|ふ}る。', NULL, 'In June, it rains day after day.', 77239),
  ('n5-aa60dd4a11', '時は金なりと古いことわざにもある。', '{時|とき}は{金|かね}なりと{古|ふる}いことわざにもある。', NULL, 'An old proverb says that time is money.', 150654),
  ('n5-aa60dd4a11', 'これらは何と古い本なのだろう。', 'これらは{何|なん}と{古|ふる}い{本|ほん}なのだろう。', NULL, 'What old books these are!', 217719),
  ('n5-34784ed6ca', '私は一日おきにふろに入ります。', '{私|わたし}は{一日|いちにち}おきにふろに{入|はい}ります。', NULL, 'I have a bath every other day.', 158438),
  ('n5-34784ed6ca', '彼はふろに水を入れた。', '{彼|かれ}はふろに{水|みず}を{入|い}れた。', NULL, 'He ran water into the bathtub.', 111040),
  ('n5-79ddbb2b98', 'ヘミングウェイの文章は悪文だった。', 'ヘミングウェイの{文章|ぶんしょう}は{悪文|あくぶん}だった。', NULL, 'Hemingway had a poor writing style.', 74604),
  ('n5-79ddbb2b98', '次の文章を日本語に直しなさい。', NULL, NULL, 'Put the following sentences into Japanese.', 150227),
  ('n5-f8fc73bd75', 'もう３ページ残っている。', 'もう３ページ{残|のこ}っている。', NULL, 'I have three more pages to go.', 194523),
  ('n5-f8fc73bd75', 'このページはリンクフリーです。', NULL, NULL, 'You may link to this webpage freely.', 76749),
  ('n5-619dae70e9', 'いいわけをするのがとても下手。', 'いいわけをするのがとても{下手|へた}。', NULL, 'He is very bad at inventing excuses.', 229378),
  ('n5-619dae70e9', '彼はイギリス生まれだが、英語がとても下手である。', '{彼|かれ}はイギリス{生|う}まれだが、{英語|えいご}がとても{下手|へた}である。', NULL, 'He comes from England, but is very poor at English.', 114691),
  ('n5-91cf4ea2fd', 'どんなベッドでもないよりはよい。', NULL, NULL, 'Any bed is better than no bed.', 199480),
  ('n5-91cf4ea2fd', 'もうベッドにつかなくてはなりません。', NULL, NULL, 'I''d better go to bed now.', 194366),
  ('n5-db38ebd955', 'あなたはペットの世話ができない。', 'あなたはペットの{世話|せわ}ができない。', NULL, 'You can''t care for pets.', 232403),
  ('n5-db38ebd955', '今、ごく小さなペットが流行っている。', '{今|いま}、ごく{小|ちい}さなペットが{流行|はや}っている。', NULL, 'Tiny pets are in fashion now.', 172937),
  ('n5-e78074927c', 'マユコは部屋に入った。', 'マユコは{部屋|へや}に{入|はい}った。', NULL, 'Mayuko entered the room.', 195194),
  ('n5-e78074927c', '部屋をそのままにしておきなさい。', '{部屋|へや}をそのままにしておきなさい。', NULL, 'Leave the room as it is.', 84128),
  ('n5-71c372d7b2', 'この辺にホテルはありますか。', 'この{辺|へん}にホテルはありますか。', NULL, 'Is there a hotel around here?', 223208),
  ('n5-71c372d7b2', 'このへんはとてもさびしい。', NULL, NULL, 'This neighborhood is very lonely.', 223204),
  ('n5-dd1183b005', 'リンゴと本の間にペンがあります。', 'リンゴと{本|ほん}の{間|あいだ}にペンがあります。', NULL, 'There is a pen between the apple and the book.', 192465),
  ('n5-dd1183b005', 'ペンとインキで書きなさい。', 'ペンとインキで{書|か}きなさい。', NULL, 'Write with pen and ink.', 196625),
  ('n5-65783b95dd', 'あなたは何時間勉強していますか。', 'あなたは{何時間|なんじかん}{勉強|べんきょう}していますか。', NULL, 'How many hours have you been studying?', 232202),
  ('n5-65783b95dd', 'なぜあなたは毎日勉強するのですか。', 'なぜあなたは{毎日|まいにち}{勉強|べんきょう}するのですか。', NULL, 'Why do you study every day?', 199272),
  ('n5-84887dde48', '電話は便利なものである。', NULL, NULL, 'The telephone is a convenience.', 124682),
  ('n5-84887dde48', 'そりゃ便利だね。', 'そりゃ{便利|べんり}だね。', NULL, 'That comes in handy.', 205969),
  ('n5-cfc75623ae', 'この帽子は１０００円なら安い。', 'この{帽子|ぼうし}は１０００{円|えん}なら{安|やす}い。', NULL, 'This hat is cheap at 1000 yen.', 219814),
  ('n5-cfc75623ae', 'その帽子はあなたには小さすぎる。', 'その{帽子|ぼうし}はあなたには{小|ちい}さすぎる。', NULL, 'It is too small a hat for you.', 206735),
  ('n5-785a997045', 'ボールペンのインクがなくなった。', NULL, NULL, 'My ballpoint pen just ran out of ink.', 196456);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-785a997045', 'ボールペンで書いていただけませんか？', 'ボールペンで{書|か}いていただけませんか？', NULL, 'Will you write with a ballpoint pen?', 196458),
  ('n5-f71c69492e', 'ほかの女の子たちはどこにいるの。', 'ほかの{女|おんな}の{子|こ}たちはどこにいるの。', NULL, 'Where are the other girls?', 196427),
  ('n5-f71c69492e', 'これはほかのどの木よりも高い。', 'これはほかのどの{木|き}よりも{高|たか}い。', NULL, 'This is taller than any other tree.', 218528),
  ('n5-ab9f2792c4', 'ポケットに何を持っていますか。', 'ポケットに{何|なに}を{持|も}っていますか。', NULL, 'What do you have in your pocket?', 232398),
  ('n5-ab9f2792c4', 'このコートにはポケットがない。', NULL, NULL, 'The coat doesn''t have any pockets.', 223814),
  ('n5-418493d941', '友人はマイカーを欲しがっている。', '{友人|ゆうじん}はマイカーを{欲|ほ}しがっている。', NULL, 'My friend wants a car of his own.', 79360),
  ('n5-418493d941', 'もっとパイが欲しい人はいますか。', 'もっとパイが{欲|ほ}しい{人|ひと}はいますか。', NULL, 'Does anyone want some more pie?', 193337),
  ('n5-2dbe65ee1d', 'ポストはどこにありますか。', NULL, NULL, 'Where is the mailbox?', 196278),
  ('n5-2dbe65ee1d', 'この辺りにポストはありません。', 'この{辺|あた}りにポストはありません。', NULL, 'Is there a mailbox near here?', 219866),
  ('n5-785adc4f9d', '彼は太っているくせに声は細い。', '{彼|かれ}は{太|ふと}っているくせに{声|こえ}は{細|ほそ}い。', NULL, 'His voice is thin even though he is fat.', 102553),
  ('n5-785adc4f9d', '細く長く愛して。', NULL, NULL, 'Love me lithe, love me long.', 237482),
  ('n5-04ab635f4b', 'レーンコートのボタンがとれた。', NULL, NULL, 'A button has come off my raincoat.', 192366),
  ('n5-04ab635f4b', 'ボタンがコートから外れている。', 'ボタンがコートから{外|はず}れている。', NULL, 'A button has come off the coat.', 196251),
  ('n5-23ec5a0b3d', 'あなたはこのホテルのお客ですか。', 'あなたはこのホテルのお{客|きゃく}ですか。', NULL, 'Are you staying at this hotel?', 232725),
  ('n5-23ec5a0b3d', 'ヒルトンホテルまでいくらですか。', NULL, NULL, 'How much is the fare to the Hilton Hotel?', 197388),
  ('n5-0e8f798dbf', 'ウイスキーを１本持っています。', NULL, NULL, 'I have a bottle of whiskey.', 228339),
  ('n5-0e8f798dbf', '本をさかさまに入れないで下さい。', '{本|ほん}をさかさまに{入|い}れないで{下|くだ}さい。', NULL, 'Don''t put the books in the shelf upside down.', 81634),
  ('n5-3839786bac', '私は本棚の本をすべて読んだわけではない。', '{私|わたし}は{本棚|ほんだな}の{本|ほん}をすべて{読|よ}んだわけではない。', NULL, 'I haven''t read all the books on the shelves.', 152787),
  ('n5-3839786bac', 'ジョンは本棚を作った。', 'ジョンは{本棚|ほんだな}を{作|つく}った。', NULL, 'John built a bookcase.', 215222),
  ('n5-849baaf2c3', '本当のマンションではありません。', '{本当|ほんとう}のマンションではありません。', NULL, 'It isn''t a real apartment.', 81497),
  ('n5-849baaf2c3', 'もしそれが本当ならどうしますか。', 'もしそれが{本当|ほんとう}ならどうしますか。', NULL, 'Suppose it were true; what would you do?', 193838),
  ('n5-a59ba12bc5', '毎朝ジョギングすることにした。', '{毎朝|まいあさ}ジョギングすることにした。', NULL, 'I''ve decided to jog every morning.', 81346),
  ('n5-a59ba12bc5', '私は毎朝８時に学校へ出かける。', '{私|わたし}は{毎朝|まいあさ}８{時|じ}に{学校|がっこう}へ{出|で}かける。', NULL, 'I leave for school at eight every morning.', 152747),
  ('n5-771fbe6b4d', '毎月のガス代はいくらですか。', NULL, NULL, 'How much is your monthly gas bill?', 81361),
  ('n5-771fbe6b4d', '私は本代に毎月千円もらいます。', NULL, NULL, 'I am allowed 1,000 yen a month for books.', 152788),
  ('n5-fd1c93832f', '父は毎週日曜日にゴルフをします。', '{父|ちち}は{毎週|まいしゅう}{日曜日|にちようび}にゴルフをします。', NULL, 'My father plays golf every Sunday.', 84362),
  ('n5-fd1c93832f', '父は毎週日曜日にテニスをする。', '{父|ちち}は{毎週|まいしゅう}{日曜日|にちようび}にテニスをする。', NULL, 'My father plays tennis every Sunday.', 84360),
  ('n5-039a696225', '毎日うっとうしくていやですね。', '{毎日|まいにち}うっとうしくていやですね。', NULL, 'Don''t you just hate this weather?', 81316),
  ('n5-039a696225', 'あなたは毎日どれぐらいテニスをしますか。', 'あなたは{毎日|まいにち}どれぐらいテニスをしますか。', NULL, 'How long do you play tennis every day?', 231557),
  ('n5-83700909d4', '毎年ここに来なきゃ。', NULL, NULL, 'I''ll have to come here every year.', 81248),
  ('n5-83700909d4', '毎年行きます。', NULL, NULL, 'I go every year.', 81243),
  ('n5-2584943533', '私は毎晩家にいます。', '{私|わたし}は{毎晩|まいばん}{家|いえ}にいます。', NULL, 'I am at home every evening.', 152681),
  ('n5-2584943533', 'マイクはほとんど毎晩外食だ。', 'マイクはほとんど{毎晩|まいばん}{外食|がいしょく}だ。', NULL, 'Mike eats out almost every night.', 195755),
  ('n5-319e218950', '外へ出る前に靴を磨きなさい。', NULL, NULL, 'Shine your shoes before going out.', 184856),
  ('n5-ae3e0a705f', '２ブロック先まで歩き、左へ曲がりなさい。', NULL, NULL, 'Walk two blocks, and turn left.', 235525),
  ('n5-ae3e0a705f', 'この通りを２ブロック行って、左に曲がりなさい。', NULL, NULL, 'Go two blocks along this street and turn left.', 220472),
  ('n5-b19034ded1', 'あ！まずい！ガソリンが切れてきた。', 'あ！まずい！ガソリンが{切|き}れてきた。', NULL, 'Oh, no! We''re running out of gas.', 234772),
  ('n5-b19034ded1', 'ひもじい時にまずいものなし。', 'ひもじい{時|とき}にまずいものなし。', NULL, 'A good appetite is a good sauce.', 197452),
  ('n5-162e00c6ef', 'ジムもまたパーティーに来ます。', 'ジムもまたパーティーに{来|き}ます。', NULL, 'Jim is coming to the party, too.', 215924),
  ('n5-162e00c6ef', 'あの人は医者でありまた大学の先生でもある。', 'あの{人|ひと}は{医者|いしゃ}でありまた{大学|だいがく}の{先生|せんせい}でもある。', NULL, 'He is a doctor and a university professor.', 230730),
  ('n5-6a7163f5f7', 'なすべきことがまだたくさんある。', NULL, NULL, 'There still remains much to be done.', 199298),
  ('n5-6a7163f5f7', 'まだたっぷり時間がありますよ。', 'まだたっぷり{時間|じかん}がありますよ。', NULL, 'You''ve got plenty of time.', 195488),
  ('n5-4d76d06d84', 'その町はロンドンのすぐ北にある。', 'その{町|まち}はロンドンのすぐ{北|きた}にある。', NULL, 'The town lies just above London.', 207801),
  ('n5-4d76d06d84', 'この町に来たのははじめてですか。', 'この{町|まち}に{来|き}たのははじめてですか。', NULL, 'Is this the first time that you have come to this town?', 220531),
  ('n5-6a39701228', 'ちょっと待っていてもらえますか。', 'ちょっと{待|ま}っていてもらえますか。', NULL, 'Would you mind waiting a few minutes?', 202739),
  ('n5-6a39701228', 'すこし待つのは気になさいますか。', 'すこし{待|ま}つのは{気|き}になさいますか。', NULL, 'Do you mind waiting for a minute?', 214707),
  ('n5-ede9ab2f7f', 'まっすぐ前を見てください。', 'まっすぐ{前|#1392580}を{見|み}てください。', NULL, 'Look forward, please.', 195363),
  ('n5-ede9ab2f7f', 'サイドミラーがまっすぐになっていない。', NULL, NULL, 'My side mirror is out of alignment.', 216856),
  ('n5-27f9d40392', 'マッチありますか。', NULL, NULL, 'Do you have a match?', 195351),
  ('n5-27f9d40392', 'マッチを持っていますか。', 'マッチを{持|も}っていますか。', NULL, 'Have you got a match?', 195348);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-7734194821', '窓を開けっぱなしにしておいたの？', NULL, NULL, 'Did you leave the window open?', 231771),
  ('n5-7734194821', 'ぬれたぞうきんで窓をふきなさい。', 'ぬれたぞうきんで{窓|まど}をふきなさい。', NULL, 'Clean the window with a damp cloth.', 198657),
  ('n5-ab36109960', 'ボールは丸い。', 'ボールは{丸|まる}い。', NULL, 'Balls are round.', 196476),
  ('n5-ab36109960', '私たちは丸いテーブルを買った。', '{私|わたし}たちは{丸|まる}いテーブルを{買|か}った。', NULL, 'We bought a round table.', 165954),
  ('n5-a0ff0f67c8', 'このテープレコーダーは４万円しました。', NULL, NULL, 'I paid 40,000 yen for this tape recorder.', 223521),
  ('n5-a0ff0f67c8', '一千万円くらいかな？', NULL, NULL, 'Is it about ten million yen?', 190376),
  ('n5-6318b0423a', '新しい万年筆をなくしてしまった。', '{新|あたら}しい{万年筆|まんねんひつ}をなくしてしまった。', NULL, 'I have lost my new fountain pen.', 155723),
  ('n5-6318b0423a', 'パリで買ったのはこの万年筆です。', 'パリで{買|か}ったのはこの{万年筆|まんねんひつ}です。', NULL, 'It was this fountain pen that I bought in Paris.', 167932),
  ('n5-7309a238e8', 'そのなべを磨いていただけませんか。', 'そのなべを{磨|みが}いていただけませんか。', NULL, 'Would you scrape that rusty pan?', 212854),
  ('n5-7309a238e8', '学生は読書の技能を磨くべきだ。', '{学生|がくせい}は{読書|どくしょ}の{技能|ぎのう}を{磨|みが}くべきだ。', NULL, 'Students should develop their reading skills.', 184229),
  ('n5-f1046f3190', 'アラビア語は右から左へ書きます。', 'アラビア{語|ご}は{右|みぎ}から{左|ひだり}へ{書|か}きます。', NULL, 'Arabic is written from right to left.', 230059),
  ('n5-f1046f3190', '入るお金が右から左へと出てしまう。', '{入|はい}るお{金|かね}が{右|みぎ}から{左|ひだり}へと{出|で}てしまう。', NULL, 'I spend money as soon as I get it.', 122093),
  ('n5-8568eded6e', '日がだんだん短くなっている。', '{日|ひ}がだんだん{短|みじか}くなっている。', NULL, 'The days are becoming shorter.', 122959),
  ('n5-8568eded6e', 'あの犬はしっぽが短い。', 'あの{犬|いぬ}はしっぽが{短|みじか}い。', NULL, 'That dog has a short tail.', 231055),
  ('n5-69a792520f', 'ひざに水がたまっているようです。', 'ひざに{水|みず}がたまっているようです。', NULL, 'I''m afraid I have water in my knee joint.', 197613),
  ('n5-69a792520f', 'バケツに水がいっぱい入っている。', 'バケツに{水|みず}がいっぱい{入|はい}っている。', NULL, 'The bucket is full of water.', 198284),
  ('n5-0c8a588e53', '店はたたまれ、それっきりだった。', '{店|みせ}はたたまれ、それっきりだった。', NULL, 'The store closed down for good.', 124989),
  ('n5-0c8a588e53', '店にあるのは、これ一つだけです。', '{店|みせ}にあるのは、これ{一|ひと}つだけです。', NULL, 'It is the only one there is in the shop.', 124997),
  ('n5-db35a99e28', 'パスポートを見せてくれませんか。', 'パスポートを{見|み}せてくれませんか。', NULL, 'Will you show me your passport, please?', 198083),
  ('n5-db35a99e28', 'カールは金メダルを見せてくれた。', 'カールは{金|きん}メダルを{見|み}せてくれた。', NULL, 'Carl showed me the gold medal.', 226458),
  ('n5-dc29195f18', '二本の道はそこでクロスしている。', '{二本|にほん}の{道|みち}はそこでクロスしている。', NULL, 'The two roads cross there.', 75827),
  ('n5-dc29195f18', '父はこの道２０年のベテランです。', '{父|ちち}はこの{道|みち}２０{年|ねん}のベテランです。', NULL, 'My father has been doing this job for twenty years.', 84728),
  ('n5-1713d0bbe8', '１０月３日です。', NULL, NULL, 'It''s the third of October.', 236068),
  ('n5-1713d0bbe8', 'この本を読むのに３日かかった。', NULL, NULL, 'It took me three days to read this book.', 168024),
  ('n5-b36b221d33', 'コーヒー三つおねがいします。', 'コーヒー{三|みっ}つおねがいします。', NULL, 'Three coffees, please.', 224844),
  ('n5-b36b221d33', 'ボーイさん、コーヒー３つください。', NULL, NULL, 'Waiter, three coffees, please.', 196583),
  ('n5-85e4ba2f28', '東京ミッドタウンは緑がいっぱい！', '{東京|とうきょう}ミッドタウンは{緑|みどり}がいっぱい！', NULL, 'There''s a lot of greenery in Tokyo Midtown!', 74154),
  ('n5-85e4ba2f28', 'その緑のシャツを見せてください。', 'その{緑|みどり}のシャツを{見|み}せてください。', NULL, 'Please show me the green shirt.', 206210),
  ('n5-d2b9c47656', '皆さんじっとしていてください。', '{皆|みな}さんじっとしていてください。', NULL, 'Could you keep still, everyone?', 195074),
  ('n5-d2b9c47656', '皆さんネチケットはしっかり。', '{皆|みな}さんネチケットはしっかり。', NULL, 'Everyone, please keep to netiquette.', 75145),
  ('n5-84e465b526', 'フランスは英国の南にある。', 'フランスは{英国|えいこく}の{南|みなみ}にある。', NULL, 'France is to the south of England.', 196997),
  ('n5-84e465b526', 'まもなくツバメが南からやってくる。', 'まもなくツバメが{南|みなみ}からやってくる。', NULL, 'Soon, swallows will come from the south.', 195304),
  ('n5-e8cdf8b85a', 'なぜ、あなたの耳はそんなに大きいの？', 'なぜ、あなたの{耳|みみ}はそんなに{大|おお}きいの？', NULL, 'Why are your ears so big?', 199295),
  ('n5-e8cdf8b85a', '耳がしもやけになったんだ。', '{耳|みみ}がしもやけになったんだ。', NULL, 'My ears are frostbitten.', 150168),
  ('n5-85b37b6884', 'わたしはそれを見てぎょっとした。', 'わたしはそれを{見|み}てぎょっとした。', NULL, 'I was appalled at the sight.', 191835),
  ('n5-85b37b6884', 'テレビはここでは見られていない。', 'テレビはここでは{見|み}られていない。', NULL, 'TV is not watched here.', 201993),
  ('n5-2676514561', '女の子はほとんどみんなやさしい。', '{女|おんな}の{子|こ}はほとんどみんなやさしい。', NULL, 'Almost all girls are kind.', 147335),
  ('n5-2676514561', 'サーカスを見にみんなくりだした。', 'サーカスを{見|み}にみんなくりだした。', NULL, 'Everyone turned out for the circus.', 216907),
  ('n5-bf44ddad08', '４月５日か６日に会っていただけませんか。', NULL, NULL, 'Would it be possible to set up a meeting with us on April 5 or 6?', 235224),
  ('n5-bf44ddad08', '６日間学校に行けませんでした。', NULL, NULL, 'I missed school for six days.', 235021),
  ('n5-8e862f05f0', 'その男の子は向こうにいます。', 'その{男|おとこ}の{子|こ}は{向|む}こうにいます。', NULL, 'The boy is over there.', 208147),
  ('n5-8e862f05f0', '向こうの大きなビルをごらんなさい。', '{向|む}こうの{大|おお}きなビルをごらんなさい。', NULL, 'Look at the large building over there.', 173839),
  ('n5-0a3894175f', '外国人が日本語を学ぶのは難しい。', '{外国人|がいこくじん}が{日本語|にほんご}を{学|まな}ぶのは{難|むずか}しい。', NULL, 'It is difficult for a foreigner to study Japanese.', 184760),
  ('n5-0a3894175f', 'フランス語を話すことは難しい。', 'フランス{語|ご}を{話|はな}すことは{難|むずか}しい。', NULL, 'To speak French is difficult.', 196964),
  ('n5-7ecc2c4bfc', '彼は６行のうちに６つまちがいをした。', '{彼|かれ}は６{行|ぎょう}のうちに６つまちがいをした。', NULL, 'He made six mistakes in as many lines.', 93506),
  ('n5-7ecc2c4bfc', '彼女はそのケーキを６つに分けた。', '{彼女|かのじょ}はそのケーキを６つに{分|わ}けた。', NULL, 'She divided the cake into six pieces.', 92613),
  ('n5-5028971b39', '町は村よりも大きい。', '{町|まち}は{村|むら}よりも{大|おお}きい。', NULL, 'Towns are larger than villages.', 126109),
  ('n5-5028971b39', 'その村までたった２マイルです。', 'その{村|むら}までたった２マイルです。', NULL, 'It''s only two miles to the village.', 208294),
  ('n5-ae534d4ca8', '彼女はきれいな目をしている。', '{彼女|かのじょ}はきれいな{目|め}をしている。', NULL, 'She has beautiful eyes.', 92969),
  ('n5-ae534d4ca8', '３時間目にはフランス語があります。', '３{時間|じかん}{目|め}にはフランス{語|ご}があります。', NULL, 'We have French third period.', 235310);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-eb5450490b', '前の人から1メートル離れて並んでください。', NULL, NULL, 'Form a line, keeping one meter away from the person in front of you.', 140982),
  ('n5-72eb77e07a', '私はメガネがなくては読めない。', '{私|わたし}はメガネがなくては{読|よ}めない。', NULL, 'I cannot read without glasses.', 158805),
  ('n5-72eb77e07a', '母はメガネなしでは読書できない。', '{母|はは}はメガネなしでは{読書|どくしょ}できない。', NULL, 'My mother can''t read without glasses.', 83033),
  ('n5-c5b7ad76fd', 'もう～、なにやってんだよ。', NULL, NULL, 'Jeez, what''re you up to?', 74910),
  ('n5-c5b7ad76fd', 'もうそろそろ帰る時間だ。', 'もうそろそろ{帰|かえ}る{時間|じかん}だ。', NULL, 'It is about time we were leaving.', 194403),
  ('n5-3ae16ad93a', 'もう一度ゆっくりお話しください。', 'もう{一度|いちど}ゆっくりお{話|はな}しください。', NULL, 'Could you please repeat it slowly?', 194309),
  ('n5-3ae16ad93a', 'もう一度それにトライしてみたら。', 'もう{一度|いちど}それにトライしてみたら。', NULL, 'Why don''t you give it another try?', 194328),
  ('n5-d10bb92f3e', 'やあ、フレッド。木曜日にバドミントンはどう。', 'やあ、フレッド。{木曜日|もくようび}にバドミントンはどう。', NULL, 'Hi, Fred, how about badminton on Thursday?', 193147),
  ('n5-d10bb92f3e', '木曜日よりむしろ金曜日においでいただきたい。', '{木曜日|もくようび}よりむしろ{金曜日|きんようび}においでいただきたい。', NULL, 'I would rather you came on Friday than on Thursday.', 80049),
  ('n5-16fda19d79', 'コートを持ちましょうか。', 'コートを{持|も}ちましょうか。', NULL, 'Shall I carry your coat?', 224958),
  ('n5-16fda19d79', '今持っているお金はこれだけです。', '{今|いま}{持|も}っているお{金|かね}はこれだけです。', NULL, 'This is all the money that I have now.', 167740),
  ('n5-a8f5f4c59e', '父がもっと長生きしていたらなあ。', '{父|ちち}がもっと{長生|ながい}きしていたらなあ。', NULL, 'I wish my father had lived longer.', 84880),
  ('n5-a8f5f4c59e', 'もっと大きいサイズはありますか。', 'もっと{大|おお}きいサイズはありますか。', NULL, 'Do you have a larger size?', 193236),
  ('n5-782272bfda', 'どちらのかばんがあなたの物ですか。', 'どちらのかばんがあなたの{物|もの}ですか。', NULL, 'Which bag is yours?', 200773),
  ('n5-782272bfda', 'この本はみなあなたの物ですか。', 'この{本|ほん}はみなあなたの{物|もの}ですか。', NULL, 'Are all these books yours?', 219684),
  ('n5-5b92758003', 'ジョンは門のところまで出てきた。', 'ジョンは{門|もん}のところまで{出|で}てきた。', NULL, 'John moved forward to the gate.', 215219),
  ('n5-5b92758003', '門をたたけたたくものはあけてもらえるだろう。', '{門|もん}をたたけたたくものはあけてもらえるだろう。', NULL, 'Knock, and it will be opened to you.', 79781),
  ('n5-4f0f6b6ae7', '問題はお金がないということです。', '{問題|もんだい}はお{金|かね}がないということです。', NULL, 'The trouble is that we have no money.', 79848),
  ('n5-4f0f6b6ae7', 'そのことは問題にしたくないんだ。', 'そのことは{問題|もんだい}にしたくないんだ。', NULL, 'I don''t want to make an issue of it.', 213123),
  ('n5-8d29f60b23', 'その八百屋は客にとても親切だ。', 'その{八百屋|やおや}は{客|きゃく}にとても{親切|しんせつ}だ。', NULL, 'The greengrocer is very kind to his customers.', 207193),
  ('n5-8d29f60b23', '私は八百屋の外で彼に出会った。', '{私|わたし}は{八百屋|やおや}の{外|そと}で{彼|かれ}に{出会|であ}った。', NULL, 'I met him outside the greengrocer''s.', 154612),
  ('n5-936289666e', 'その店は野菜を売っている。', 'その{店|みせ}は{野菜|やさい}を{売|う}っている。', NULL, 'The store deals in vegetables.', 207603),
  ('n5-936289666e', '野菜をたくさん食べなさい。', '{野菜|やさい}をたくさん{食|た}べなさい。', NULL, 'Eat a lot of vegetables.', 79599),
  ('n5-ead1ae2736', 'もっと易しい事を聞いて下さい。', 'もっと{易|やさ}しい{事|こと}を{聞|き}いて{下|くだ}さい。', NULL, 'Ask me something easier.', 193198),
  ('n5-ead1ae2736', 'この本は易しい英語で書かれている。', 'この{本|ほん}は{易|やさ}しい{英語|えいご}で{書|か}かれている。', NULL, 'This book is written in easy English.', 219533),
  ('n5-33b86212ca', 'もっと安いものを見せてください。', 'もっと{安|やす}いものを{見|み}せてください。', NULL, 'Show me a cheaper one, please.', 193311),
  ('n5-33b86212ca', 'もっと安いものはありますか。', 'もっと{安|やす}いものはありますか。', NULL, 'Do you have less expensive ones?', 193312),
  ('n5-d4a1d27d3b', '学校はクリスマスで休みになった。', '{学校|がっこう}はクリスマスで{休|やす}みになった。', NULL, 'School has closed for the Christmas holidays.', 184412),
  ('n5-d4a1d27d3b', 'でも休みはとったほうがいいわよ。', 'でも{休|やす}みはとったほうがいいわよ。', NULL, 'I think you should get more rest.', 202088),
  ('n5-3e3efcb45f', '父はまだ休んでいる。', '{父|ちち}はまだ{休|やす}んでいる。', NULL, 'Father is still in bed.', 84662),
  ('n5-3e3efcb45f', '彼はしばらくの間休んだ。', '{彼|かれ}はしばらくの{間|あいだ}{休|やす}んだ。', NULL, 'He rested for a while.', 113559),
  ('n5-62c4216674', 'そこに八つの小石があった。', 'そこに{八|やっ}つの{小石|こいし}があった。', NULL, 'There were eight pebbles there.', 519714),
  ('n5-62c4216674', '母はケーキを８つに分けました。', '{母|はは}はケーキを８つに{分|わ}けました。', NULL, 'Mother divided the cake into eight pieces.', 83078),
  ('n5-e8a5cbdf0a', 'その山はどれくらいの高さですか。', 'その{山|やま}はどれくらいの{高|たか}さですか。', NULL, 'How high is the mountain?', 210451),
  ('n5-e8a5cbdf0a', 'この山の高さはどのくらいですか。', 'この{山|やま}の{高|たか}さはどのくらいですか。', NULL, 'What is the height of this mountain?', 221853),
  ('n5-f81d503d6f', '５ドルをやる。', NULL, NULL, 'Here''s $5.', 235161),
  ('n5-f81d503d6f', 'サイン書いてやってもいいぞ。', NULL, NULL, 'I can give you an autograph if you want.', 430482),
  ('n5-285b008622', 'ひょっとすると夕方前に雨になるかもしれない。', 'ひょっとすると{夕方|ゆうがた}{前|#1392580}に{雨|あめ}になるかもしれない。', NULL, 'It might rain before evening.', 197417),
  ('n5-285b008622', 'ある夕方、一人の男がやってきた。', 'ある{夕方|ゆうがた}、{一人|ひとり}の{男|おとこ}がやってきた。', NULL, 'One evening a man came to my house.', 229774),
  ('n5-ae2b9f6d7e', '夕飯はもう食べましたか。', NULL, NULL, 'Have you had dinner?', 79059),
  ('n5-ae2b9f6d7e', '夕飯を食べているときに電話がかかってきた。', NULL, NULL, 'The telephone rang while I was having supper.', 79058),
  ('n5-8b86921749', 'あの～郵便局はどちらでしょうか。', 'あの～{郵便局|ゆうびんきょく}はどちらでしょうか。', NULL, 'Uh..., where''s the post office?', 231383),
  ('n5-8b86921749', 'このあたりに郵便局はありますか。', 'このあたりに{郵便局|ゆうびんきょく}はありますか。', NULL, 'Is there a post office around here?', 224027),
  ('n5-39fff8fc4b', '昨夜はよく眠れましたか。', '{昨夜|ゆうべ}はよく{眠|ねむ}れましたか。', NULL, 'Did you have a good sleep last night?', 169654),
  ('n5-39fff8fc4b', '昨夜あなたはテレビを見ましたか。', '{昨夜|ゆうべ}あなたはテレビを{見|み}ましたか。', NULL, 'Did you watch TV last night?', 169693),
  ('n5-50b217ed0b', 'そのホテルは食事で有名である。', 'そのホテルは{食事|しょくじ}で{有名|ゆうめい}である。', NULL, 'The hotel is noted for its food.', 212598),
  ('n5-50b217ed0b', 'トーマス先生はとても有名な先生です。', NULL, NULL, 'Mr Thomas is a very able teacher.', 201079),
  ('n5-78c044b951', 'ひどい雪のため外出できなかった。', 'ひどい{雪|ゆき}のため{外出|がいしゅつ}できなかった。', NULL, 'The heavy snow kept us from going out.', 197547),
  ('n5-78c044b951', '雪のため、外に出られなかった。', '{雪|ゆき}のため、{外|そと}に{出|で}られなかった。', NULL, 'The snow kept us from going out.', 142003),
  ('n5-d980cb1531', 'おじいさんはとてもゆっくりと話す。', 'おじいさんはとてもゆっくりと{話|はな}す。', NULL, 'Grandfather speaks very slowly.', 227740);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-d980cb1531', 'メアリーは日本語をゆっくりと話しました。', 'メアリーは{日本語|にほんご}をゆっくりと{話|はな}しました。', NULL, 'Mary spoke Japanese slowly.', 194720),
  ('n5-4f8e83945d', '学校は４月８日から始まります。', NULL, NULL, 'School begins on April 8.', 184424),
  ('n5-4f8e83945d', '私は１９５０年１月８日に東京で生まれました。', NULL, NULL, 'I was born in Tokyo on the eighth of January in 1950.', 162088),
  ('n5-1907b6fc38', 'お前に新しい洋服を作ってあげよう。', 'お{前|まえ}に{新|あたら}しい{洋服|ようふく}を{作|つく}ってあげよう。', NULL, 'I will make a new suit for you.', 226963),
  ('n5-1907b6fc38', 'とてもすてきな洋服ですね。', 'とてもすてきな{洋服|ようふく}ですね。', NULL, 'That''s a beautiful dress.', 236922),
  ('n5-19db29fbbb', 'ジャック、よく来てくれたね。', 'ジャック、よく{来|き}てくれたね。', NULL, 'You are welcome, Jack!', 215788),
  ('n5-19db29fbbb', 'よく、そんな口がきけるな！', 'よく、そんな{口|くち}がきけるな！', NULL, 'How dare you say that!', 192833),
  ('n5-4cb7c969c4', '母親は赤ん坊をベッドに横にした。', '{母親|ははおや}は{赤|あか}ん{坊|ぼう}をベッドに{横|よこ}にした。', NULL, 'The mother laid her baby on the bed.', 82787),
  ('n5-4cb7c969c4', '道が濡れていたので、車は横にスリップしたにちがいない。', '{道|みち}が{濡|ぬ}れていたので、{車|くるま}は{横|よこ}にスリップしたにちがいない。', NULL, 'As the road was wet, the car must have slipped sideways.', 123621),
  ('n5-222ae96df7', '長くても４日しか待てませんよ。', NULL, NULL, 'I can wait four days at the longest.', 125908),
  ('n5-222ae96df7', '私は１９７４年６月４日に生まれた。', NULL, NULL, 'I was born on June 4, 1974.', 162081),
  ('n5-1000ee441a', 'その紙を四つ折りにしなさい。', 'その{紙|かみ}を{四|よっ}つ{折|お}りにしなさい。', NULL, 'Fold the paper in four.', 210071),
  ('n5-1000ee441a', '世界には四つの海洋がある。', '{世界|せかい}には{四|よっ}つの{海洋|かいよう}がある。', NULL, 'There are four oceans in the world.', 143446),
  ('n5-76f05a0739', 'あなたをケパと呼ぶことにします。', 'あなたをケパと{呼|よ}ぶことにします。', NULL, 'You will be called Cephas.', 231456),
  ('n5-76f05a0739', 'あなたが呼べば、彼は来るでしょう。', 'あなたが{呼|よ}べば、{彼|かれ}は{来|く}るでしょう。', NULL, 'He will come if you call him.', 234086),
  ('n5-eb7e675902', '本を読む時間がほとんどないんだ。', '{本|ほん}を{読|よ}む{時間|じかん}がほとんどないんだ。', NULL, 'I have little time to read.', 152798),
  ('n5-eb7e675902', '午前中はずっと本を読んでました。', '{午前中|ごぜんちゅう}はずっと{本|ほん}を{読|よ}んでました。', NULL, 'I have been reading a book all morning.', 157196),
  ('n5-6c214111ea', 'もうこれよりほかに手はない。', 'もうこれよりほかに{手|て}はない。', NULL, 'There''s no other way than this now.', 194478),
  ('n5-6c214111ea', 'どんなベッドでもないよりはよい。', NULL, NULL, 'Any bed is better than no bed.', 199480),
  ('n5-1a0aec6793', 'あなたは夜よく寝れませんか。', 'あなたは{夜|よる}よく{寝|ね}れませんか。', NULL, 'Don''t you sleep well at night?', 231522),
  ('n5-1a0aec6793', '夜にスタジオでは電気をつけない。', '{夜|よる}にスタジオでは{電気|でんき}をつけない。', NULL, 'I don''t switch on the light in my studio at night.', 79751),
  ('n5-83da293775', 'それを言われると弱いなあ。', NULL, NULL, 'That sure puts me on the spot.', 204593),
  ('n5-83da293775', 'そのひもはとても弱い。', 'そのひもはとても{弱|よわ}い。', NULL, 'The string is very weak.', 212696),
  ('n5-61fd50f12e', '来月タクシー料金があがります。', '{来月|らいげつ}タクシー{料金|りょうきん}があがります。', NULL, 'Taxi fares will go up next month.', 78688),
  ('n5-61fd50f12e', 'おじは来月で２年間ずっとニューヨークにいることになる。', 'おじは{来月|らいげつ}で２{年間|ねんかん}ずっとニューヨークにいることになる。', NULL, 'My uncle will have been in New York for two years next month.', 227704),
  ('n5-7a4ef637be', '来週ヨーロッパへ行くつもりなんです。', NULL, NULL, 'I''m going to Europe next week.', 191765),
  ('n5-7a4ef637be', '来週はうちへいらしゃいませんか。', '{来週|らいしゅう}はうちへいらしゃいませんか。', NULL, 'Won''t you come and see me next week?', 78640),
  ('n5-c68f2caa2f', 'あなたは来年この本を読むことが出来るでしょう。', 'あなたは{来年|らいねん}この{本|ほん}を{読|よ}むことが{出来|でき}るでしょう。', NULL, 'You will be able to read this book next year.', 231498),
  ('n5-c68f2caa2f', '私は来年の四月に学校に入っています。', '{私|わたし}は{来年|らいねん}の{四月|しがつ}に{学校|がっこう}に{入|はい}っています。', NULL, 'I will be in high school next April.', 152393),
  ('n5-670f2dd0dc', 'そのニュースはラジオで聞いたよ。', 'そのニュースはラジオで{聞|き}いたよ。', NULL, 'I heard the news on the radio.', 212803),
  ('n5-670f2dd0dc', 'ラジオをつけてもかまいませんか。', NULL, NULL, 'Do you mind if I turn on the radio?', 192597),
  ('n5-924572e50c', '確かに今の日本では、「ラジカセ」はもう古い言葉なのかもしれない。', NULL, NULL, 'The word "raji-kase", meaning radio cassette in Japan, is probably more of an antiquated term by now.', 1174918),
  ('n5-a45af4ed89', 'どうもごりっぱな言いわけだよ。', NULL, NULL, 'That is a fine excuse.', 201196),
  ('n5-a45af4ed89', '彼は大学の学業をりっぱにやっている。', '{彼|かれ}は{大学|だいがく}の{学業|がくぎょう}をりっぱにやっている。', NULL, 'He is doing well in his college work.', 102449),
  ('n5-dc7d39c7af', '留学生も入れるのかしら。', '{留学生|りゅうがくせい}も{入|い}れるのかしら。', NULL, 'Can foreign students be in the club?', 237462),
  ('n5-dc7d39c7af', '３人の中国人留学生がその大学に入学が許された。', NULL, NULL, 'Three Chinese students were admitted to the college.', 235285),
  ('n5-0139a208fe', '両親は二人ともまだ生きています。', '{両親|りょうしん}は{二人|ふたり}ともまだ{生|い}きています。', NULL, 'Both the parents are still living.', 77996),
  ('n5-0139a208fe', '両親とも生きているわけではない。', '{両親|りょうしん}とも{生|い}きているわけではない。', NULL, 'Neither of my parents is alive.', 78052),
  ('n5-ee85169acd', 'これらのりんごは料理用にもってこいだ。', 'これらのりんごは{料理|りょうり}{用|よう}にもってこいだ。', NULL, 'These apples are good cookers.', 217962),
  ('n5-ee85169acd', 'なんておいしい料理なんでしょう。', 'なんておいしい{料理|りょうり}なんでしょう。', NULL, 'This dish is terrific.', 198943),
  ('n5-2ba96bef9a', 'いつ旅行においでになりますか。', 'いつ{旅行|りょこう}においでになりますか。', NULL, 'When will you go on a journey?', 228596),
  ('n5-2ba96bef9a', 'お金がないので、プチッと旅行。', 'お{金|かね}がないので、プチッと{旅行|りょこう}。', NULL, 'As I don''t have the money, it''ll just be a short trip.', 76816),
  ('n5-f7a15687a1', '冷蔵庫の中にバターが２ポンドある。', '{冷蔵庫|れいぞうこ}の{中|なか}にバターが２ポンドある。', NULL, 'There are two pounds of butter in the icebox.', 77638),
  ('n5-f7a15687a1', '冷蔵庫にバターはありますか。', '{冷蔵庫|れいぞうこ}にバターはありますか。', NULL, 'Is there any butter in the refrigerator?', 77648),
  ('n5-0455201fe6', 'ステレオにレコードをかけてください。', NULL, NULL, 'Put a record on the stereo.', 214601),
  ('n5-0455201fe6', 'ＣＤはすっかりレコードに取って代わった。', 'ＣＤはすっかりレコードに{取|と}って{代|か}わった。', NULL, 'Compact discs have entirely taken the place of phonograph records.', 234862),
  ('n5-31893e4378', 'あのレストランはサービスがよい。', NULL, NULL, 'They give good service at that restaurant.', 231226),
  ('n5-31893e4378', 'このレストランのカレーはうまいよ。', NULL, NULL, 'The curry at this restaurant is good.', 223009),
  ('n5-d23f06249a', 'あなたはいつピアノの練習をしますか。', 'あなたはいつピアノの{練習|れんしゅう}をしますか。', NULL, 'When do you practice the piano?', 232827),
  ('n5-d23f06249a', '後でテニスの練習があるんだよ。', '{後|あと}でテニスの{練習|れんしゅう}があるんだよ。', NULL, 'I have tennis practice later.', 174352);
INSERT INTO seed_vocab_examples (source_key, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) VALUES
  ('n5-5fc0f979e6', '廊下の突き当たりで火事が起きました。', '{廊下|ろうか}の{突|つ}き{当|あ}たりで{火事|かじ}が{起|お}きました。', NULL, 'There''s a fire down the hall.', 77345),
  ('n5-5fc0f979e6', '花子はカツカツと音を立てながら廊下を歩いてきた。', NULL, NULL, 'Hanako walked through the hallway making a clicking sound.', 173664),
  ('n5-f9ccc7bfdf', '私は毎朝六時に起きます。', NULL, NULL, 'I get up at six every morning.', 152733),
  ('n5-f9ccc7bfdf', 'もうすぐ六時です。', NULL, NULL, 'It''s nearly six o''clock.', 519112),
  ('n5-38249a2dd2', 'ワイシャツにボタンをつけて。', NULL, NULL, 'Would you sew a button on my shirt?', 192073),
  ('n5-38249a2dd2', '母はワイシャツのしわをアイロンでのばすのにいそがしかった。', '{母|はは}はワイシャツのしわをアイロンでのばすのにいそがしかった。', NULL, 'I found my mother busy ironing out some shirts.', 83028),
  ('n5-640761cb8b', '「彼女は若いですか」「はい」', '「{彼女|かのじょ}は{若|わか}いですか」「はい」', NULL, '"Is she young?" "Yes, she is."', 236166),
  ('n5-640761cb8b', '若いときは、よくサッカーをした。', '{若|わか}いときは、よくサッカーをした。', NULL, 'I often played soccer when I was young.', 156108),
  ('n5-ecee43eb04', 'ボブがいつ来日したか分からない。', 'ボブがいつ{来日|らいにち}したか{分|わ}からない。', NULL, 'I don''t know when Bob came to Japan.', 196088),
  ('n5-ecee43eb04', 'どっちがどっちなのか分からないよ。', 'どっちがどっちなのか{分|わ}からないよ。', NULL, 'I don''t know which is which.', 200695),
  ('n5-0ca0de9dea', '電話するのを忘れてごめんなさい。', '{電話|でんわ}するのを{忘|わす}れてごめんなさい。', NULL, 'Please forgive me for forgetting to call you.', 124723),
  ('n5-0ca0de9dea', '名前をすっかり忘れてしまいました。', '{名前|なまえ}をすっかり{忘|わす}れてしまいました。', NULL, 'I''ve completely forgotten its name.', 80772),
  ('n5-d5c2e69813', '私は泳げません。', '{私|わたくし}は{泳|およ}げません。', NULL, 'I don''t know how to swim.', 159334),
  ('n5-d5c2e69813', '彼女は私の子供の世話をしてくれる。', NULL, NULL, 'She takes care of my children.', 89373),
  ('n5-b1d440d4e1', 'わたしを川のむこうに渡してください。', 'わたしを{川|かわ}のむこうに{渡|わた}してください。', NULL, 'Please take me across the river.', 191763),
  ('n5-b1d440d4e1', '走者がリレーでバトンを渡さなければなりません。', '{走者|そうしゃ}がリレーでバトンを{渡|わた}さなければなりません。', NULL, 'A runner must pass the baton in a relay race.', 192496),
  ('n5-78255b9860', '一行はアメリカへ渡った。', '{一行|いっこう}はアメリカへ{渡|わた}った。', NULL, 'The party crossed over to America.', 190628),
  ('n5-78255b9860', 'ここを渡りましょう。', 'ここを{渡|わた}りましょう。', NULL, 'Let''s cross here.', 224241),
  ('n5-13b6dbec03', 'これは悪い話ではないでしょう？', 'これは{悪|わる}い{話|はなし}ではないでしょう？', NULL, 'This isn''t an unappealing proposition, is it?', 74724),
  ('n5-13b6dbec03', 'すいません。あなたに悪いことをしました。', 'すいません。あなたに{悪|わる}いことをしました。', NULL, 'I''m sorry. I did you wrong.', 215129);
