  (4, '六', 'Lục', 'Sáu', 'N5', 4),
  (5, '日', 'Nhật', 'Mặt trời, ngày', 'N5', 4),
  (6, '目', 'Mục', 'Mắt', 'N5', 5),
  (7, '三', 'Tam', 'Ba', 'N5', 3),
  (8, '手', 'Thủ', 'Tay', 'N5', 4),
  (9, '十', 'Thập', 'Mười', 'N5', 2),
  (10, '千', 'Thiên', 'Một nghìn', 'N5', 3),
