INSERT INTO vocabulary (source_key, word, reading, romaji, level, jmdict_id)
SELECT source_key, word, reading, romaji, level, jmdict_id FROM seed_vocab
ON DUPLICATE KEY UPDATE word=VALUES(word), reading=VALUES(reading), romaji=VALUES(romaji), level=VALUES(level), jmdict_id=VALUES(jmdict_id), is_deleted=FALSE;
DELETE vm FROM vocabulary_meanings vm JOIN vocabulary v ON v.id=vm.vocabulary_id JOIN seed_vocab s ON s.source_key=v.source_key;
DELETE vp FROM vocabulary_parts_of_speech vp JOIN vocabulary v ON v.id=vp.vocabulary_id JOIN seed_vocab s ON s.source_key=v.source_key;
DELETE vf FROM vocabulary_forms vf JOIN vocabulary v ON v.id=vf.vocabulary_id JOIN seed_vocab s ON s.source_key=v.source_key;
DELETE ve FROM vocabulary_examples ve JOIN vocabulary v ON v.id=ve.vocabulary_id JOIN seed_vocab s ON s.source_key=v.source_key;
INSERT INTO vocabulary_meanings (vocabulary_id, language_code, meaning, sort_order) SELECT v.id, s.language_code, s.meaning, s.sort_order FROM seed_vocab_meanings s JOIN vocabulary v ON v.source_key=s.source_key;
INSERT INTO vocabulary_parts_of_speech (vocabulary_id, code, label) SELECT v.id, s.code, s.label FROM seed_vocab_pos s JOIN vocabulary v ON v.source_key=s.source_key;
INSERT INTO vocabulary_forms (vocabulary_id, form_type, value) SELECT v.id, s.form_type, s.value FROM seed_vocab_forms s JOIN vocabulary v ON v.source_key=s.source_key;
INSERT INTO vocabulary_examples (vocabulary_id, japanese_text, furigana, meaning_vi, meaning_en, tatoeba_id) SELECT v.id, s.japanese_text, s.furigana, s.meaning_vi, s.meaning_en, s.tatoeba_id FROM seed_vocab_examples s JOIN vocabulary v ON v.source_key=s.source_key;
INSERT INTO kanji (source_id, `character`, han_viet, meaning, jlpt_level, stroke_count)
SELECT source_id, `character`, han_viet, meaning, jlpt_level, stroke_count FROM seed_kanji
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id), `character`=VALUES(`character`), han_viet=VALUES(han_viet), meaning=VALUES(meaning), jlpt_level=VALUES(jlpt_level), stroke_count=VALUES(stroke_count), is_deleted=FALSE;
DELETE kr FROM kanji_readings kr JOIN kanji k ON k.id=kr.kanji_id JOIN seed_kanji s ON s.source_id=k.source_id;
DELETE krr FROM kanji_radicals krr JOIN kanji k ON k.id=krr.kanji_id JOIN seed_kanji s ON s.source_id=k.source_id;
DELETE kv FROM kanji_vocabulary kv JOIN kanji k ON k.id=kv.kanji_id JOIN seed_kanji s ON s.source_id=k.source_id;
INSERT INTO kanji_readings (kanji_id, reading_type, reading, sort_order) SELECT k.id, s.reading_type, s.reading, s.sort_order FROM seed_kanji_readings s JOIN kanji k ON k.source_id=s.source_id;
INSERT IGNORE INTO radicals (`character`) SELECT DISTINCT radical_character FROM seed_kanji_radicals;
INSERT IGNORE INTO kanji_radicals (kanji_id, radical_id) SELECT k.id, r.id FROM seed_kanji_radicals s JOIN kanji k ON k.source_id=s.source_id JOIN radicals r ON r.`character`=s.radical_character;
INSERT IGNORE INTO kanji_vocabulary (kanji_id, vocabulary_id) SELECT k.id, v.id FROM seed_kanji_vocab s JOIN kanji k ON k.source_id=s.source_id JOIN vocabulary v ON v.source_key=s.source_key;
DROP TEMPORARY TABLE seed_vocab, seed_vocab_meanings, seed_vocab_pos, seed_vocab_forms, seed_vocab_examples, seed_kanji, seed_kanji_readings, seed_kanji_radicals, seed_kanji_vocab;

