-- Readable SQL fixtures for 21 grammar points, examples, lessons and exercises.
-- The Node seeder uses the same titles, so running both seeders will not duplicate them.
DROP TEMPORARY TABLE IF EXISTS seed_grammar_samples;
CREATE TEMPORARY TABLE seed_grammar_samples (
  seed_order TINYINT UNSIGNED NOT NULL PRIMARY KEY,
  level ENUM('N5','N4','N3','N2','N1') NOT NULL,
  title VARCHAR(255) NOT NULL,
  form VARCHAR(255) NOT NULL,
  meaning VARCHAR(1000) NOT NULL,
  structure TEXT NOT NULL,
  japanese_text TEXT NOT NULL,
  reading TEXT NOT NULL,
  meaning_vi TEXT NOT NULL,
  meaning_en TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO seed_grammar_samples
  (seed_order, level, title, form, meaning, structure, japanese_text, reading, meaning_vi, meaning_en) VALUES
  (1, 'N5', 'Câu danh từ với は và です', 'N は N です', 'Giới thiệu hoặc xác định một người/vật bằng câu khẳng định lịch sự.', 'Danh từ + は + danh từ + です', '私は学生です。', 'わたしはがくせいです。', 'Tôi là học sinh/sinh viên.', 'I am a student.'),
  (2, 'N5', 'Phủ định danh từ với じゃありません', 'N は N じゃありません', 'Phủ định lịch sự cho câu danh từ trong hội thoại.', 'Danh từ + は + danh từ + じゃありません', '田中さんは先生じゃありません。', 'たなかさんはせんせいじゃありません。', 'Anh Tanaka không phải là giáo viên.', 'Mr. Tanaka is not a teacher.'),
  (3, 'N5', 'Hỏi địa điểm với どこ', 'N は どこですか', 'Hỏi vị trí của người hoặc vật.', 'Danh từ + は + どこ + ですか', '駅はどこですか。', 'えきはどこですか。', 'Nhà ga ở đâu?', 'Where is the station?'),
  (4, 'N5', 'Tân ngữ với trợ từ を', 'N を Vます', 'Đánh dấu tân ngữ trực tiếp của động từ.', 'Danh từ + を + động từ', '水を飲みます。', 'みずをのみます。', 'Tôi uống nước.', 'I drink water.'),
  (5, 'N5', 'Thời điểm với に', 'Thời gian に Vます', 'Nêu thời điểm cụ thể mà hành động diễn ra.', 'Mốc thời gian + に + động từ', '七時に起きます。', 'しちじにおきます。', 'Tôi thức dậy lúc bảy giờ.', 'I get up at seven.'),
  (6, 'N4', 'Hai hành động đồng thời với ながら', 'Vます bỏ ます + ながら', 'Diễn tả cùng một chủ thể làm hai hành động đồng thời.', 'Động từ thể ます bỏ ます + ながら + hành động chính', '音楽を聞きながら勉強します。', 'おんがくをききながらべんきょうします。', 'Tôi vừa nghe nhạc vừa học.', 'I study while listening to music.'),
  (7, 'N4', 'Liệt kê hành động tiêu biểu với たり', 'Vたり、Vたりします', 'Nêu một số hành động tiêu biểu trong nhiều hoạt động.', 'Động từ thể た + り, lặp lại rồi します', '日曜日は本を読んだり、散歩したりします。', 'にちようびはほんをよんだり、さんぽしたりします。', 'Chủ nhật tôi đọc sách, đi dạo và làm những việc khác.', 'On Sundays I read and take walks, among other things.'),
  (8, 'N4', 'Kinh nghiệm với たことがあります', 'V thể た + ことがあります', 'Hỏi hoặc kể về trải nghiệm đã từng có.', 'Động từ thể た + ことがあります', '京都へ行ったことがあります。', 'きょうとへいったことがあります。', 'Tôi đã từng đến Kyoto.', 'I have been to Kyoto.'),
  (9, 'N4', 'Đưa ra lời khuyên với ほうがいい', 'Vた + ほうがいいです', 'Đề xuất một việc nên làm dựa trên tình huống.', 'Động từ thể た + ほうがいいです', '早く寝たほうがいいです。', 'はやくねたほうがいいです。', 'Bạn nên ngủ sớm.', 'You should go to bed early.'),
  (10, 'N4', 'Lý do với ので', '普通形 + ので', 'Nêu lý do với sắc thái giải thích nhẹ nhàng, lịch sự.', 'Thể thường + ので; tính từ な/danh từ + な + ので', '雨が降っているので、出かけません。', 'あめがふっているので、でかけません。', 'Vì trời đang mưa nên tôi không ra ngoài.', 'Because it is raining, I will not go out.'),
  (11, 'N3', 'Hoàn tất hoặc tiếc nuối với てしまう', 'Vて + しまう', 'Diễn tả sự hoàn tất hoặc điều ngoài ý muốn tùy ngữ cảnh.', 'Động từ thể て + しまう', '財布を忘れてしまいました。', 'さいふをわすれてしまいました。', 'Tôi lỡ quên ví mất rồi.', 'I accidentally forgot my wallet.'),
  (12, 'N3', 'Duy trì thói quen với ようにする', 'Vる / Vない + ようにする', 'Nói về nỗ lực chủ động tạo hoặc duy trì một thói quen.', 'Động từ thể từ điển hoặc phủ định + ようにする', '毎日、日本語を読むようにしています。', 'まいにち、にほんごをよむようにしています。', 'Tôi cố gắng đọc tiếng Nhật mỗi ngày.', 'I try to read Japanese every day.'),
  (13, 'N3', 'Quyết định với ことにする', 'Vる / Vない + ことにする', 'Diễn tả quyết định do chính người nói đưa ra.', 'Động từ thể từ điển hoặc phủ định + ことにする', '来月から毎朝走ることにしました。', 'らいげつからまいあさはしることにしました。', 'Tôi đã quyết định chạy bộ mỗi sáng từ tháng sau.', 'I decided to run every morning starting next month.'),
  (14, 'N3', 'Hành động vừa mới xảy ra với たばかり', 'Vた + ばかり', 'Nhấn mạnh hành động vừa mới hoàn thành theo cảm nhận người nói.', 'Động từ thể た + ばかりです', '昼ご飯を食べたばかりです。', 'ひるごはんをたべたばかりです。', 'Tôi vừa mới ăn trưa xong.', 'I have just eaten lunch.'),
  (15, 'N3', 'Phủ định suy luận khái quát với わけではない', '普通形 + わけではない', 'Đính chính rằng một điều không đúng trong mọi trường hợp.', 'Thể thường + わけではない', '高い物がいつもいいわけではありません。', 'たかいものがいつもいいわけではありません。', 'Đồ đắt tiền không phải lúc nào cũng tốt.', 'Expensive things are not always good.'),
  (16, 'N2', 'Suy luận mạnh với に違いない', '普通形 + に違いない', 'Đưa ra kết luận có cơ sở với mức độ tin chắc cao.', 'Thể thường + に違いない; danh từ/tính từ な + に違いない', '毎日練習したから、上達したに違いない。', 'まいにちれんしゅうしたから、じょうたつしたにちがいない。', 'Vì luyện tập mỗi ngày nên chắc hẳn đã tiến bộ.', 'They must have improved because they practiced every day.'),
  (17, 'N2', 'Đối chiếu với に対して', 'N / 普通形 + のに対して', 'So sánh hai phía có đặc điểm hoặc tình huống đối lập.', 'Danh từ + に対して; mệnh đề + のに対して', '兄は社交的なのに対して、弟は静かです。', 'あにはしゃこうてきなのにたいして、おとうとはしずかです。', 'Trái với anh trai hòa đồng, em trai lại trầm tính.', 'Whereas the older brother is sociable, the younger brother is quiet.'),
  (18, 'N2', 'Nhượng bộ với ものの', '普通形 + ものの', 'Nêu sự thật đầu tiên nhưng kết quả sau đó không như mong đợi.', 'Thể thường + ものの; tính từ な/danh từ + である + ものの', '薬を飲んだものの、まだ熱があります。', 'くすりをのんだものの、まだねつがあります。', 'Tuy đã uống thuốc nhưng tôi vẫn còn sốt.', 'Although I took medicine, I still have a fever.'),
  (19, 'N2', 'Nguy cơ với おそれがある', 'N / Vる + おそれがある', 'Cảnh báo một khả năng xấu có thể xảy ra.', 'Danh từ hoặc động từ thể từ điển + おそれがある', '台風で電車が止まるおそれがあります。', 'たいふうででんしゃがとまるおそれがあります。', 'Có nguy cơ tàu điện ngừng chạy do bão.', 'There is a risk that trains will stop because of the typhoon.'),
  (20, 'N2', 'Khả năng dẫn đến hậu quả với かねない', 'Vます bỏ ます + かねない', 'Cảnh báo một hành động có thể dẫn tới hậu quả tiêu cực.', 'Động từ thể ます bỏ ます + かねない', '確認しないと、大きな間違いを起こしかねません。', 'かくにんしないと、おおきなまちがいをおこしかねません。', 'Nếu không kiểm tra, có thể gây ra sai sót lớn.', 'Failing to check could cause a serious mistake.'),
  (21, 'N1', 'Bị buộc phải làm với を余儀なくされる', 'N + を余儀なくされる', 'Văn phong trang trọng diễn tả việc bị hoàn cảnh buộc phải làm điều gì.', 'Danh từ chỉ hành động + を余儀なくされる', '大雨のため、試合は中止を余儀なくされました。', 'おおあめのため、しあいはちゅうしをよぎなくされました。', 'Do mưa lớn, trận đấu buộc phải hủy.', 'The match was forced to be canceled because of heavy rain.');

INSERT INTO grammar_points (title, level, form, meaning, structure)
SELECT s.title, s.level, s.form, s.meaning, s.structure
FROM seed_grammar_samples s
WHERE NOT EXISTS (
  SELECT 1 FROM grammar_points g WHERE g.title=s.title AND g.level=s.level
);

INSERT INTO grammar_examples (grammar_point_id, japanese_text, reading, meaning_vi, meaning_en, sort_order)
SELECT g.id, s.japanese_text, s.reading, s.meaning_vi, s.meaning_en, 1
FROM seed_grammar_samples s
JOIN grammar_points g ON g.title=s.title AND g.level=s.level
WHERE NOT EXISTS (
  SELECT 1 FROM grammar_examples ge WHERE ge.grammar_point_id=g.id AND ge.sort_order=1
);

INSERT INTO lessons (title, level, duration, summary, objectives, content, course_id)
SELECT CONCAT('Ngữ pháp ', s.level, ' · ', s.title), s.level, '20 phút',
  CONCAT(s.form, ': ', s.meaning), CONCAT('Nhận biết và vận dụng ', s.form, ' trong câu đúng ngữ cảnh.'),
  CONCAT('CẤU TRÚC\n', s.structure, '\n\nÝ NGHĨA\n', s.meaning, '\n\nVÍ DỤ\n',
    s.japanese_text, '\n', s.meaning_vi, '\n\nCÁCH HỌC\nĐọc ví dụ, xác định phần ngữ pháp và tự đặt một câu tương tự.'),
  c.id
FROM seed_grammar_samples s
JOIN courses c ON c.level=s.level
WHERE NOT EXISTS (
  SELECT 1 FROM lessons l
  WHERE l.title=CONCAT('Ngữ pháp ', s.level, ' · ', s.title) AND l.level=s.level
);

INSERT INTO exercises (title, level, topic, question_count, description)
SELECT CONCAT('Luyện tập ', s.level, ' · ', s.title), s.level, 'Ngữ pháp', 1,
  CONCAT('Luyện nhận biết mẫu ', s.form, ' và cách dùng: ', s.meaning)
FROM seed_grammar_samples s
WHERE NOT EXISTS (
  SELECT 1 FROM exercises e
  WHERE e.title=CONCAT('Luyện tập ', s.level, ' · ', s.title) AND e.level=s.level
);

INSERT INTO exercise_questions (exercise_id, question_text, question_type, sort_order, explanation)
SELECT e.id, CONCAT('Mẫu nào phù hợp với ý nghĩa: “', s.meaning, '”'),
  'multiple_choice', 1, CONCAT(s.form, ': ', s.structure)
FROM seed_grammar_samples s
JOIN exercises e ON e.title=CONCAT('Luyện tập ', s.level, ' · ', s.title) AND e.level=s.level
WHERE NOT EXISTS (
  SELECT 1 FROM exercise_questions q WHERE q.exercise_id=e.id AND q.sort_order=1
);

INSERT INTO exercise_choices (question_id, choice_text, is_correct, sort_order)
SELECT q.id,
  CASE choices.option_order
    WHEN 1 THEN s.form
    WHEN 2 THEN IF(s.form='N は N です', 'N を Vます', 'N は N です')
    WHEN 3 THEN IF(s.form='Vて + しまう', 'Vる + ことにする', 'Vて + しまう')
    WHEN 4 THEN IF(s.form='普通形 + に違いない', 'N は どこですか', '普通形 + に違いない')
  END,
  choices.option_order=1, choices.option_order
FROM seed_grammar_samples s
JOIN exercises e ON e.title=CONCAT('Luyện tập ', s.level, ' · ', s.title) AND e.level=s.level
JOIN exercise_questions q ON q.exercise_id=e.id AND q.sort_order=1
CROSS JOIN (
  SELECT 1 AS option_order UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
) choices
WHERE NOT EXISTS (
  SELECT 1 FROM exercise_choices ec
  WHERE ec.question_id=q.id AND ec.sort_order=choices.option_order
);

DROP TEMPORARY TABLE seed_grammar_samples;
